window.LK_VEHICULES = [{"id":"albany-emperor","nom":"Emperor","marque":"Albany","cat":"berline","st":"vu","insp":"Cadillac Sedan de Ville 1977-1980","src":"Offizielle Screenshots","search":"albany emperor cadillac sedan de ville 1977-1980","txt":"Albany war schon immer die Marke der großen, komfortablen amerikanischen Straßenkreuzer, und der Emperor ist ihr Archetyp: lange Motorhaube, breite C-Säule, weiches Fahrwerk. Der Cadillac Sedan de Ville von 1977 bis 1980, dessen Look er übernimmt, war ein alternder Chefwagen und wurde mit den Jahren zur Gebrauchtlimousine schlechthin: die, die man in Arbeitervierteln vor sich hin rosten sieht. Die von Rockstar veröffentlichten Screenshots zeigen ihn am Straßenrand in Vice City geparkt.","reel":"https://www.google.com/search?tbm=isch&q=Cadillac%20Sedan%20de%20Ville","reelNom":"Cadillac Sedan de Ville","slot":"americain","thumb":"/img/schemas/albany-emperor.svg"},{"id":"albany-primo","nom":"Primo","marque":"Albany","cat":"berline","st":"vu","insp":"Pontiac Bonneville Ende der 80er","src":"Erster Trailer","search":"albany primo pontiac bonneville fin des annees 80","txt":"Der Primo hat in der Reihe einen besonderen Platz: eine Limousine ohne Prestige, aber technisch solide, und die liebste Basis der Tuner. Der Pontiac Bonneville der späten 80er, der ihn inspiriert, war ein großer amerikanischer Serienwagen, massenhaft gebaut und zehn Jahre später billig weiterverkauft, was ihn zu einer beliebten Basis für die Lowrider-Kultur in Südflorida machte. Im ersten Trailer fährt er in einer Straßenszene vorbei.","reel":"https://www.google.com/search?tbm=isch&q=Pontiac%20Bonneville%20fin%20des%20ann%C3%A9es%2080","reelNom":"Pontiac Bonneville Ende der 80er","slot":"americain","thumb":"/img/schemas/albany-primo.svg"},{"id":"albany-primo-custom","nom":"Primo Custom","marque":"Albany","cat":"berline","st":"comm","insp":"Buick Regal","src":"Zuordnung der Community","search":"albany primo custom buick regal","txt":"Gleiche Karosserie wie der Primo, als Lowrider aufgebaut: tiefergelegtes Fahrwerk, schmale Speichenfelgen, Effektlack. Diese Variante passt am besten zu Vice City, wo die kubanische und puerto-ricanische Lowrider-Szene ein starkes kulturelles Merkmal ist. Die Werkstatt Rideout Customs, zu sehen auf unserer Karte, ist genau die Art Ort, an dem so ein Umbau entstehen würde. Modell von Rockstar für Leonida nicht bestätigt.","reel":"https://www.google.com/search?tbm=isch&q=Buick%20Regal","reelNom":"Buick Regal","slot":"americain","thumb":"/img/schemas/albany-primo-custom.svg"},{"id":"benefactor-schafter-v12","nom":"Schafter V12","marque":"Benefactor","cat":"berline","st":"vu","insp":"Brabus E V12","src":"Erster Trailer","search":"benefactor schafter v12 brabus e v12","txt":"Der Schafter V12 ist eine Sportlimousine von Benefactor. Die hier gewählte Zuordnung ist der Brabus E V12. Er ist aus dem ersten Trailer über eine Community-Identifizierung erfasst; seinen Namen nennt Rockstar dort nicht.","reel":"https://www.google.com/search?tbm=isch&q=Brabus%20E%20V12","reelNom":"Brabus E V12","thumb":"/img/schemas/benefactor-schafter-v12.svg"},{"id":"karin-asterope","nom":"Asterope","marque":"Karin","cat":"berline","st":"comm","insp":"Toyota Camry der vorherigen Generation","txt":"Japanische Familienlimousine, jahrzehntelang das meistverkaufte Auto ihres Segments in den USA. Die neuere GZ-Variante ist bereits in dieser Datenbank.","search":"karin asterope toyota camry generation precedente","src":"Zuordnung der Community","reel":"https://www.google.com/search?tbm=isch&q=Toyota%20Camry%20pr%C3%A9c%C3%A9dente","reelNom":"Toyota Camry, Vorgängergeneration","slot":"japonais","thumb":"/img/schemas/karin-asterope.svg"},{"id":"karin-asterope-gz","nom":"Asterope GZ","marque":"Karin","cat":"berline","st":"vu","insp":"Toyota Camry (XV30)","src":"Offizielle Screenshots","search":"karin asterope gz toyota camry (xv30)","txt":"Karin ist die japanische Volumenmarke des Universums, und der Asterope ist ihr Auto für jedermann. Der Toyota Camry, an den er angelehnt ist, ist seit Jahrzehnten die meistverkaufte Limousine der USA, gerade weil er nie auffällt. Das Kürzel GZ deutet auf eine etwas höhere Ausstattung hin. Er taucht auf den offiziellen Screenshots auf, untergegangen im Alltagsverkehr von Leonida.","reel":"https://www.google.com/search?tbm=isch&q=Toyota%20Camry%20(XV30)","reelNom":"Toyota Camry (XV30)","slot":"japonais","thumb":"/img/schemas/karin-asterope-gz.svg"},{"id":"lampadati-feroci","nom":"Feroci","marque":"Karin","cat":"berline","st":"vu","insp":"Lexus GS 300 erste Generation","txt":"Der Feroci basiert auf dem Lexus GS 300 der ersten Generation, gezeichnet von Giugiaro und 1993 vorgestellt. Er war Toyotas Versuch, eine Premium-Sportlimousine gegen die deutsche Konkurrenz zu etablieren: tadellose Verarbeitung, Reihensechszylinder und eine Zurückhaltung, die ihn den Verkaufserfolg kostete. Karin ist der Toyota des Universums, deshalb ist die Zuordnung schlüssig.","search":"karin feroci lexus gs 300 premiere generation","src":"Extended Look","reel":"https://www.google.com/search?tbm=isch&q=Lexus%20GS%20300","reelNom":"Lexus GS 300","slot":"japonais","thumb":"/img/schemas/lampadati-feroci.svg"},{"id":"karin-intruder","nom":"Intruder","marque":"Karin","cat":"berline","st":"vu","insp":"Infiniti Q45/I30","src":"Erster Trailer","search":"karin intruder infiniti q45/i30","txt":"Der Intruder orientiert sich am Infiniti Q45 und am I30, den Oberklasse-Limousinen, die Nissan in den USA gegen Lexus ins Rennen schickte. Die Rechnung ging nie richtig auf: gut gebaut, komfortabel, aber ohne starke Identität neben den Deutschen. Deshalb findet man sie heute billig als Gebrauchtwagen, genau die Art Auto, die die Parkplätze von Vice City füllt, ohne dass jemand hinsieht.","reel":"https://www.google.com/search?tbm=isch&q=Infiniti%20Q45%2FI30","reelNom":"Infiniti Q45/I30","slot":"japonais","thumb":"/img/schemas/karin-intruder.svg"},{"id":"audi-a7-rs7","nom":"A7 RS7","marque":"Unbekannte Marke","cat":"berline","st":"vu","insp":"Audi RS7 zweite Generation","src":"Erster Trailer","txt":"Deutsche Hochleistungs-Coupé-Limousine, vier Türen und abfallende Dachlinie. Der RS7 ist der Inbegriff des schnellen Autos, das niemandem auffällt: fünfhundert PS unter der Karosserie einer Vertreterlimousine. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue a7 rs7 audi rs7 deuxieme generation","reel":"https://www.google.com/search?tbm=isch&q=Audi%20RS7","reelNom":"Audi RS7","slot":"europeen","thumb":"/img/schemas/audi-a7-rs7.svg"},{"id":"honda-accord-10","nom":"Accord","marque":"Unbekannte Marke","cat":"berline","st":"vu","insp":"Honda Accord zehnte Generation","src":"Offizielle Screenshots","txt":"Japanische Großserienlimousine, zehnte Generation. Der Accord ist eines der meistverkauften Autos der US-Geschichte, so sehr, dass er im Stadtbild unsichtbar geworden ist. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue accord honda accord dixieme generation","reel":"https://www.google.com/search?tbm=isch&q=Honda%20Accord%20dixi%C3%A8me","reelNom":"Honda Accord, zehnte Gen.","slot":"japonais","thumb":"/img/schemas/honda-accord-10.svg"},{"id":"mercedes-c-w205","nom":"C-Klasse","marque":"Unbekannte Marke","cat":"berline","st":"vu","insp":"Mercedes-Benz C-Klasse W205","src":"Zweiter Trailer","txt":"Deutsche Kompaktlimousine der Generation W205, gebaut von 2014 bis 2021. Dieses Modell hat den Mercedes-Stern einem breiten Publikum zugänglich gemacht und ist im ganzen Westen der Dienstwagen schlechthin. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue classe c mercedes-benz classe c w205","reel":"https://www.google.com/search?tbm=isch&q=Mercedes-Benz%20Classe%20C%20W205","reelNom":"Mercedes-Benz C-Klasse W205","slot":"europeen","thumb":"/img/schemas/mercedes-c-w205.svg"},{"id":"chevrolet-impala-10","nom":"Impala","marque":"Unbekannte Marke","cat":"berline","st":"vu","insp":"Chevrolet Impala zehnte Generation","src":"Erster Trailer","txt":"Große amerikanische Limousine der 2000er, letzte Generation mit Frontantrieb. Massenhaft von Flotten, Autovermietungen und Behörden gekauft, ist er das anonyme Auto in Reinform. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue impala chevrolet impala dixieme generation","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Impala%20dixi%C3%A8me","reelNom":"Chevrolet Impala, zehnte Gen.","slot":"americain","thumb":"/img/schemas/chevrolet-impala-10.svg"},{"id":"volkswagen-jetta","nom":"Jetta","marque":"Unbekannte Marke","cat":"berline","st":"vu","insp":"Volkswagen Jetta","src":"Extended Look","txt":"Deutsche Kompaktlimousine, die Stufenheckversion des Golf, sehr beliebt in den USA, wo sich Schrägheckmodelle schlecht verkaufen. Im Extended Look entdeckt. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue jetta volkswagen jetta","reel":"https://www.google.com/search?tbm=isch&q=Volkswagen%20Jetta","reelNom":"Volkswagen Jetta","slot":"europeen","thumb":"/img/schemas/volkswagen-jetta.svg"},{"id":"chrysler-lebaron-town-country","nom":"LeBaron Town & Country","marque":"Unbekannte Marke","cat":"berline","st":"vu","insp":"Chrysler LeBaron Town & Country 1986-1988","src":"Extended Look","txt":"Familienkombi mit Holzimitat an den Flanken, im Extended Look entdeckt. Diese Vinylverkleidung in Nussbaumoptik ist eine amerikanische Tradition, die bis in die 40er zurückreicht und die Chrysler bis in die 80er weitergeführt hat. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue lebaron town & country chrysler lebaron town & country 1986-1988","reel":"https://www.google.com/search?tbm=isch&q=Chrysler%20LeBaron%20Town%20%26%20Country","reelNom":"Chrysler LeBaron Town & Country","slot":"americain","thumb":"/img/schemas/chrysler-lebaron-town-country.svg"},{"id":"oceanic","nom":"Oceanic","marque":"Unbekannte Marke","cat":"berline","st":"comm","insp":"Chevrolet Bel Air 1950","txt":"Amerikanische Nachkriegslimousine, runde Kotflügel, zweiteilige Windschutzscheibe. Sie gehört zur Generation vor den Heckflossen, der Zeit der ersten großen Umzugswellen nach Florida.","search":"marque inconnue oceanic chevrolet bel air 1950","src":"Zuordnung der Community","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Bel%20Air%201950","reelNom":"Chevrolet Bel Air 1950","slot":"americain","thumb":"/img/schemas/oceanic.svg"},{"id":"buick-regal-6","nom":"Regal","marque":"Unbekannte Marke","cat":"berline","st":"vu","insp":"Buick Regal sechste Generation","src":"Erster Trailer","txt":"Amerikanische Mittelklasselimousine der 2010er, abgeleitet von einem europäischen Opel. Buick versuchte damals, eine alternde Kundschaft zu verjüngen, ohne echten Erfolg. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue regal buick regal sixieme generation","reel":"https://www.google.com/search?tbm=isch&q=Buick%20Regal","reelNom":"Buick Regal","slot":"americain","thumb":"/img/schemas/buick-regal-6.svg"},{"id":"chrysler-sebring-dodge-stratus","nom":"Sebring","marque":"Unbekannte Marke","cat":"berline","st":"vu","insp":"Chrysler Sebring zweite Generation","src":"Offizielle Screenshots","txt":"Großserienlimousine der späten 2000er, Zwilling des Dodge Stratus. Oft als eines der missratensten amerikanischen Autos seiner Zeit genannt, was ihn nicht daran hinderte, die Flotten der Autovermieter zu füllen. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue sebring chrysler sebring deuxieme generation","reel":"https://www.google.com/search?tbm=isch&q=Chrysler%20Sebring","reelNom":"Chrysler Sebring","slot":"americain","thumb":"/img/schemas/chrysler-sebring-dodge-stratus.svg"},{"id":"buick-skylark-6","nom":"Skylark","marque":"Unbekannte Marke","cat":"berline","st":"vu","insp":"Buick Skylark sechste Generation","src":"Zweiter Trailer","txt":"Amerikanische Kompaktlimousine der 80er, in sehr großer Serie auf der X-Plattform von General Motors gebaut. Diese Autos sind schlecht gealtert und stehen heute in den Straßen der Arbeiterviertel, was gut zur Kulisse von Leonida passt. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue skylark buick skylark sixieme generation","reel":"https://www.google.com/search?tbm=isch&q=Buick%20Skylark","reelNom":"Buick Skylark","slot":"americain","thumb":"/img/schemas/buick-skylark-6.svg"},{"id":"chevrolet-sonic","nom":"Sonic","marque":"Unbekannte Marke","cat":"berline","st":"vu","insp":"Chevrolet Sonic","src":"Erster Trailer","txt":"Der Chevrolet Sonic, ein Einstiegs-Kleinwagen, der in den USA zu Hunderttausenden verkauft wurde. Bescheidener Vierzylinder, karger Innenraum: das Auto vom ersten Gehalt oder aus der Mietwagenflotte. Rockstar lässt ihn vorerst ohne Namen im Spiel. Der erste Trailer zeigt ihn an einer Ampel, zwischen Alltagsautos.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Sonic","reelNom":"Chevrolet Sonic","search":"marque inconnue sonic chevrolet sonic","slot":"americain","thumb":"/img/schemas/chevrolet-sonic.svg"},{"id":"ford-taurus","nom":"Taurus","marque":"Unbekannte Marke","cat":"berline","st":"vu","insp":"Ford Taurus","src":"Extended Look","txt":"Amerikanische Familienlimousine, einer der größten Verkaufserfolge von Ford in den 80ern und 90ern. Die abgerundete Karosserie sorgte bei der Vorstellung für Aufsehen, bevor sie zum Branchenstandard wurde. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue taurus ford taurus","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Taurus","reelNom":"Ford Taurus","slot":"americain","thumb":"/img/schemas/ford-taurus.svg"},{"id":"obey-tailgater","nom":"Tailgater","marque":"Obey","cat":"berline","st":"vu","insp":"Audi A6","src":"Erster Trailer","search":"obey tailgater audi a6","txt":"Obey ist die deutsche Premiummarke der Reihe, und der Tailgater ihre Einstiegslimousine: das Auto der Führungskraft, die gerade aufsteigt. Der Audi A6, der ihn inspiriert, ist ein nüchterner Reisewagen mit Allradantrieb, gemacht, um ohne Emotionen Kilometer zu fressen. Ein Profil, das zu den Geschäftsvierteln von Downtown passt. Der erste Trailer zeigt ihn kurz, für die Dauer einer Verkehrsszene.","reel":"https://www.google.com/search?tbm=isch&q=Audi%20A6","reelNom":"Audi A6","slot":"europeen","thumb":"/img/schemas/obey-tailgater.svg"},{"id":"obey-tailgater-s","nom":"Tailgater S","marque":"Obey","cat":"berline","st":"vu","insp":"Audi RS3 Sedan","src":"Offizielle Screenshots","search":"obey tailgater s audi rs3 sedan","txt":"Verlängerte und besser ausgestattete Variante des Tailgater, nach dem Vorbild des Verhältnisses zwischen Audi A4 und A6: gleiche Formensprache, mehr Länge, mehr dezentes Chrom. Das ist die Vorstandslimousine, die mit Chauffeur. Auf den offiziellen Screenshots sticht er heraus, auf seinen Serienfelgen stehend.","reel":"https://www.google.com/search?tbm=isch&q=Audi%20RS3%20Sedan","reelNom":"Audi RS3 Sedan","slot":"europeen","thumb":"/img/schemas/obey-tailgater-s.svg"},{"id":"schyster-pmp-700","nom":"PMP 700","marque":"Schyster","cat":"berline","st":"vu","insp":"Chrysler 300 zweite Generation","src":"Erster Trailer","search":"schyster pmp 700 chrysler 300 deuxieme generation","txt":"Der PMP 700 ist eine Vorstandslimousine mit Chauffeur, im Stil der großen, verlängerten deutschen Limousinen. Solche Fahrzeuge übernehmen die Transfers zwischen Flughafen und Strandhotels, ein enormes Verkehrsaufkommen in Miami. Der erste Trailer zeigt ihn schräg von hinten, im Schritttempo in einer Kolonne.","medias":["trailer-1-vehicles-027"],"imageAlts":{"trailer-1-vehicles-027":"Große grüne Limousine rechts im Vordergrund, erster Trailer von GTA VI bei 00:27"},"reel":"https://www.google.com/search?tbm=isch&q=Chrysler%20300","reelNom":"Chrysler 300","slot":"americain","thumb":"/img/officiel/trailer-1-vehicles-027-480.webp"},{"id":"vapid-stanier-moderne","nom":"Stanier","marque":"Vapid","cat":"berline","st":"vu","insp":"Ford Crown Victoria","src":"Erster Trailer","txt":"Der aktuelle Stanier, nicht zu verwechseln mit dem Stanier ’55 der Ultimate Edition. Er basiert auf dem Ford Crown Victoria, einer Limousine mit Heckantrieb und Leiterrahmen, die über zwanzig Jahre lang als amerikanisches Polizeiauto und Taxi diente. Unverwüstlich, schwer und sofort wiederzuerkennen.","search":"vapid stanier ford crown victoria","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Crown%20Victoria","reelNom":"Ford Crown Victoria","slot":"americain","thumb":"/img/schemas/vapid-stanier-moderne.svg"},{"id":"vapid-stanier","nom":"Stanier ’55","marque":"Vapid","cat":"berline","st":"officiel","insp":"1956 Ford Fairlane Club Sedan","src":"Erster Trailer","vues":[],"credit":"Offizieller Screenshot von Rockstar Games","search":"vapid stanier ’55 1956 ford fairlane club sedan","txt":"Der Stanier ’55 ist eines der wenigen Fahrzeuge, deren Namen Rockstar veröffentlicht hat, im Vintage Vice City Pack. Unsere offiziellen Screenshots zeigen die zweifarbige Karosserie in Gelb und Creme, die Heckflossen, die Scheibenradkappen und den Schriftzug auf dem Kotflügel. Der Ford Fairlane von 1955, dessen Linien er übernimmt, gehört zu jener Nachkriegsgeneration, in der amerikanische Autos anfingen, wie Flugzeuge auszusehen. Eine logische Wahl für eine Stadt, die ihre Nostalgie pflegt.","edition":"Pre-Order","medias":["55-vapid-stanier-01","55-vapid-stanier-02","55-vapid-stanier-03","55-vapid-stanier-04"],"vuesDeclarees":["profil","arriere","interieur","detail"],"reel":"https://www.google.com/search?tbm=isch&q=1956%20Ford%20Fairlane%20Club%20Sedan","reelNom":"1956 Ford Fairlane Club Sedan","slot":"americain","thumb":"/img/officiel/55-vapid-stanier-01-480.webp"},{"id":"declasse-stratum","nom":"Stratum","marque":"Zirconium","cat":"berline","st":"vu","insp":"Honda Accord Kombi","txt":"Familienkombi aus der Großserie, senkrechte Heckklappe und Dachreling. Der Stratum ist das Hintergrundfahrzeug schlechthin: überall da, nirgends bemerkt, und damit perfekt, wenn man nicht auffallen will.","search":"zirconium stratum honda accord station wagon","src":"Erster Trailer","reel":"https://www.google.com/search?tbm=isch&q=Honda%20Accord%20station%20wagon","reelNom":"Honda Accord Kombi","slot":"japonais","thumb":"/img/schemas/declasse-stratum.svg"},{"id":"albany-manana","nom":"Manana","marque":"Albany","cat":"sport","st":"vu","insp":"Buick LeSabre, Cadillac Eldorado","src":"Offizielle Screenshots","search":"albany manana buick lesabre, cadillac eldorado","txt":"Der Manana ist ein amerikanisches Personal-Luxury-Coupé der 70er: zwei Türen, Vinyldach, durchgehende Sitzbank vorne. In der Reihe war er schon immer ein Auto aus dem Viertel, oft als Lowrider unterwegs. Seine riesigen Abmessungen für nur zwei Sitzplätze fassen die Epoche, die ihn hervorgebracht hat, ziemlich gut zusammen. Die offiziellen Screenshots zeigen ihn bei einem Tuner, bereit zum Lackieren.","medias":["rideout-customs-mod-shop-01","ultimate-edition-rideout-customs-02","ultimate-edition-rideout-customs-03"],"imageAlts":{"ultimate-edition-rideout-customs-02":"Roter Innenraum des Autos aus der Screenshot-Serie zu Rideout Customs","ultimate-edition-rideout-customs-03":"Höhergelegtes gelbes Coupé in der Werkstatt Rideout Customs, als Albany Manana identifiziert"},"reel":"https://www.google.com/search?tbm=isch&q=Buick%20LeSabre","reelNom":"Buick LeSabre","slot":"americain","thumb":"/img/officiel/rideout-customs-mod-shop-01-480.webp"},{"id":"albany-v-str","nom":"V-STR","marque":"Albany","cat":"sport","st":"vu","insp":"2019 Cadillac CTS-V","src":"Offizielle Screenshots","search":"albany v-str 2019 cadillac cts-v","txt":"Der V-STR ist Albanys Versuch eines modernen Sportwagens, was für eine Marke großer amerikanischer Straßenkreuzer ein ziemlicher Spagat ist. Das Kürzel erinnert an die Drei-Buchstaben-Bezeichnungen, die Cadillac zum Markenzeichen seiner Performance-Modelle gemacht hat. Die offiziellen Screenshots zeigen ihn im Stand, den Kühlergrill gut im Blick.","reel":"https://www.google.com/search?tbm=isch&q=2019%20Cadillac%20CTS-V","reelNom":"2019 Cadillac CTS-V","slot":"americain","thumb":"/img/schemas/albany-v-str.svg"},{"id":"annis-elegy-retro-custom","nom":"Elegy Retro Custom","marque":"Annis","cat":"sport","st":"vu","insp":"Nissan Skyline GT-R","src":"Erster Trailer","search":"annis elegy retro custom nissan skyline gt-r","txt":"Der Elegy ist die Tuning-Ikone der Reihe, und seine Version Retro Custom ist die begehrteste. Der Nissan Skyline R32, der ihn inspiriert, ist ein Denkmal der japanischen Autokultur: Allradantrieb, Reihensechszylinder und eine totale Dominanz im Motorsport, die ihm den Spitznamen Godzilla einbrachte. Der Zusatz Custom bedeutet ein Breitbau-Kit und einen Heckflügel. Der erste Trailer schickt ihn eine Avenue hinunter, auf Scheinwerferhöhe gefilmt.","reel":"https://www.google.com/search?tbm=isch&q=Nissan%20Skyline%20GT-R","reelNom":"Nissan Skyline GT-R","slot":"japonais","thumb":"/img/schemas/annis-elegy-retro-custom.svg"},{"id":"benefactor-schafter-lwb","nom":"Schafter LWB","marque":"Benefactor","cat":"sport","st":"comm","insp":"Mercedes-Benz E-Klasse mit langem Radstand","txt":"Version des Schafter mit langem Radstand, eher für den Fond gedacht als für den Fahrer. In Leonida ist das das Auto von jemandem, der sich fahren lässt: Hotels in Vice City, Flughafen, Abende in der Stadt.","search":"benefactor schafter lwb mercedes-benz classe e allongee","src":"Zuordnung der Community","reel":"https://www.google.com/search?tbm=isch&q=Mercedes-Benz%20Classe%20E%20allong%C3%A9e","reelNom":"Mercedes-Benz E-Klasse mit langem Radstand","slot":"europeen","thumb":"/img/schemas/benefactor-schafter-lwb.svg"},{"id":"bravado-banshee","nom":"Banshee","marque":"Bravado","cat":"sport","st":"vu","insp":"Dodge Viper","src":"Zweiter Trailer","search":"bravado banshee dodge viper","txt":"Der Banshee ist seit Vice City eine Konstante der Reihe, mit einer Silhouette, die sofort an die Dodge Viper denken lässt. Die Dodge Viper der fünften Generation, deren Proportionen er übernimmt, ist ein brutales Auto: ein Lkw-V10 in einem schmalen Chassis, ohne die elektronischen Helfer, die moderne Sportwagen zahm machen. Der Banshee ist aus dem zweiten Trailer erfasst, ohne einen von Rockstar genannten Namen.","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Viper","reelNom":"Dodge Viper","slot":"americain","thumb":"/img/schemas/bravado-banshee.svg"},{"id":"bravado-buffalo","nom":"Buffalo","marque":"Bravado","cat":"sport","st":"vu","insp":"Dodge Charger","src":"Erster Trailer","search":"bravado buffalo dodge charger","txt":"Bravado ist die Marke der amerikanischen Muscle-Cars, und der Buffalo ihre Sportlimousine: vier Türen, großer Motor, steifes Chassis. In den früheren Teilen fuhren ihn Polizei und Gangs gleichermaßen, was viel über seine Positionierung sagt. Im ersten Trailer fährt er durch den Verkehr von Vice City.","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Charger","reelNom":"Dodge Charger","slot":"americain","thumb":"/img/schemas/bravado-buffalo.svg"},{"id":"bravado-buffalo-s","nom":"Buffalo S","marque":"Bravado","cat":"sport","st":"comm","insp":"Dodge Charger SRT8","txt":"Die sportliche Variante des Buffalo: aggressivere Seitenschweller, Lufthutze auf der Motorhaube, geschlossene Felgen. Beim echten Charger markierte diese Version in den 2010ern die Rückkehr des viertürigen amerikanischen Muscle-Cars.","search":"bravado buffalo s dodge charger srt8","src":"Zuordnung der Community","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Charger%20SRT8","reelNom":"Dodge Charger SRT8","slot":"americain","thumb":"/img/schemas/bravado-buffalo-s.svg"},{"id":"coil-raiden","nom":"Raiden","marque":"Coil","cat":"sport","st":"vu","insp":"Tesla Model S","src":"Offizielle Screenshots","txt":"Die Elektrolimousine von Coil, nach dem Vorbild des Tesla Model S: kein Kühlergrill, bündige Türgriffe, volles Drehmoment, sobald du den Fuß von der Bremse nimmst. Das ist das Auto der wohlhabenden Viertel von Leonida. Die offiziellen Screenshots zeigen den Wagen an einer Ladesäule.","reel":"https://www.google.com/search?tbm=isch&q=Tesla%20Model%20S","reelNom":"Tesla Model S","search":"coil raiden tesla model s","slot":"americain","thumb":"/img/schemas/coil-raiden.svg"},{"id":"declasse-mamba-gt","nom":"Mamba GT","marque":"Declasse","cat":"sport","st":"officiel","insp":"Shelby Daytona Coupé","src":"Ultimate Edition","vues":[],"credit":"Offizieller Screenshot von Rockstar Games","search":"declasse mamba gt shelby daytona coupe","txt":"Der Mamba GT gehört zu den Modellen, die Rockstar im Katalog der Ultimate Edition namentlich nennt. Das Shelby Daytona Coupé, dessen Look er übernimmt, ist ein Rennwagen, der aus einer Vorgabe entstand: eine offene Cobra so aerodynamisch zu machen, dass sie auf der Geraden der 24 Stunden von Le Mans mithalten konnte. Das Ergebnis, mit abgeschnittenem Heck und flacher Windschutzscheibe, gewann 1965 die Weltmeisterschaft. Nur sechs Exemplare wurden gebaut.","edition":"Ultimate Edition","medias":["classic-car-collection-04"],"vuesDeclarees":["detail"],"reel":"https://www.google.com/search?tbm=isch&q=Shelby%20Daytona%20Coup%C3%A9","reelNom":"Shelby Daytona Coupé","slot":"americain","thumb":"/img/officiel/classic-car-collection-04-480.webp"},{"id":"dinka-blista-compact","nom":"Blista Compact","marque":"Dinka","cat":"sport","st":"vu","insp":"Honda CR-X erste Generation","src":"Offizielle Screenshots","search":"dinka blista compact honda cr-x premiere generation","txt":"Dinka ist der Honda des Universums, und der Blista Compact sein sportlicher Stadtflitzer. Die Formel ist bekannt: kleines, leichtes Auto, spritziger Motor, Frontantrieb, erschwinglicher Preis. Es ist die Art Fahrzeug, die eher die Straßen füllt als die Sammlergaragen. Die offiziellen Screenshots zeigen ihn an einer Wohnstraße.","reel":"https://www.google.com/search?tbm=isch&q=Honda%20CR-X","reelNom":"Honda CR-X","slot":"japonais","thumb":"/img/schemas/dinka-blista-compact.svg"},{"id":"dinka-sugoi","nom":"Sugoi","marque":"Dinka","cat":"sport","st":"vu","insp":"Honda Civic Type R FK8","src":"Offizielle Screenshots","search":"dinka sugoi honda civic type r fk8","txt":"Als sportliche Kompaktlimousine trägt der Sugoi einen Namen, der auf Japanisch schlicht „super“ bedeutet, was viel über den Humor der Reihe verrät. Er gehört zu jener Familie von Serienautos, die sich mit ein paar Teilen in Rennstreckenmaschinen verwandeln lassen. Die offiziellen Screenshots zeigen ihn mit aufgestelltem Heckflügel, bereit für die Gerade.","reel":"https://www.google.com/search?tbm=isch&q=Honda%20Civic%20R%20FK8","reelNom":"Honda Civic R FK8","slot":"japonais","thumb":"/img/schemas/dinka-sugoi.svg"},{"id":"cheval-vectre","nom":"Vectre","marque":"Emperor","cat":"sport","st":"vu","insp":"Lexus RC F","src":"Zweiter Trailer","search":"emperor vectre lexus rc f","txt":"Emperor ist die gehobene japanische Marke des Universums, und der Vectre ihr kompaktes Sportcoupé. Der Name klingt wie eine Verkürzung von Vektor, im aerodynamischen Stil, den die Hersteller in den 90ern liebten. Der zweite Trailer zeigt ihn kurz in einer Szene im Stadtverkehr.","reel":"https://www.google.com/search?tbm=isch&q=Lexus%20RC%20F","reelNom":"Lexus RC F","slot":"japonais","thumb":"/img/schemas/cheval-vectre.svg"},{"id":"enus-paragon-r","nom":"Paragon R","marque":"Enus","cat":"sport","st":"vu","insp":"2018 Bentley Continental GT","src":"Offizielle Screenshots","search":"enus paragon r 2018 bentley continental gt","txt":"Der Paragon R basiert auf dem Bentley Continental GT von 2018: viersitziges Coupé, W12 unter der Haube und ein Gewicht, das kein Fahrwerk ganz vergessen machen kann. Das ist Grand Touring im wörtlichen Sinn: das Auto, das einen Kontinent in einem Zug durchquert. Der Zusatz R kennzeichnet die geschärfte Version.","reel":"https://www.google.com/search?tbm=isch&q=2018%20Bentley%20Continental%20GT","reelNom":"2018 Bentley Continental GT","slot":"europeen","thumb":"/img/schemas/enus-paragon-r.svg"},{"id":"enus-windsor","nom":"Windsor","marque":"Enus","cat":"sport","st":"vu","insp":"Rolls-Royce Wraith","src":"Zweiter Trailer","txt":"Das Luxuscoupé von Enus, nach dem Vorbild des Rolls-Royce Wraith: gegenläufig öffnende Türen, endlose Motorhaube, senkrechter Kühlergrill wie ein Giebel. Das ist das Auto, das man vor einem Hotel parkt, um beim Aussteigen gesehen zu werden. Der zweite Trailer zeigt ihn im Profil.","reel":"https://www.google.com/search?tbm=isch&q=Rolls-Royce%20Wraith","reelNom":"Rolls-Royce Wraith","search":"enus windsor rolls-royce wraith","slot":"europeen","thumb":"/img/schemas/enus-windsor.svg"},{"id":"fathom-fr36","nom":"FR36","marque":"Fathom","cat":"sport","st":"vu","insp":"Infiniti G35 (V35)","src":"Extended Look","txt":"Das Coupé von Fathom basiert auf dem Infiniti G35 der ersten Generation, einem japanischen Hecktriebler, der dank seines Sechszylinders und seines ausgewogenen Chassis zum Tuning-Klassiker wurde. Der Extended Look zeigt ihn in einer Werkstatt, mit offener Motorhaube.","reel":"https://www.google.com/search?tbm=isch&q=Infiniti%20G35%20(V35)","reelNom":"Infiniti G35 (V35)","search":"fathom fr36 infiniti g35 (v35)","slot":"japonais","thumb":"/img/schemas/fathom-fr36.svg"},{"id":"grotti-carbonizzare","nom":"Carbonizzare","marque":"Grotti","cat":"sport","st":"vu","insp":"Ferrari F12berlinetta und Aston Martin V12 Zagato","src":"Erster Trailer","search":"grotti carbonizzare ferrari f12berlinetta et aston martin v12 zagato","txt":"Grotti ist der Ferrari der Reihe, und der Carbonizzare sein Gran Turismo mit Frontmotor. Der Ferrari F12, der ihm als Vorbild dient, ist ein Straßenauto der besonderen Art: ein V12-Saugmotor mit über siebenhundert PS in einer Karosserie, die geformt ist, um die Luft zu lenken statt sie zu durchschneiden. Der erste Trailer zeigt ihn kurz bei einer schnellen Vorbeifahrt.","medias":["trailer-1-vehicles-025"],"imageAlts":{"trailer-1-vehicles-025":"Rotes Cabrio mit einer stehenden Beifahrerin, erster Trailer von GTA VI bei 00:25"},"reel":"https://www.google.com/search?tbm=isch&q=Ferrari%20F12berlinetta","reelNom":"Ferrari F12berlinetta","slot":"europeen","thumb":"/img/officiel/trailer-1-vehicles-025-480.webp"},{"id":"grotti-cheetah-classic","nom":"Cheetah ’95","marque":"Grotti","cat":"sport","st":"officiel","insp":"Ferrari Testarossa und 512 BB","src":"Ultimate Edition","vues":[],"credit":"Offizieller Screenshot von Rockstar Games","search":"grotti cheetah ’95 ferrari testarossa et 512 bb","txt":"Rockstar nennt den Cheetah ’95 im Katalog der Ultimate Edition beim Namen, und unsere vier offiziellen Screenshots zeigen die weiße Karosserie mit roten Streifen, das rote Lederinterieur, die Fünfspeichenfelgen und den Schriftzug am Heck. Der Ferrari Testarossa, dessen Designmerkmale er übernimmt, wurde für eine ganze Generation zum Inbegriff von Miami: Seine seitlichen Lamellen und seine ausladenden Proportionen haben mehr für das Image der Stadt getan als jede Tourismuskampagne.","edition":"Ultimate Edition","medias":["95-grotti-cheetah-01","95-grotti-cheetah-02","95-grotti-cheetah-03","95-grotti-cheetah-04"],"vuesDeclarees":["face","profil","arriere","interieur"],"reel":"https://www.google.com/search?tbm=isch&q=Ferrari%20Testarossa","reelNom":"Ferrari Testarossa","slot":"europeen","thumb":"/img/officiel/95-grotti-cheetah-01-480.webp"},{"id":"grotti-itali-gto","nom":"Itali GTO","marque":"Grotti","cat":"sport","st":"vu","insp":"Ferrari 812 Superfast","src":"Erster Trailer","search":"grotti itali gto ferrari 812 superfast","txt":"Der Itali GTO übernimmt die Formensprache des Ferrari 812 Superfast: V12 vorne, kompaktes Heck, gebündelte Endrohre. Der 812 ist einer der letzten Ferrari mit Zwölfzylinder-Saugmotor, was ihm heute bei Sammlern einen besonderen Status verleiht. Ob er nach Leonida kommt, ist noch zu bestätigen.","reel":"https://www.google.com/search?tbm=isch&q=Ferrari%20812%20Superfast","reelNom":"Ferrari 812 Superfast","slot":"europeen","thumb":"/img/schemas/grotti-itali-gto.svg"},{"id":"grotti-itali-rsx","nom":"Itali RSX","marque":"Grotti","cat":"sport","st":"vu","insp":"Ferrari SF90 Stradale","src":"Extended Look","txt":"Der technisch fortschrittlichste Grotti der Modellpalette, nach dem Vorbild des Ferrari SF90 Stradale und seines Plug-in-Hybridantriebs. Abgeschnittenes Heck, hoch liegende Doppelendrohre, aktive Aerodynamik am Heck. Der Extended Look schickt ihn über ein freies Stück Autobahn.","reel":"https://www.google.com/search?tbm=isch&q=Ferrari%20SF90%20Stradale","reelNom":"Ferrari SF90 Stradale","search":"grotti itali rsx ferrari sf90 stradale","slot":"europeen","thumb":"/img/schemas/grotti-itali-rsx.svg"},{"id":"invetero-coquette","nom":"Coquette","marque":"Invetero","cat":"sport","st":"vu","insp":"Corvette C7, 2014 Corvette Stingray","src":"Zweiter Trailer","search":"invetero coquette corvette c7, 2014 corvette stingray","txt":"Der Coquette von Invetero wird der Corvette C7 zugeordnet, genauer der Corvette Stingray von 2014. Diese Inspiration unterscheidet die Seite von den anderen Coquette-Generationen. Unsere Datenbank erfasst ihn im zweiten Trailer, ohne von Rockstar genannten Namen.","reel":"https://www.google.com/search?tbm=isch&q=Corvette%20C7","reelNom":"Corvette C7","slot":"americain","thumb":"/img/schemas/invetero-coquette.svg"},{"id":"invetero-coquette-d10","nom":"Coquette D10","marque":"Invetero","cat":"sport","st":"vu","insp":"Chevrolet Corvette C8","src":"Erster Trailer","search":"invetero coquette d10 chevrolet corvette c8","txt":"Eine kompromisslose Version des Coquette im Geist der Corvette Z06: breitere Spur, deutlicher Abtrieb, schärferer Motor. Die Z06 ist traditionell die Variante, die Chevrolet für die Rennstrecke vorsieht, ohne ihr die Straßenzulassung zu nehmen. Im ersten Trailer taucht er plötzlich in einer Nachtszene auf.","medias":["extended-look-coquette-d10"],"imageAlts":{"extended-look-coquette-d10":"Rotes Cabrio links im Vordergrund, Standbild aus An Extended Look"},"reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Corvette%20C8","reelNom":"Chevrolet Corvette C8","slot":"americain","thumb":"/img/officiel/extended-look-coquette-d10-480.webp"},{"id":"annis-futo","nom":"Futo","marque":"Karin","cat":"sport","st":"vu","insp":"Toyota AE86 Levin","src":"Erster Trailer","search":"karin futo toyota ae86 levin","txt":"Der Futo ist der leichte Hecktriebler schlechthin: den wählt man, um Driften zu lernen, nicht um schnell zu fahren. Der Toyota AE86, dessen Silhouette er übernimmt, hat eine enorme Aura: Als erschwingliches, ausgewogenes Auto wurde er zum Symbol des Amateur-Drifts, bevor die Manga-Kultur ihn berühmt machte. Im ersten Trailer fährt er im Hintergrund vorbei, mit eingeschalteten Rücklichtern.","reel":"https://www.google.com/search?tbm=isch&q=Toyota%20AE86%20Levin","reelNom":"Toyota AE86 Levin","slot":"japonais","thumb":"/img/schemas/annis-futo.svg"},{"id":"karin-sultan","nom":"Sultan","marque":"Karin","cat":"sport","st":"vu","insp":"Lexus IS, Mitsubishi Lancer Evo VI, Subaru Impreza","src":"Erster Trailer","search":"karin sultan lexus is, mitsubishi lancer evo vi, subaru impreza","txt":"Der Sultan ist die allradgetriebene Sportlimousine der Reihe, der Rallyewagen für die Stadt. Der Subaru Impreza WRX, der ihn inspiriert, hat sich seinen Ruf auf den Wertungsprüfungen der Rallye-Weltmeisterschaft erarbeitet, mit seinem Boxermotor und seiner unerschütterlichen Straßenlage auf schlechtem Belag. Sein Auftritt ist im ersten Trailer erfasst; der Name Sultan bleibt eine Community-Identifizierung.","reel":"https://www.google.com/search?tbm=isch&q=Lexus%20IS","reelNom":"Lexus IS","slot":"japonais","thumb":"/img/schemas/karin-sultan.svg"},{"id":"karin-sultan-rs","nom":"Sultan RS","marque":"Karin","cat":"sport","st":"comm","insp":"Getunter Subaru Impreza WRX STI","txt":"Der Sultan in Rallye-Ausführung: Kotflügelverbreiterungen, Heckflügel, Lufthutze auf der Motorhaube. Das ist die Referenz unter den japanischen Kompakten mit Allradantrieb, die eine ganze Tuning-Generation geprägt hat.","search":"karin sultan rs subaru impreza wrx sti preparee","src":"Zuordnung der Community","reel":"https://www.google.com/search?tbm=isch&q=Subaru%20Impreza%20WRX%20STI","reelNom":"Subaru Impreza WRX STI","slot":"japonais","thumb":"/img/schemas/karin-sultan-rs.svg"},{"id":"maibatsu-penumbra","nom":"Penumbra","marque":"Maibatsu","cat":"sport","st":"vu","insp":"Mitsubishi Eclipse, Audi TT","src":"Zweiter Trailer","search":"maibatsu penumbra mitsubishi eclipse, audi tt","txt":"Maibatsu ist die japanische Volumenmarke der Reihe, und der Penumbra ihr sportliches Einstiegscoupé. Er gehört zu jener Kategorie von Autos, die die Silhouette eines Sportwagens bieten, ohne die passende Technik, was sie zu sehr beliebten Tuning-Basen macht. Der zweite Trailer zeigt ihn im Verkehr, mit eingeschalteten Scheinwerfern.","reel":"https://www.google.com/search?tbm=isch&q=Mitsubishi%20Eclipse","reelNom":"Mitsubishi Eclipse","slot":"japonais","thumb":"/img/schemas/maibatsu-penumbra.svg"},{"id":"maibatsu-penumbra-ff","nom":"Penumbra FF","marque":"Maibatsu","cat":"sport","st":"vu","insp":"Mitsubishi Eclipse zweite Generation, Eagle Talon zweite Generation","src":"Extended Look","txt":"Der Penumbra als Fronttriebler, nach dem Mitsubishi Eclipse der zweiten Generation und seinem Zwilling, dem Eagle Talon. Klappscheinwerfer, verglaste Heckklappe: das Tuning-Auto der 90er schlechthin. Der Extended Look zeigt ihn bei voller Beschleunigung.","reel":"https://www.google.com/search?tbm=isch&q=Mitsubishi%20Eclipse","reelNom":"Mitsubishi Eclipse","search":"maibatsu penumbra ff mitsubishi eclipse deuxieme generation, eagle talon deuxieme generation","slot":"japonais","thumb":"/img/schemas/maibatsu-penumbra-ff.svg"},{"id":"mercedes-cle-a236","nom":"CLE-Klasse Cabriolet","marque":"Unbekannte Marke","cat":"sport","st":"vu","insp":"Mercedes-Benz CLE-Klasse (A236)","src":"Zweiter Trailer","txt":"Das CLE Cabriolet von Mercedes-Benz, das auf einen Schlag die offenen Versionen von C-Klasse und E-Klasse ersetzt hat. Stoffverdeck, vier enge Sitze, der Stern mitten im Kühlergrill. Es taucht im zweiten Trailer auf, ohne einen Namen im Spiel erhalten zu haben.","reel":"https://www.google.com/search?tbm=isch&q=Mercedes-Benz%20Classe%20CLE%20(A236)","reelNom":"Mercedes-Benz CLE-Klasse (A236)","search":"marque inconnue classe cle cabriolet mercedes-benz classe cle (a236)","slot":"europeen","thumb":"/img/schemas/mercedes-cle-a236.svg"},{"id":"cadillac-eldorado-1959","nom":"Eldorado 1959","marque":"Unbekannte Marke","cat":"sport","st":"vu","insp":"Cadillac Eldorado 1959","src":"Zweiter Trailer","txt":"Der Cadillac Eldorado von 1959, der mit den riesigen Heckflossen und den Rückleuchten in Raketenform, Symbol des Amerikas vor der Ölkrise. Ihm wurden weder ein Name im Spiel noch ein fiktiver Hersteller zugewiesen. Im zweiten Trailer rollt er im Schritttempo an der Uferpromenade entlang.","reel":"https://www.google.com/search?tbm=isch&q=Cadillac%20Eldorado%201959","reelNom":"Cadillac Eldorado 1959","search":"marque inconnue eldorado 1959 cadillac eldorado 1959","slot":"americain","thumb":"/img/schemas/cadillac-eldorado-1959.svg"},{"id":"kellison-j4","nom":"Kellison J4","marque":"Unbekannte Marke","cat":"sport","st":"vu","insp":"Kellison J4","src":"Offizielle Screenshots","txt":"Ein handgefertigter Roadster aus Glasfaser aus den 60ern, in Kleinserie von einem kalifornischen Karosseriebauer gebaut, um am Wochenende Rennen zu fahren. Rockstar hat ihm keinen Namen im Spiel gegeben. Die offiziellen Screenshots zeigen ihn im Stand, mit geschlossener Motorhaube.","medias":["ultimate-edition-02","classic-car-collection-05"],"imageAlts":{"ultimate-edition-02":"Jason und Lucia vor dem grünen Coupé, das im Bild zur Ultimate Edition einem Kellison J4 zugeordnet wird"},"reel":"https://www.google.com/search?tbm=isch&q=Kellison%20J4","reelNom":"Kellison J4","search":"marque inconnue kellison j4 kellison j4","thumb":"/img/officiel/ultimate-edition-02-480.webp"},{"id":"lincoln-mark-viii","nom":"Mark VIII","marque":"Unbekannte Marke","cat":"sport","st":"vu","insp":"Lincoln Mark VIII","src":"Extended Look","txt":"Das große Personal-Luxury-Coupé von Lincoln, das letzte der Mark-Reihe, mit abgerundetem Heck und einem Leuchtenband über die ganze Breite. Der Name im Spiel wurde nicht bekannt gegeben. Der Extended Look zeigt es kurz im nächtlichen Verkehr, mit eingeschalteten Lichtern.","reel":"https://www.google.com/search?tbm=isch&q=Lincoln%20Mark%20VIII","reelNom":"Lincoln Mark VIII","search":"marque inconnue mark viii lincoln mark viii","slot":"americain","thumb":"/img/schemas/lincoln-mark-viii.svg"},{"id":"buick-reatta-convertible","nom":"Reatta Cabrio","marque":"Unbekannte Marke","cat":"sport","st":"vu","insp":"Buick Reatta Convertible","src":"Zweiter Trailer","txt":"Ein amerikanisches Cabrio-Coupé der späten 80er, nach dem Buick Reatta: kantige Linien, Stoffverdeck, zwei Sitze und keiner mehr. Rockstar hat ihm noch keinen Namen im Spiel gegeben. Im zweiten Trailer steht es geparkt mit Blick aufs Meer.","reel":"https://www.google.com/search?tbm=isch&q=Buick%20Reatta%20Convertible","reelNom":"Buick Reatta Convertible","search":"marque inconnue reatta decapotable buick reatta convertible","slot":"americain","thumb":"/img/schemas/buick-reatta-convertible.svg"},{"id":"obey-8f-drafter","nom":"8F Drafter","marque":"Obey","cat":"sport","st":"vu","insp":"2018 Audi RS5 Coupe","src":"Offizielle Screenshots","search":"obey 8f drafter 2018 audi rs5 coupe","txt":"Der 8F Drafter ist das viertürige Coupé von Obey, jene Zwitterkategorie, die die deutschen Hersteller erfunden haben, um den Komfort einer Limousine mit der Linie eines Coupés zu verkaufen. Der Name spielt auf das Windschattenfahren im Rennsport an, wenn sich ein Auto in den Windschatten eines anderen setzt. Die offiziellen Screenshots zeigen ihn im Profil, mit einem Parkplatz im Hintergrund.","reel":"https://www.google.com/search?tbm=isch&q=2018%20Audi%20RS5%20Coupe","reelNom":"2018 Audi RS5 Coupe","slot":"europeen","thumb":"/img/schemas/obey-8f-drafter.svg"},{"id":"overflod-omnis-e-gt","nom":"Omnis e-GT","marque":"Obey","cat":"sport","st":"vu","insp":"Audi e-Tron GT","txt":"Elektrisches Grand-Touring-Coupé, ohne sichtbaren Auspuff und ohne Lufteinlass für einen Motor. In Leonida sind Elektrofahrzeuge und Ladesäulen bestätigt, was dieser Kategorie eine echte Funktion im Spiel gibt.","search":"obey omnis e-gt audi e-tron gt","src":"Erster Trailer","reel":"https://www.google.com/search?tbm=isch&q=Audi%20e-Tron%20GT","reelNom":"Audi e-Tron GT","slot":"europeen","thumb":"/img/schemas/overflod-omnis-e-gt.svg"},{"id":"ocelot-jugular","nom":"Jugular","marque":"Ocelot","cat":"sport","st":"vu","insp":"Jaguar XE SV Project 8","src":"Erster Trailer","search":"ocelot jugular jaguar xe sv project 8","txt":"Ocelot ist der Jaguar des Universums, und der Jugular seine Sportlimousine. Der Jaguar XE SV Project 8, dessen Proportionen er übernimmt, ist eine auf die Spitze getriebene Serienlimousine: feststehender Heckflügel, verbreiterte Spur und ein Kompressor-V8 für die Rennstrecke. Im ersten Trailer durchquert er in wenigen Bildern eine Straßenszene.","reel":"https://www.google.com/search?tbm=isch&q=Jaguar%20XE%20SV%20Project%208","reelNom":"Jaguar XE SV Project 8","slot":"europeen","thumb":"/img/schemas/ocelot-jugular.svg"},{"id":"pegassi-infernus-classic","nom":"Infernus Classic","marque":"Pegassi","cat":"sport","st":"vu","insp":"Lamborghini Diablo, Cizeta V16T, Ferrari Testarossa","src":"Extended Look","search":"pegassi infernus classic lamborghini diablo, cizeta v16t, ferrari testarossa","txt":"Der Infernus ist der historische Supersportwagen der Reihe, dabei seit GTA III. Seine Version Classic übernimmt die Designmerkmale des Lamborghini Diablo und des Cizeta V16T: scharfe Kanten, Scherentüren, praktisch keine Sicht nach hinten. Der Diablo führte in den 90ern die Ästhetik des Supersportwagens vom Poster im Jugendzimmer weiter. Er wurde im Extended Look entdeckt.","reel":"https://www.google.com/search?tbm=isch&q=Lamborghini%20Diablo","reelNom":"Lamborghini Diablo","slot":"europeen","thumb":"/img/schemas/pegassi-infernus-classic.svg"},{"id":"pfister-comet-retro-custom","nom":"Comet Retro Custom","marque":"Pfister","cat":"sport","st":"vu","insp":"Rauh-Welt Porsche 911 930","src":"Erster Trailer","search":"pfister comet retro custom rauh-welt porsche 911 930","txt":"Pfister ist der Porsche des Universums, und der Comet schon immer sein 911. Die Version Retro Custom orientiert sich an den 911 der G-Serie aus den 70ern und 80ern, erkennbar an ihren Faltenbalg-Stoßstangen. Diese Generation, lange verschmäht, ist heute die gefragteste für Umbauten. Der erste Trailer zeigt ihn rundum verbreitert, ausladende Radläufe inklusive.","reel":"https://www.google.com/search?tbm=isch&q=Rauh-Welt%20Porsche%20911%20930","reelNom":"Rauh-Welt Porsche 911 930","slot":"europeen","thumb":"/img/schemas/pfister-comet-retro-custom.svg"},{"id":"pfister-comet-s2","nom":"Comet S2","marque":"Pfister","cat":"sport","st":"comm","insp":"Porsche 911 992","txt":"Das Pfister-Coupé in seiner neuesten Form, auf Basis des 911 der Generation 992. Heckmotor hinter der Hinterachse, durchgehendes Leuchtenband, verbreitertes Heck. Die Cabrio-Variante ist bereits in dieser Datenbank.","search":"pfister comet s2 porsche 911 992","src":"Zuordnung der Community","reel":"https://www.google.com/search?tbm=isch&q=Porsche%20911%20992","reelNom":"Porsche 911 992","slot":"europeen","thumb":"/img/schemas/pfister-comet-s2.svg"},{"id":"pfister-comet-s2-cabrio","nom":"Comet S2 Cabrio","marque":"Pfister","cat":"sport","st":"vu","insp":"Porsche 911 Turbo S Cabriolet","src":"Erster Trailer","search":"pfister comet s2 cabrio porsche 911 turbo s cabriolet","txt":"Cabrio-Variante des modernen Comet, nach dem Vorbild des Porsche 911 vom Typ 992. Die Besonderheit des offenen 911 liegt in seiner Bauweise: Da der Motor hinten sitzt, leidet die Steifigkeit der Karosserie weniger unter dem fehlenden Dach als bei einem klassischen Sportwagen. Im ersten Trailer fährt er mit offenem Verdeck an der Uferpromenade entlang.","medias":["trailer-1-vehicles-033"],"imageAlts":{"trailer-1-vehicles-033":"Türkisfarbenes Cabrio links im Vordergrund an der Uferpromenade, erster Trailer von GTA VI bei 00:33"},"reel":"https://www.google.com/search?tbm=isch&q=Porsche%20911%20Turbo%20S%20Cabriolet","reelNom":"Porsche 911 Turbo S Cabriolet","slot":"europeen","thumb":"/img/officiel/trailer-1-vehicles-033-480.webp"},{"id":"annis-growler","nom":"Growler","marque":"Pfister","cat":"sport","st":"vu","insp":"Porsche 718 Cayman","src":"Zweiter Trailer","search":"pfister growler porsche 718 cayman","txt":"Der Growler ist das Pfister-Coupé, das in unserer Datenbank dem Porsche 718 Cayman zugeordnet wird. Er ist im zweiten Trailer erfasst. Seine Identifizierung stammt weiterhin aus der Community: Das offizielle Material nennt keinen Namen für ihn.","reel":"https://www.google.com/search?tbm=isch&q=Porsche%20718%20Cayman","reelNom":"Porsche 718 Cayman","slot":"europeen","thumb":"/img/schemas/annis-growler.svg"},{"id":"pfister-neon","nom":"Neon","marque":"Pfister","cat":"sport","st":"vu","insp":"Porsche Taycan, Porsche Panamera, Porsche 918 Spyder","src":"Extended Look","txt":"Die Elektrolimousine von Pfister, zusammengesetzt aus mehreren Porsche: der Taycan für die Silhouette, der 918 Spyder für die Front, der Panamera für die Dachlinie. Leise und schwer, spurtet aber sehr kräftig los. Der Extended Look folgt dem Wagen durch die Stadt.","reel":"https://www.google.com/search?tbm=isch&q=Porsche%20Taycan","reelNom":"Porsche Taycan","search":"pfister neon porsche taycan, porsche panamera, porsche 918 spyder","slot":"europeen","thumb":"/img/schemas/pfister-neon.svg"},{"id":"ubermacht-cypher","nom":"Cypher","marque":"Übermacht","cat":"sport","st":"vu","insp":"BMW M2 F87, mit Anklängen an M6 und M8","src":"Erster Trailer","search":"ubermacht cypher bmw m2 f87, avec des touches de m6 et m8","txt":"Übermacht ist der BMW der Reihe, und der Cypher sein geschärftes kompaktes Coupé. Der BMW M2, dessen Designmerkmale er übernimmt, gehört zu einer Linie, die bis zum M3 der 80er zurückreicht, einem straßenzugelassenen Rennwagen, dessen Ruf auf der Rennstrecke entstand, bevor er in die Autohäuser kam. Der erste Trailer zeigt ihn im Stand, kurz vor dem Losfahren.","reel":"https://www.google.com/search?tbm=isch&q=BMW%20M2%20F87","reelNom":"BMW M2 F87","slot":"europeen","thumb":"/img/schemas/ubermacht-cypher.svg"},{"id":"ubermacht-sentinel-classic","nom":"Sentinel Classic","marque":"Übermacht","cat":"sport","st":"vu","insp":"BMW E30 M3","txt":"Der Sentinel ist seit GTA III der BMW des GTA-Universums. Die Version Classic übernimmt die Silhouette des E30 aus den 80ern: flache Motorhaube, runde Doppelscheinwerfer, schmale C-Säule. Genau die Art deutsches Coupé, die man auf dem Ocean Drive sah, zu der Zeit, die Vice City nachspielt.","search":"ubermacht sentinel classic bmw e30 m3","src":"Extended Look","medias":["extended-look-sentinel-classic-front","extended-look-sentinel-classic-rear"],"imageAlts":{"extended-look-sentinel-classic-front":"Rotes Cabrio vor Geschäften, Standbild aus An Extended Look","extended-look-sentinel-classic-rear":"Rotes Cabrio von hinten während einer Fahrszene in An Extended Look"},"reel":"https://www.google.com/search?tbm=isch&q=BMW%20E30%20M3","reelNom":"BMW E30 M3","slot":"europeen","thumb":"/img/officiel/extended-look-sentinel-classic-front-480.webp"},{"id":"ubermacht-sentinel-xs","nom":"Sentinel XS","marque":"Übermacht","cat":"sport","st":"vu","insp":"BMW M3 E92","txt":"Aktuelle Version des Sentinel, angelehnt an den 3er der 2000er und 2010er. Kompaktes Coupé mit Heckantrieb, integrierte Stoßstangen, ausgeprägte Schulterlinie. Das Referenzmodell der deutschen Sportlimousine für die breite Masse.","search":"ubermacht sentinel xs bmw m3 e92","src":"Zweiter Trailer","reel":"https://www.google.com/search?tbm=isch&q=BMW%20M3%20E92","reelNom":"BMW M3 E92","slot":"europeen","thumb":"/img/schemas/ubermacht-sentinel-xs.svg"},{"id":"ubermacht-zion","nom":"Zion","marque":"Übermacht","cat":"sport","st":"vu","insp":"BMW M6 E63","src":"Offizielle Screenshots","search":"ubermacht zion bmw m6 e63","txt":"Als gediegenes Coupé von Übermacht setzt der Zion eher auf Grand Touring als auf reine Leistung: zwei Türen, vier Sitze, ein Motor, der genügt, ohne extravagant zu sein. Das ist das Auto von jemandem, der es geschafft hat und es nicht mehr beweisen muss. Die offiziellen Screenshots zeigen ihn schräg geparkt, mit geschlossenem Dach.","reel":"https://www.google.com/search?tbm=isch&q=BMW%20M6%20E63","reelNom":"BMW M6 E63","slot":"europeen","thumb":"/img/schemas/ubermacht-zion.svg"},{"id":"ubermacht-zion-cabrio","nom":"Zion Cabrio","marque":"Übermacht","cat":"sport","st":"vu","insp":"BMW 6er E64","src":"Extended Look","txt":"Die offene Version des Zion, nach dem BMW 6er E64 aus der Bangle-Ära, umstrittenes Heck inklusive. Vier Sitze, Stoffverdeck, ein Sechszylinder, der den Ton hält. Der Extended Look zeigt ihn mit offenem Verdeck an der Küste.","reel":"https://www.google.com/search?tbm=isch&q=BMW%20S%C3%A9rie%206%20E64","reelNom":"BMW 6er E64","search":"ubermacht zion cabrio bmw serie 6 e64","slot":"europeen","thumb":"/img/schemas/ubermacht-zion-cabrio.svg"},{"id":"grotti-furia","nom":"Furia","marque":"Grotti","cat":"supercar","st":"vu","insp":"Ferrari 488 Pista und SF90 Stradale","src":"Erster Trailer","search":"grotti furia ferrari 488 pista et sf90 stradale","txt":"Der Furia orientiert sich am Ferrari SF90 Stradale, dem ersten Straßen-Ferrari mit Plug-in-Hybrid. Die Bauweise ist ungewöhnlich: ein Turbo-V8 hinten, drei Elektromotoren, zwei davon an der Vorderachse, zusammen über tausend PS. Ein Auto, das lautlos fahren kann, bevor es sich verwandelt. Der erste Trailer schickt ihn mit Vollgas über ein freies Stück Straße.","reel":"https://www.google.com/search?tbm=isch&q=Ferrari%20488%20Pista","reelNom":"Ferrari 488 Pista","slot":"europeen","thumb":"/img/schemas/grotti-furia.svg"},{"id":"lamborghini-aventador","nom":"Aventador","marque":"Unbekannte Marke","cat":"supercar","st":"vu","insp":"Lamborghini Aventador","src":"Erster Trailer","txt":"Der Lamborghini Aventador, wie er ist: Scherentüren und V12-Saugmotor, ohne Namen im Spiel und ohne zugeordneten fiktiven Hersteller. Rockstar hat ihn in die Kulisse gestellt, ohne ein hauseigenes Gegenstück zu erfinden. Der erste Trailer zeigt ihn im Verkehr.","reel":"https://www.google.com/search?tbm=isch&q=Lamborghini%20Aventador","reelNom":"Lamborghini Aventador","search":"marque inconnue aventador lamborghini aventador","slot":"europeen","thumb":"/img/schemas/lamborghini-aventador.svg"},{"id":"pegassi-tempesta","nom":"Tempesta","marque":"Pegassi","cat":"supercar","st":"vu","insp":"Lamborghini Huracán und Centenario","src":"Zweiter Trailer","search":"pegassi tempesta lamborghini huracan et centenario","txt":"Der Tempesta leiht sich Elemente vom Lamborghini Huracán und vom Centenario: V10-Saugmotor in Mittellage, Allradantrieb, facettierte Karosserie. Der Huracán ist einer der letzten Supersportwagen mit großvolumigem Saugmotor, was ihm einen Klang verleiht, den Turbomotoren nicht nachahmen können. Manche sehen darin auch den Lotus Esprit, der 2015 entworfen und nie gebaut wurde.","reel":"https://www.google.com/search?tbm=isch&q=Lamborghini%20Hurac%C3%A1n","reelNom":"Lamborghini Huracán","slot":"europeen","thumb":"/img/schemas/pegassi-tempesta.svg"},{"id":"pegassi-zentorno","nom":"Zentorno","marque":"Pegassi","cat":"supercar","st":"comm","insp":"Lamborghini Sesto Elemento und Veneno","txt":"Supersportwagen mit scharfen Kanten, Y-förmigen Lufteinlässen und spitz zulaufendem Dach. Der Zentorno treibt die Lamborghini-Formensprache in ihre extremste Form, die der auf wenige Exemplare limitierten Serien.","search":"pegassi zentorno lamborghini sesto elemento et veneno","src":"Zuordnung der Community","reel":"https://www.google.com/search?tbm=isch&q=Lamborghini%20Sesto%20Elemento","reelNom":"Lamborghini Sesto Elemento","slot":"europeen","thumb":"/img/schemas/pegassi-zentorno.svg"},{"id":"pegassi-zorrusso","nom":"Zorrusso","marque":"Pegassi","cat":"supercar","st":"vu","insp":"Italdesign Zerouno","src":"Erster Trailer","search":"pegassi zorrusso italdesign zerouno","txt":"Der Zorrusso von Pegassi wird hier dem Italdesign Zerouno zugeordnet. Diese Identifizierung bleibt eine Zuordnung der Community. Der erste Trailer ist der für diese Seite verzeichnete Auftritt, ohne offizielle Bezeichnung des Fahrzeugs.","reel":"https://www.google.com/search?tbm=isch&q=Italdesign%20Zerouno","reelNom":"Italdesign Zerouno","slot":"europeen","thumb":"/img/schemas/pegassi-zorrusso.svg"},{"id":"progen-emerus","nom":"Emerus","marque":"Progen","cat":"supercar","st":"vu","insp":"McLaren Senna","src":"Extended Look","txt":"Der Rennstrecken-Supersportwagen von Progen, abgepaust vom McLaren Senna: riesiger Heckflügel, Lufthutzen überall, Verglasung bis tief in die Türen. Alles wird dem Abtrieb geopfert, angefangen beim Komfort. Der Extended Look zeigt ihn abgestellt in einer Garage.","reel":"https://www.google.com/search?tbm=isch&q=McLaren%20Senna","reelNom":"McLaren Senna","search":"progen emerus mclaren senna","slot":"europeen","thumb":"/img/schemas/progen-emerus.svg"},{"id":"albany-buccaneer","nom":"Buccaneer","marque":"Albany","cat":"muscle","st":"vu","insp":"Ford Fairlane, Buick Riviera","src":"Erster Trailer","search":"albany buccaneer ford fairlane, buick riviera","txt":"Der Buccaneer ist das amerikanische Personal-Luxury-Coupé in seiner üppigsten Form. Der Buick Riviera von 1966, der ihn inspiriert, ist ein Auto mit bemerkenswertem Design, mit Klappscheinwerfern und straffer Linie der C-Säule, gezeichnet vom Designstudio von General Motors auf seinem Höhepunkt. Der erste Trailer zeigt ihn beim Herausfahren aus einer Kurve, das Heck leicht ausbrechend.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Fairlane","reelNom":"Ford Fairlane","slot":"americain","thumb":"/img/schemas/albany-buccaneer.svg"},{"id":"albany-buccaneer-custom","nom":"Buccaneer Custom","marque":"Albany","cat":"muscle","st":"vu","insp":"Ford Fairlane, Buick Riviera","src":"Erster Trailer","search":"albany buccaneer custom ford fairlane, buick riviera","txt":"Getunte Version des Buccaneer im Lowrider-Stil: Karosserie fast auf dem Boden, Speichenfelgen, Glitzerlack. Die großen Coupés der 60er sind die historischen Basen dieser Kultur, gerade weil ihr Leiterrahmen hydraulische Fahrwerke gut verträgt. Der erste Trailer erwischt ihn unter den Neonlichtern einer Tankstelle.","medias":["trailer-1-vehicles-028"],"imageAlts":{"trailer-1-vehicles-028":"Hellblauer Lowrider rechts im Vordergrund, erster Trailer von GTA VI bei 00:28"},"reel":"https://www.google.com/search?tbm=isch&q=Ford%20Fairlane","reelNom":"Ford Fairlane","slot":"americain","thumb":"/img/officiel/trailer-1-vehicles-028-480.webp"},{"id":"albany-virgo-classic","nom":"Virgo Classic","marque":"Albany","cat":"muscle","st":"comm","insp":"Lincoln Continental Mark III","txt":"Personal-Luxury-Coupé der 70er: angedeutetes Reserverad auf dem Kofferraum, senkrechter Kühlergrill, Vinyldach. Die Datenbank ordnet diesen Virgo Classic Albany zu und bringt ihn mit dem Lincoln Continental Mark III in Verbindung.","search":"albany virgo classic lincoln continental mark iii","src":"Zuordnung der Community","reel":"https://www.google.com/search?tbm=isch&q=Lincoln%20Continental%20Mark%20III","reelNom":"Lincoln Continental Mark III","slot":"americain","thumb":"/img/schemas/albany-virgo-classic.svg"},{"id":"bravado-buffalo-stx","nom":"Buffalo STX","marque":"Bravado","cat":"muscle","st":"vu","insp":"2015 Dodge Charger","src":"Erster Trailer","search":"bravado buffalo stx 2015 dodge charger","txt":"Sportliche Variante des Buffalo, mit dem kompletten Paket: Frontsplitter, Heckspoiler, sichtbare Auspuffrohre. Der Archetyp der amerikanischen Limousine, die sich weigert, vernünftig zu sein. Der erste Trailer zeigt ihn in einer Parkplatzszene, Türen geschlossen.","reel":"https://www.google.com/search?tbm=isch&q=2015%20Dodge%20Charger","reelNom":"2015 Dodge Charger","slot":"americain","thumb":"/img/schemas/bravado-buffalo-stx.svg"},{"id":"bravado-gauntlet-classic","nom":"Gauntlet Classic","marque":"Bravado","cat":"muscle","st":"vu","src":"Erster Trailer","insp":"Dodge Challenger erste Generation","txt":"Der ursprüngliche Gauntlet, nach dem Vorbild des Dodge Challenger der ersten Generation: endlose Motorhaube, betonte Radläufe, abgeschnittenes Heck. Seit mehreren Teilen ist er das Muscle-Car schlechthin von Bravado. Im ersten Trailer fährt er über eine palmengesäumte Avenue.","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Challenger","reelNom":"Dodge Challenger","search":"bravado gauntlet classic dodge challenger premiere generation","slot":"americain","thumb":"/img/schemas/bravado-gauntlet-classic.svg"},{"id":"vapid-gauntlet-classic-custom","nom":"Gauntlet Classic Custom","marque":"Bravado","cat":"muscle","st":"comm","insp":"Dodge Challenger 1970","src":"Zuordnung der Community","search":"bravado gauntlet classic custom dodge challenger 1970","txt":"Umbau eines Dodge Challenger von 1970, eines der heute gefragtesten Muscle-Cars. Die Version von 1970 ist die, deren Design alle überzeugt, mit Kühlergrill mit vier Scheinwerfern und gerader Schulterlinie. Der Zusatz Custom bedeutet überarbeiteten Motor und überarbeitetes Chassis. Von Rockstar nicht bestätigt.","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Challenger%201970","reelNom":"Dodge Challenger 1970","slot":"americain","thumb":"/img/schemas/vapid-gauntlet-classic-custom.svg"},{"id":"bravado-gauntlet-hellfire","nom":"Gauntlet Hellfire","marque":"Bravado","cat":"muscle","st":"vu","insp":"Dodge Challenger Demon 2018","src":"Erster Trailer","search":"bravado gauntlet hellfire dodge challenger demon 2018","txt":"Der Gauntlet Hellfire übernimmt die Designmerkmale des Dodge Challenger SRT Hellcat, eines Autos, dessen Datenblatt an Provokation grenzt: ein Kompressor-V8 mit über siebenhundert PS in einer 1970 entworfenen Karosserie, ohne jeden Anspruch auf Feinheit. Er ist zum Symbol der amerikanischen Weigerung geworden, maßvoll zu sein. Der erste Trailer lässt ihn auf einer Geraden los, die Motorhaube vibriert.","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Challenger%20Demon%202018","reelNom":"Dodge Challenger Demon 2018","slot":"americain","thumb":"/img/schemas/bravado-gauntlet-hellfire.svg"},{"id":"declasse-impaler-lx","nom":"Impaler ’80","marque":"Declasse","cat":"muscle","st":"vu","insp":"Chevrolet Impala sechste Generation","txt":"Der serienmäßige Impaler, ohne das Karosseriekit des SZ. Der Chevrolet Impala der sechsten Generation, der von Ende der 70er, ist eine riesige Limousine mit flachem Dach und geraden Flanken, zu Hunderttausenden vom Band gelaufen, für Flotten ebenso wie für Familien. Die offiziellen Screenshots zeigen ihn am Straßenrand.","search":"declasse impaler ’80 chevrolet impala sixieme generation","src":"Offizielle Screenshots","medias":["vice-city-09"],"imageAlts":{"vice-city-09":"Blaue Limousine im Vordergrund, unter dem Viadukt von Vice City in GTA VI."},"reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Impala","reelNom":"Chevrolet Impala","slot":"americain","thumb":"/img/officiel/vice-city-09-480.webp"},{"id":"declasse-impaler-sz","nom":"Impaler SZ","marque":"Declasse","cat":"muscle","st":"vu","insp":"1994-1996 Chevrolet Impala SS","src":"Offizielle Screenshots","search":"declasse impaler sz 1994-1996 chevrolet impala ss","txt":"Declasse ist der Chevrolet der Reihe, und der Impaler seine große Volkslimousine. Die Version SZ ist die sportliche Variante, im Geist der Straßen-Umbauten. Der Name spielt auf den Impala an, ein in der amerikanischen Autokultur allgegenwärtiges Modell. Dieser Impaler SZ ist in unserer Datenbank mit den offiziellen Screenshots verknüpft; sein Name bleibt dort eine Community-Identifizierung.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Impala%20SS","reelNom":"Chevrolet Impala SS","slot":"americain","thumb":"/img/schemas/declasse-impaler-sz.svg"},{"id":"declasse-sabre-turbo","nom":"Sabre Turbo","marque":"Declasse","cat":"muscle","st":"vu","insp":"Chevrolet Chevelle, Oldsmobile Cutlass","src":"Erster Trailer","search":"declasse sabre turbo chevrolet chevelle, oldsmobile cutlass","txt":"Der Sabre Turbo mischt den Chevrolet Chevelle und den Oldsmobile Cutlass, zwei Mittelklassemodelle von General Motors, die sich Anfang der 70er dieselbe Plattform teilten. Das war die große Zeit der dicken V8, jäh beendet durch die Ölkrise von 1973. Der Zusatz Turbo stammt dagegen aus der Tuningszene: Diese Motoren waren ab Werk nie aufgeladen.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Chevelle","reelNom":"Chevrolet Chevelle","slot":"americain","thumb":"/img/schemas/declasse-sabre-turbo.svg"},{"id":"declasse-tulip","nom":"Tulip","marque":"Declasse","cat":"muscle","st":"vu","insp":"1972 Chevelle Malibu, 1972 Oldsmobile Cutlass Supreme","src":"Erster Trailer","search":"declasse tulip 1972 chevelle malibu, 1972 oldsmobile cutlass supreme","txt":"Der Tulip übernimmt den Chevelle Malibu und den Oldsmobile Cutlass Supreme von 1972, den letzten Jahrgang, bevor die Abgasnormen die amerikanischen Motoren abwürgten. Diese Mittelklassewagen verkauften sich millionenfach, deshalb sieht man sie noch überall, oft in fragwürdigem Zustand. Ein Auto fürs Viertel, nicht für Sammler.","medias":["trailer-1-vehicles-071"],"imageAlts":{"trailer-1-vehicles-071":"Rote Limousine, gefahren von Jason mit Lucia, im Profil im ersten Trailer von GTA VI gegen 01:11"},"reel":"https://www.google.com/search?tbm=isch&q=1972%20Chevelle%20Malibu","reelNom":"1972 Chevelle Malibu","slot":"americain","thumb":"/img/officiel/trailer-1-vehicles-071-480.webp"},{"id":"declasse-tulip-m100","nom":"Tulip M100","marque":"Declasse","cat":"muscle","st":"vu","insp":"Chevrolet Malibu vierte Generation","src":"Erster Trailer","search":"declasse tulip m100 chevrolet malibu quatrieme generation","txt":"Getunte Version des Tulip, im Geist der Muscle-Cars aus dem Viertel: getauschter Motor, überarbeitetes Fahrwerk, selbstbewusste Optik. Der Zusatz M100 erinnert an die Chassiscodes, mit denen Tuner ihre Basisfahrzeuge bezeichnen. Der erste Trailer parkt ihn neben einem Vorstadthaus.","medias":["trailer-1-vehicles-028"],"imageAlts":{"trailer-1-vehicles-028":"Höhergelegte pinke Limousine in der Mitte, erster Trailer von GTA VI bei 00:28"},"reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Malibu","reelNom":"Chevrolet Malibu","slot":"americain","thumb":"/img/officiel/trailer-1-vehicles-028-480.webp"},{"id":"declasse-vigero-zx-convertible","nom":"Vigero ZX Convertible","marque":"Declasse","cat":"muscle","st":"vu","insp":"Chevrolet Camaro sechste Generation","src":"Offizielle Screenshots","search":"declasse vigero zx convertible chevrolet camaro sixieme generation","txt":"Cabrio-Variante des modernen Vigero, angelehnt an den aktuellen Chevrolet Camaro. Der aktuelle Camaro übernimmt bewusst die Proportionen der Generation von 1969, mit einer hohen Gürtellinie, die die Sicht stark einschränkt: ein bewusst eingegangener Kompromiss zugunsten des Stils. Die offiziellen Screenshots zeigen ihn offen, unter klarem Himmel.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Camaro","reelNom":"Chevrolet Camaro","slot":"americain","thumb":"/img/schemas/declasse-vigero-zx-convertible.svg"},{"id":"declasse-voodoo","nom":"Voodoo","marque":"Declasse","cat":"muscle","st":"comm","insp":"Chevrolet Impala 1960","txt":"Der Lowrider schlechthin von Grand Theft Auto, dabei seit San Andreas. Tiefergelegte Karosserie, Hydraulikfahrwerk, Metalliclack. Er passt ganz natürlich in eine heiße Stadt mit breiten Boulevards.","search":"declasse voodoo chevrolet impala 1960","src":"Zuordnung der Community","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Impala%201960","reelNom":"Chevrolet Impala 1960","slot":"americain","thumb":"/img/schemas/declasse-voodoo.svg"},{"id":"imponte-phoenix","nom":"Phoenix","marque":"Imponte","cat":"muscle","st":"vu","insp":"Pontiac Firebird zweite Generation","src":"Zweiter Trailer","search":"imponte phoenix pontiac firebird deuxieme generation","txt":"Imponte ist der Pontiac des Universums, eine Marke, die es in der Realität nicht mehr gibt, die aber im amerikanischen Automythos zentral bleibt. Der Phoenix übernimmt die Designmerkmale des Firebird der 70er, mit riesiger Motorhaube und Vogel-Dekor. Der zweite Trailer zeigt ihn aus der Froschperspektive, Heckspoiler inklusive.","reel":"https://www.google.com/search?tbm=isch&q=Pontiac%20Firebird","reelNom":"Pontiac Firebird","slot":"americain","thumb":"/img/schemas/imponte-phoenix.svg"},{"id":"imponte-ruiner","nom":"Ruiner","marque":"Imponte","cat":"muscle","st":"vu","insp":"Pontiac Trans Am/Chevrolet Camaro","src":"Erster Trailer","search":"imponte ruiner pontiac trans am/chevrolet camaro","txt":"Der Ruiner ist der Pontiac Trans Am der Reihe, ein Auto, das untrennbar zur amerikanischen Popkultur der 70er und 80er gehört, berühmt geworden durch Kino und Fernsehen. Seine Silhouette, seine Lufthutzen und seine Motorhaubenstreifen haben mehr für seinen Ruf getan als seine tatsächliche Leistung. Der erste Trailer schickt ihn mit hohem Tempo über eine Kreuzung.","reel":"https://www.google.com/search?tbm=isch&q=Pontiac%20Trans%20Am%2FChevrolet%20Camaro","reelNom":"Pontiac Trans Am/Chevrolet Camaro","slot":"americain","thumb":"/img/schemas/imponte-ruiner.svg"},{"id":"sirius","nom":"Sirius","marque":"Unbekannte Marke","cat":"muscle","st":"vu","insp":"1970 Mercury Cougar","src":"Ultimate Edition","note":"Der Name Sirius ist auf dem hinteren Kotflügel des türkisfarbenen Muscle-Cars aus der Wyman-Sammlung zu lesen.","vues":[],"credit":"Offizieller Screenshot von Rockstar Games","search":"marque inconnue sirius 1970 mercury cougar","txt":"Die offiziellen Screenshots zeigen ein türkisfarbenes Muscle-Car mit goldenen Streifen, Kofferraumspoiler und Dreispeichenfelgen, mit dem Namen Sirius ausgeschrieben auf dem hinteren Kotflügel. Weder unsere bisherige Liste noch die anderer Seiten erwähnten dieses Modell: ein Fund direkt aus dem Material von Rockstar. Die Silhouette ist die eines Mercury Cougar von 1970, des teureren Cousins des Mustang. Der Hersteller wurde nicht bekannt gegeben.","edition":"Ultimate Edition","medias":["classic-car-collection-02"],"vuesDeclarees":["profil"],"reel":"https://www.google.com/search?tbm=isch&q=1970%20Mercury%20Cougar","reelNom":"1970 Mercury Cougar","slot":"americain","thumb":"/img/officiel/classic-car-collection-02-480.webp"},{"id":"schyster-deviant","nom":"Deviant","marque":"Schyster","cat":"muscle","st":"officiel","insp":"1972 AMC Javelin","src":"Ultimate Edition","vues":[],"credit":"Offizieller Screenshot von Rockstar Games","search":"schyster deviant 1972 amc javelin","txt":"Der Name des Deviant stammt von Rockstar, aus der Vorstellung der Ultimate Edition, und unser offizieller Screenshot zeigt ihn in den Farben der amerikanischen Flagge, mit dem Schriftzug auf der C-Säule und dem durch das Fenster sichtbaren Innenraum. Der AMC Javelin, dessen Proportionen er übernimmt, war der Außenseiter des Marktes: Gebaut von einem unabhängigen Hersteller, viel kleiner als die großen Drei aus Detroit, gewann er trotzdem die Trans-Am-Meisterschaft gegen Mustang und Camaro.","edition":"Ultimate Edition","medias":["classic-car-collection-06"],"vuesDeclarees":["profil"],"reel":"https://www.google.com/search?tbm=isch&q=1972%20AMC%20Javelin","reelNom":"1972 AMC Javelin","slot":"americain","thumb":"/img/officiel/classic-car-collection-06-480.webp"},{"id":"vapid-chino","nom":"Chino","marque":"Vapid","cat":"muscle","st":"vu","insp":"Lincoln Continental und Chrysler Imperial von 1965","src":"Erster Trailer","search":"vapid chino lincoln continental et chrysler imperial de 1965","txt":"Der Chino ist das amerikanische Gebrauchtcoupé, das man für fast nichts kauft und zwanzig Jahre behält. In der Reihe wird er mit Arbeitervierteln und der Lowrider-Kultur verbunden. Sein Reiz liegt weniger in seinen Qualitäten als in dem, wofür er steht. Seine Präsenz beruht auf Sichtungen von Spielern.","reel":"https://www.google.com/search?tbm=isch&q=Lincoln%20Continental","reelNom":"Lincoln Continental","slot":"americain","thumb":"/img/schemas/vapid-chino.svg"},{"id":"vapid-chino-custom","nom":"Chino Custom","marque":"Vapid","cat":"muscle","st":"comm","insp":"Lincoln Continental Mark IV und V, als Lowrider aufgebaut","src":"Zuordnung der Community","search":"vapid chino custom lincoln continental mark iv et v, prepare en lowrider","txt":"Getunte Version des Chino: Hydraulikfahrwerk, Speichenfelgen, mehrschichtige Lackierung. In Vice City ist dieser Look kein dekoratives Detail, sondern ein Zeichen der Zugehörigkeit, ein Erbe der kubanischen und puerto-ricanischen Communitys von Miami. Modell von Rockstar nicht bestätigt.","reel":"https://www.google.com/search?tbm=isch&q=Lincoln%20Continental%20Mark%20IV","reelNom":"Lincoln Continental Mark IV","slot":"americain","thumb":"/img/schemas/vapid-chino-custom.svg"},{"id":"vapid-dominator","nom":"Dominator","marque":"Vapid","cat":"muscle","st":"vu","insp":"Ford Mustang","src":"Erster Trailer","search":"vapid dominator ford mustang","txt":"Der Dominator ist der Ford Mustang der Reihe, und Vapid ist ihr Ford. Der moderne Mustang setzt eine 1964 begonnene Linie fort, mit einer Konstante: großer Motor vorne, Hinterradantrieb und ein bewusst erschwinglicher Preis. Er ist im ersten Trailer erfasst, ohne von Rockstar genannten Namen.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Mustang","reelNom":"Ford Mustang","slot":"americain","thumb":"/img/schemas/vapid-dominator.svg"},{"id":"vapid-dominator-67","nom":"Dominator ’67","marque":"Vapid","cat":"muscle","st":"vu","src":"Offizielle Screenshots","insp":"Ford Mustang erste Generation","txt":"Der Dominator in seiner ursprünglichen Form, der des Ford Mustang der ersten Generation: breiter Kühlergrill, ausgeformte Flanken, kurzes Heck. Das ist der Urahn der ganzen Linie, in Straßenausführung und nicht als höhergelegter Buggy. Die offiziellen Screenshots zeigen ihn in einer Privatsammlung.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Mustang","reelNom":"Ford Mustang","search":"vapid dominator ’67 ford mustang premiere generation","slot":"americain","thumb":"/img/schemas/vapid-dominator-67.svg"},{"id":"vapid-dominator-asp","nom":"Dominator ASP","marque":"Vapid","cat":"muscle","st":"vu","insp":"Ford Mustang SVT Cobra R (New Edge)","src":"Erster Trailer","search":"vapid dominator asp ford mustang svt cobra r (new edge)","txt":"Getunte Variante des Dominator, mit Aerodynamikteilen für mehr Abtrieb und verbreiterter Spur. Ford hat den Mustang schon immer in immer radikaleren Versionen angeboten, bis hin zu Modellen, die kaum noch straßenzugelassen sind. Der erste Trailer zeigt ihn dicht an der Stoßstange eines anderen Autos.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Mustang%20SVT%20Cobra%20R%20(New%20Edge)","reelNom":"Ford Mustang SVT Cobra R (New Edge)","slot":"americain","thumb":"/img/schemas/vapid-dominator-asp.svg"},{"id":"vapid-dominator-buggy","nom":"Dominator Buggy ’67","marque":"Vapid","cat":"muscle","st":"officiel","insp":"Ford Mustang von 1967, für Offroad umgebaut","src":"Offizielle Seite der Ultimate Edition","vues":[],"credit":"Offizieller Screenshot von Rockstar Games","search":"vapid dominator buggy ’67 ford mustang de 1967, preparee tout-terrain","txt":"Rockstar hat dieses Fahrzeug in der Vorstellung der Ultimate Edition benannt, und unsere vier offiziellen Screenshots zeigen es aus allen Blickwinkeln: blaue Karosserie mit gelbem Streifen, Startnummer 6, Traktorreifen, Dachbügel mit vier Scheinwerfern, Gitter-Kühlergrill hinter einem Rammschutz. Im Innenraum sind das Dreispeichenlenkrad und der originale Tacho erhalten. Ein Ford Mustang von 1967, höhergelegt und für den Schlamm umgebaut: Er allein fasst das ländliche Sumpf-Florida zusammen, wenige Kilometer von den Hochhäusern von Vice City entfernt.","medias":["67-vapid-dominator-buggy-01","67-vapid-dominator-buggy-02","67-vapid-dominator-buggy-03","67-vapid-dominator-buggy-04"],"edition":"Ultimate Edition","vuesDeclarees":["face","profil","interieur","detail"],"reel":"https://www.google.com/search?tbm=isch&q=Ford%20Mustang%20de%201967","reelNom":"Ford Mustang von 1967","slot":"americain","thumb":"/img/officiel/67-vapid-dominator-buggy-01-480.webp"},{"id":"vapid-dominator-gt","nom":"Dominator GT","marque":"Vapid","cat":"muscle","st":"vu","insp":"2018-2023 Ford Mustang Convertible","src":"Offizielle Screenshots","search":"vapid dominator gt 2018-2023 ford mustang convertible","txt":"Cabrio-Version des Dominator. Das Mustang Cabrio gibt es seit der allerersten Generation, und es macht einen großen Teil der Verkäufe in Florida aus, wo das Klima ein Dach fast überflüssig macht. Die offiziellen Screenshots zeigen ihn vor einer Villa am Meer.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Mustang%20Convertible","reelNom":"Ford Mustang Convertible","slot":"americain","thumb":"/img/schemas/vapid-dominator-gt.svg"},{"id":"vapid-dominator-gtx","nom":"Dominator GTX","marque":"Vapid","cat":"muscle","st":"vu","insp":"Moderner Ford Mustang und Dodge Charger","src":"Erster Trailer","search":"vapid dominator gtx ford mustang et dodge charger contemporaines","txt":"Eine weitere Variante des Dominator, ganz im Stil der Sondermodelle, die Ford beim Mustang am laufenden Band auflegt: Gedenklackierungen, überarbeitete Motoren, nummerierte Kleinserien. Der Dominator GTX ist im ersten Trailer unter einem von der Community vorgeschlagenen Namen erfasst.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Mustang","reelNom":"Ford Mustang","slot":"americain","thumb":"/img/schemas/vapid-dominator-gtx.svg"},{"id":"vapid-slamvan","nom":"Slamvan","marque":"Vapid","cat":"muscle","st":"vu","insp":"Ford F-Series 1953-1956, als Rat Rod aufgebaut","src":"Erster Trailer","search":"vapid slamvan ford f-series 1953-1956 prepare rat rod","txt":"Der Slamvan ist ein Pick-up, der fast auf dem Asphalt aufliegt – irgendwo zwischen Custom-Umbau und Showfahrzeug. Tiefergelegte Trucks sind eine Tradition aus Kalifornien und Texas, entstanden in den 80ern rund um japanische Mini-Trucks. Die hier erfasste Version stammt aus dem ersten Trailer, ein offizieller Name wurde nicht genannt.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20F-Series%20pr%C3%A9par%C3%A9%20rat%20rod","reelNom":"Ford F-Series, als Rat Rod aufgebaut","slot":"americain","thumb":"/img/schemas/vapid-slamvan.svg"},{"id":"willard-faction","nom":"Faction","marque":"Willard","cat":"muscle","st":"comm","insp":"Buick Regal aus den 80ern","txt":"Zweitüriges US-Coupé aus den späten 80ern, in der Reihe die klassische Basis für Lowrider. Gerade Linien, breite C-Säule, schmaler Kühlergrill.","search":"willard faction buick regal des annees 80","src":"Zuordnung der Community","reel":"https://www.google.com/search?tbm=isch&q=Buick%20Regal%20des%20ann%C3%A9es%2080","reelNom":"Buick Regal aus den 80ern","slot":"americain","thumb":"/img/schemas/willard-faction.svg"},{"id":"willard-faction-custom-donk","nom":"Faction Custom Donk","marque":"Willard","cat":"muscle","st":"comm","insp":"Buick Regal als Donk","txt":"Der Donk ist ein Tuning-Stil aus dem Süden der USA, vor allem aus Miami: höhergelegte Karosserie, Felgen mit riesigem Durchmesser, knallige Lackierung. Er ist einer der wenigen Autostile, die wirklich in der Region verwurzelt sind, für die Leonida steht.","search":"willard faction custom donk buick regal en configuration donk","src":"Zuordnung der Community","reel":"https://www.google.com/search?tbm=isch&q=Buick%20Regal%20en%20configuration%20donk","reelNom":"Buick Regal als Donk","slot":"americain","thumb":"/img/schemas/willard-faction-custom-donk.svg"},{"id":"albany-cavalcade-xl","nom":"Cavalcade XL","marque":"Albany","cat":"suv","st":"vu","insp":"Cadillac Escalade-V 2023","src":"Offizielle Screenshots","txt":"Der amerikanische Luxus-SUV in seiner protzigsten Form. Der Escalade-V, dessen Züge er übernimmt, packt einen aufgeladenen Sechsliter-V8 in eine zweieinhalb Tonnen schwere Karosserie. Er ist das Statusfahrzeug schlechthin, das Auto für Kolonnen und Musikvideos.","search":"albany cavalcade xl cadillac escalade-v 2023","reel":"https://www.google.com/search?tbm=isch&q=Cadillac%20Escalade-V%202023","reelNom":"Cadillac Escalade-V 2023","slot":"americain","thumb":"/img/schemas/albany-cavalcade-xl.svg"},{"id":"benefactor-dubsta","nom":"Dubsta","marque":"Benefactor","cat":"suv","st":"vu","insp":"Mercedes-Benz G-Klasse","src":"Erster Trailer","search":"benefactor dubsta mercedes-benz g-class","txt":"Der Dubsta übernimmt die Designsprache der Mercedes-Benz G-Klasse, eines ursprünglich fürs Militär entwickelten Fahrzeugs, das vierzig Jahre lang fast unverändert gebaut wurde. Sein Erfolg beruht auf einem Paradox: ein Militärgerät, das zum urbanen Luxusobjekt wurde und für ein Vermögen in Vierteln verkauft wird, in denen es nie ein Hindernis überwinden wird. Im ersten Trailer klettert er mit der Stoßstange voran auf einen Bordstein.","reel":"https://www.google.com/search?tbm=isch&q=Mercedes-Benz%20G-Class","reelNom":"Mercedes-Benz G-Klasse","slot":"europeen","thumb":"/img/schemas/benefactor-dubsta.svg"},{"id":"benefactor-xls","nom":"XLS","marque":"Benefactor","cat":"suv","st":"vu","insp":"Mercedes-Benz GL-Klasse","src":"Extended Look","txt":"Großer deutscher SUV mit drei Sitzreihen, irgendwo zwischen Mercedes GL und BMW X5. Im Extended Look entdeckt. Das ist das Format des Chef-SUV: lang genug für sieben Sitze und edel genug, um den Asphalt nie zu verlassen.","search":"benefactor xls mercedes-benz classe gl","reel":"https://www.google.com/search?tbm=isch&q=Mercedes-Benz%20Classe%20GL","reelNom":"Mercedes-Benz GL-Klasse","slot":"europeen","thumb":"/img/schemas/benefactor-xls.svg"},{"id":"bravado-dorado","nom":"Dorado","marque":"Bravado","cat":"suv","st":"vu","insp":"Dodge Durango der ersten Generation","src":"Offizielle Screenshots","search":"bravado dorado dodge durango premiere generation","txt":"Der Dorado orientiert sich am Dodge Durango der ersten Generation, der 1998 auf Basis des Pick-ups Dakota erschien. Er war Chryslers Antwort auf den Wandel des US-Markts hin zum Familien-SUV: drei Sitzreihen, Anhängelast und ein Verbrauch, auf den damals noch niemand achtete.","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Durango","reelNom":"Dodge Durango","slot":"americain","thumb":"/img/schemas/bravado-dorado.svg"},{"id":"enus-jubilee","nom":"Jubilee","marque":"Buckingham","cat":"suv","st":"vu","insp":"Rolls-Royce Cullinan","src":"Erster Trailer","search":"buckingham jubilee rolls-royce cullinan","txt":"Der Jubilee ist der Ultra-Luxus-SUV der Modellreihe, angelehnt an den Rolls-Royce Cullinan. Sein Erscheinen in der realen Welt war ein Wendepunkt: Eine Marke, die Geländewagen lange abgelehnt hatte, stieg ein, weil das zu ihrer wichtigsten Gewinnquelle geworden ist. Gegenläufig öffnende Türen, senkrechter Kühlergrill, selbstbewusst hohe Karosserie.","reel":"https://www.google.com/search?tbm=isch&q=Rolls-Royce%20Cullinan","reelNom":"Rolls-Royce Cullinan","slot":"europeen","thumb":"/img/schemas/enus-jubilee.svg"},{"id":"canis-mesa","nom":"Mesa","marque":"Canis","cat":"suv","st":"vu","insp":"Jeep Wrangler","src":"Offizielles Bild der Ultimate Edition","note":"Das Canis-Logo ist auf dem Kühlergrill des grünen Pick-ups in der Werkstatt One-Eyed Willie zu lesen.","vues":[],"credit":"Offizieller Screenshot von Rockstar Games","search":"canis mesa jeep wrangler","txt":"Unsere offiziellen Screenshots zeigen diesen knallgrünen viertürigen Pick-up in der Werkstatt One-Eyed Willie, mit ausgeschriebenem Canis-Logo auf dem Kühlergrill, einer Seilwinde, Abschlepphaken und einem Unterfahrschutz unter dem Motor. Eine Werkstattansicht zeigt ihn mit offener Motorhaube, mitten im Umbau. Die Silhouette erinnert an Geländewagen mit Leiterrahmen im Stil eines Jeep. Rockstar hat das Modell nicht benannt.","vuesDeclarees":["face","profil","detail"],"reel":"https://www.google.com/search?tbm=isch&q=Jeep%20Wrangler","reelNom":"Jeep Wrangler","slot":"americain","thumb":"/img/schemas/canis-mesa.svg"},{"id":"declasse-seminole-frontier","nom":"Seminole Frontier","marque":"Canis","cat":"suv","st":"vu","insp":"Jeep Cherokee XJ der zweiten Generation","txt":"Kompakter SUV mit kantiger Karosserie, flachen Radläufen und senkrechter C-Säule. Der Name verweist auf das Volk der Seminolen in Florida, deren historisches Gebiet einen Teil dessen umfasst, was das Spiel Leonida nennt.","search":"canis seminole frontier jeep cherokee xj deuxieme generation","src":"Erster Trailer","reel":"https://www.google.com/search?tbm=isch&q=Jeep%20Cherokee%20XJ","reelNom":"Jeep Cherokee XJ","slot":"americain","thumb":"/img/schemas/declasse-seminole-frontier.svg"},{"id":"canis-terminus","nom":"Terminus","marque":"Canis","cat":"suv","st":"vu","insp":"Jeep Wrangler Rubicon der vierten Generation","src":"Extended Look","txt":"Kurzer Geländewagen mit sichtbarem Überrollbügel, angelehnt an den aktuellen Wrangler Rubicon. Der Wrangler ist einer der wenigen massentauglichen 4x4, die noch Starrachsen und ein abnehmbares Dach haben – deshalb sieht man ihn in jedem Feuchtgebiet Floridas. Im Extended Look gesehen.","reel":"https://www.google.com/search?tbm=isch&q=Jeep%20Wrangler%20Rubicon","reelNom":"Jeep Wrangler Rubicon","search":"canis terminus jeep wrangler rubicon quatrieme generation","slot":"americain","thumb":"/img/schemas/canis-terminus.svg"},{"id":"declasse-granger","nom":"Granger","marque":"Declasse","cat":"suv","st":"vu","insp":"Chevrolet Suburban","src":"Zweiter Trailer","search":"declasse granger chevrolet suburban","txt":"Der Granger ist der große amerikanische SUV mit Leiterrahmen, angelehnt an den Chevrolet Suburban. Diese Art Fahrzeug hat in den USA einen besonderen Platz: Familienauto, Dienstwagen und Streifenwagen der Polizei zugleich. Er taucht im zweiten Trailer auf.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Suburban","reelNom":"Chevrolet Suburban","slot":"americain","thumb":"/img/schemas/declasse-granger.svg"},{"id":"declasse-granger-3600lx","nom":"Granger 3600LX","marque":"Declasse","cat":"suv","st":"vu","insp":"Chevrolet Suburban 2015-2020","src":"Erster Trailer","search":"declasse granger 3600lx chevrolet suburban 2015-2020","txt":"Edelversion des Granger, im Geist der Luxusausstattungen, die General Motors seinen großen SUVs verpasst: Leder, Chrom, 22-Zoll-Felgen. Das Fahrzeug ist im ersten Trailer zu sehen.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Suburban","reelNom":"Chevrolet Suburban","slot":"americain","thumb":"/img/schemas/declasse-granger-3600lx.svg"},{"id":"dundreary-landstalker-xl","nom":"Landstalker XL","marque":"Dundreary","cat":"suv","st":"vu","insp":"Lincoln Navigator der vierten Generation","src":"Zweiter Trailer","search":"dundreary landstalker xl lincoln navigator quatrieme generation","txt":"Der Landstalker XL basiert auf dem Lincoln Navigator der vierten Generation, dem großen amerikanischen Luxus-SUV in seiner wuchtigsten Form. Lincoln hat das Konzept vom rollenden Wohnzimmer auf die Spitze getrieben: drei Sitzreihen, Lederausstattung, Panoramabildschirm. Er ist das Fahrzeug der reichen Viertel von Vice City, mit dem man vors Hotel fährt, ohne auszusteigen.","reel":"https://www.google.com/search?tbm=isch&q=Lincoln%20Navigator","reelNom":"Lincoln Navigator","slot":"americain","thumb":"/img/schemas/dundreary-landstalker-xl.svg"},{"id":"gallivanter-baller","nom":"Baller II","marque":"Gallivanter","cat":"suv","st":"vu","insp":"Range Rover Evoque und Range Rover Sport","src":"Offizielle Screenshots","search":"gallivanter baller ii range rover evoque et range rover sport","txt":"Gallivanter ist das Gegenstück zu Land Rover in diesem Universum, der Baller seine Stadtvariante auf Basis des Range Rover Sport. Das reale Modell zeigt eine bezeichnende Entwicklung: Vom britischen Nutzfahrzeug für die Landwirtschaft wurde es zum Standardauto wohlhabender Viertel – mit Geländefähigkeiten, die nie jemand nutzt.","reel":"https://www.google.com/search?tbm=isch&q=Range%20Rover%20Evoque","reelNom":"Range Rover Evoque","slot":"europeen","thumb":"/img/schemas/gallivanter-baller.svg"},{"id":"gallivanter-baller-st","nom":"Baller ST-D","marque":"Gallivanter","cat":"suv","st":"vu","insp":"Range Rover L460","txt":"Die Performance-Version des Baller: neu gestaltete Stoßstange, vier Auspuffendrohre, Felgen mit großem Durchmesser. Der schnelle Luxus-SUV ist ein Archetyp, der perfekt in die reichen Viertel von Vice City passt.","search":"gallivanter baller st-d range rover l460","src":"Offizielle Screenshots","reel":"https://www.google.com/search?tbm=isch&q=Range%20Rover%20L460","reelNom":"Range Rover L460","slot":"europeen","thumb":"/img/schemas/gallivanter-baller-st.svg"},{"id":"vapid-contender","nom":"Contender","marque":"Karin","cat":"suv","st":"vu","insp":"Ford F-150 Raptor und getunter Toyota Tundra","src":"Offizielle Screenshots","search":"karin contender ford f-150 raptor et toyota tundra prepare","txt":"Großer Pick-up, angelehnt an den getunten Toyota Tundra, mit Anleihen beim Ford F-150 Raptor: die Klasse der höhergelegten Freizeit-Trucks, eher für Pisten gemacht als für die Stadt. Die offiziellen Screenshots zeigen ihn hoch auf seinen grobstolligen Reifen.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20F-150%20Raptor","reelNom":"Ford F-150 Raptor","slot":"japonais","thumb":"/img/schemas/vapid-contender.svg"},{"id":"karin-vivanite","nom":"Vivanite","marque":"Karin","cat":"suv","st":"vu","insp":"Toyota Sienna der vierten Generation","src":"Extended Look","txt":"Japanischer Van, im Extended Look entdeckt. Der Sienna, dessen Linien er übernimmt, fährt serienmäßig als Hybrid – eine seltene Wahl in diesem Segment. Da Karin die Toyota-Marke dieses Universums ist, ist die Abstammung eindeutig.","search":"karin vivanite toyota sienna quatrieme generation","reel":"https://www.google.com/search?tbm=isch&q=Toyota%20Sienna","reelNom":"Toyota Sienna","slot":"japonais","thumb":"/img/schemas/karin-vivanite.svg"},{"id":"lampadati-novak","nom":"Novak","marque":"Lampadati","cat":"suv","st":"vu","insp":"Maserati Levante","src":"Offizielle Screenshots","txt":"Italienischer Luxus-SUV, irgendwo zwischen Maserati Levante und Alfa Romeo Stelvio. Lampadati deckt im GTA-Universum beide Marken ab. Die Herausforderung: den Charakter einer Sportlimousine in eine höhergelegte Karosserie zu packen – mit umstrittenem Ergebnis.","search":"lampadati novak maserati levante","reel":"https://www.google.com/search?tbm=isch&q=Maserati%20Levante","reelNom":"Maserati Levante","slot":"europeen","thumb":"/img/schemas/lampadati-novak.svg"},{"id":"mammoth-patriot-mil-spec","nom":"Patriot Mil-Spec","marque":"Mammoth","cat":"suv","st":"vu","insp":"Hummer H1","src":"Extended Look","txt":"Militärversion des Patriot, angelehnt an den zivilen Hummer H1, der vom Humvee der US-Armee abstammt. Breit, langsam, durstig – er hatte nie ein anderes Argument als seine Geländegängigkeit und seinen Auftritt. Im Extended Look entdeckt.","reel":"https://www.google.com/search?tbm=isch&q=Hummer%20H1","reelNom":"Hummer H1","search":"mammoth patriot mil-spec hummer h1","thumb":"/img/schemas/mammoth-patriot-mil-spec.svg"},{"id":"dodge-durango-3","nom":"Durango","marque":"Unbekannte Marke","cat":"suv","st":"vu","insp":"Dodge Durango der dritten Generation","src":"Zweiter Trailer","txt":"Amerikanischer Familien-SUV der dritten Generation, in den stärksten Versionen mit Motoren, die alles andere als familientauglich sind. Nicht zu verwechseln mit dem Dorado, der auf der ersten Generation basiert. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue durango dodge durango troisieme generation","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Durango","reelNom":"Dodge Durango","slot":"americain","thumb":"/img/schemas/dodge-durango-3.svg"},{"id":"ford-explorer-2","nom":"Explorer ’95","marque":"Unbekannte Marke","cat":"suv","st":"vu","insp":"Ford Explorer der zweiten Generation","src":"Erster Trailer","txt":"Der SUV, der den US-Markt umgekrempelt hat. Die zweite Generation des Explorer, in den 90ern millionenfach verkauft, brachte die Familien dazu, den Kombi aufzugeben. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue explorer ’95 ford explorer deuxieme generation","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Explorer","reelNom":"Ford Explorer","slot":"americain","thumb":"/img/schemas/ford-explorer-2.svg"},{"id":"audi-q7-2","nom":"Q7","marque":"Unbekannte Marke","cat":"suv","st":"vu","insp":"Audi Q7 der zweiten Generation","src":"Erster Trailer","txt":"Großer deutscher SUV mit drei Sitzreihen, zweite Generation. Mit dem Audi Q7 begann bei der Marke eine Modellpalette, die heute den Großteil ihrer Verkäufe ausmacht – auf Kosten der Limousinen, die ihren Ruf begründet haben. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue q7 audi q7 deuxieme generation","reel":"https://www.google.com/search?tbm=isch&q=Audi%20Q7","reelNom":"Audi Q7","slot":"europeen","thumb":"/img/schemas/audi-q7-2.svg"},{"id":"toyota-rav4-5","nom":"RAV4","marque":"Unbekannte Marke","cat":"suv","st":"vu","insp":"Toyota RAV4 der fünften Generation","src":"Zweiter Trailer","txt":"Japanischer Kompakt-SUV, seit mehreren Jahren das meistverkaufte Fahrzeug der Welt über alle Klassen hinweg. Dass er im Verkehr von Leonida auftaucht, ist schlicht statistischer Realismus. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue rav4 toyota rav4 cinquieme generation","reel":"https://www.google.com/search?tbm=isch&q=Toyota%20RAV4","reelNom":"Toyota RAV4","slot":"japonais","thumb":"/img/schemas/toyota-rav4-5.svg"},{"id":"pegassi-toros","nom":"Toros","marque":"Pegassi","cat":"suv","st":"vu","insp":"Lamborghini Urus und Audi Q8","src":"Offizielle Screenshots","search":"pegassi toros lamborghini urus et audi q8","txt":"Der Toros überträgt das Rezept des Lamborghini Urus: ein SUV auf Großserienbasis, im Look der Marke eingekleidet und mit einem extremen Antrieb ausgestattet. Wirtschaftlich ist es das Modell, mit dem Lamborghini seine Produktion verdoppeln konnte. Er ist auf den offiziellen Screenshots zu sehen.","reel":"https://www.google.com/search?tbm=isch&q=Lamborghini%20Urus","reelNom":"Lamborghini Urus","slot":"europeen","thumb":"/img/schemas/pegassi-toros.svg"},{"id":"pfister-astron","nom":"Astron","marque":"Pfister","cat":"suv","st":"vu","insp":"Porsche Macan","src":"Zweiter Trailer","search":"pfister astron porsche macan","txt":"Der Astron ist der SUV von Pfister, angelehnt an den Porsche Macan, den kleinen Bruder des Cayenne. Der Cayenne löste bei seinem Start 2002 einen Skandal unter den Puristen der Marke aus, bevor er zu dem Modell wurde, das den Verbleib der Sportwagen im Programm finanzierte. Rockstar hat ihn im zweiten Trailer auftauchen lassen.","reel":"https://www.google.com/search?tbm=isch&q=Porsche%20Macan","reelNom":"Porsche Macan","slot":"europeen","thumb":"/img/schemas/pfister-astron.svg"},{"id":"ubermacht-rebla-gts","nom":"Rebla GTS","marque":"Übermacht","cat":"suv","st":"vu","insp":"BMW X5 der vierten Generation","txt":"Deutsches SUV-Coupé mit abfallender Dachlinie und schräger Heckklappe. Der Rebla besetzt die Nische des SUV, der wie eine Sportlimousine aussehen will – eine Nische, die genau von dem Modell erfunden wurde, das ihn inspiriert.","search":"ubermacht rebla gts bmw x5 quatrieme generation","src":"Extended Look","reel":"https://www.google.com/search?tbm=isch&q=BMW%20X5","reelNom":"BMW X5","slot":"europeen","thumb":"/img/schemas/ubermacht-rebla-gts.svg"},{"id":"vapid-aleutian","nom":"Aleutian","marque":"Vapid","cat":"suv","st":"vu","insp":"Ford Expedition der vierten Generation","src":"Zweiter Trailer","search":"vapid aleutian ford expedition quatrieme generation","txt":"Großer amerikanischer SUV mit drei Sitzreihen: Der Aleutian gehört zu den Fahrzeugen, die sieben Personen samt Gepäck über lange Autobahnstrecken bringen sollen. Der zweite Trailer stellt ihn mit offener Heckklappe in eine Einfahrt im Wohngebiet.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Expedition","reelNom":"Ford Expedition","slot":"americain","thumb":"/img/schemas/vapid-aleutian.svg"},{"id":"vapid-montagne","nom":"Montagne","marque":"Vapid","cat":"suv","st":"vu","insp":"Ford Explorer der sechsten Generation","src":"Zweiter Trailer","txt":"Der aktuelle Explorer, nach zwanzig Jahren Frontantrieb zurück beim Heckantrieb. Da Vapid die Ford-Marke dieses Universums ist, ist die Zuordnung eindeutig. Er ist heute der verbreitetste Polizei-SUV der USA und taucht auch in ziviler Ausführung auf.","search":"vapid montagne ford explorer sixieme generation","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Explorer","reelNom":"Ford Explorer","slot":"americain","thumb":"/img/schemas/vapid-montagne.svg"},{"id":"vapid-riata-classic","nom":"Riata Classic","marque":"Vapid","cat":"suv","st":"officiel","insp":"Ford Bronco der ersten Generation","src":"Ultimate Edition","vues":[],"credit":"Offizieller Screenshot von Rockstar Games","search":"vapid riata classic ford bronco premiere generation","txt":"Rockstar selbst nennt den Riata Classic, nebenbei in der Ultimate Edition, und unser offizieller Screenshot zeigt ihn im Profil: cremefarbene Karosserie, Seitenstreifen mit Verlauf von Rot zu Gelb, Geländereifen, Schriftzug in Schreibschrift auf dem Kotflügel. Der Ford Bronco der ersten Generation, dessen Look er übernimmt, war ein einfaches Nutzfahrzeug, kaum mehr als Fahrgestell und Karosserie, und ist heute ein gesuchtes Sammlerstück.","edition":"Ultimate Edition","medias":["classic-car-collection-03"],"vuesDeclarees":["profil"],"reel":"https://www.google.com/search?tbm=isch&q=Ford%20Bronco","reelNom":"Ford Bronco","slot":"americain","thumb":"/img/officiel/classic-car-collection-03-480.webp"},{"id":"annis-hellion","nom":"Hellion","marque":"Annis","cat":"pickup","st":"vu","insp":"Nissan Patrol Safari Y6, Jeep Cherokee (XJ)","src":"Erster Trailer","search":"annis hellion nissan patrol safari y6, jeep cherokee (xj)","txt":"Der Hellion ist der Geländewagen von Annis – ungewöhnlich für eine Marke, die man mit japanischen Sportwagen verbindet. Seine kompakte, kantige Silhouette erinnert an japanische 4x4 der 80er, gebaut fürs Gelände statt für Komfort. Er ist im ersten Trailer im Bild.","reel":"https://www.google.com/search?tbm=isch&q=Nissan%20Patrol%20Safari%20Y6","reelNom":"Nissan Patrol Safari Y6","slot":"japonais","thumb":"/img/schemas/annis-hellion.svg"},{"id":"bravado-bison-900-95-monster-truck","nom":"Bison 900 ’95 Monster Truck","marque":"Bravado","cat":"pickup","st":"vu","insp":"Dodge Ram der zweiten Generation als Monster Truck","src":"Offizielle Screenshots","txt":"Der Bison 900 ’95 auf höhergelegten Achsen und Traktorreifen. Der Monster Truck entstand Ende der 70er im Süden der USA, als Pick-up-Besitzer immer größere Räder montierten, bis daraus eine Show wurde. Florida hat mehrere Strecken dafür.","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Ram%20en%20configuration%20monster%20truck","reelNom":"Dodge Ram als Monster Truck","search":"bravado bison 900 ’95 monster truck dodge ram deuxieme generation en configuration monster truck","slot":"americain","thumb":"/img/schemas/bravado-bison-900-95-monster-truck.svg"},{"id":"canis-kamacho","nom":"Kamacho","marque":"Canis","cat":"pickup","st":"vu","insp":"Jeep Crew Chief 715 (Konzeptfahrzeug)","txt":"Geländewagen mit ausgeschnittener Karosserie und Stollenreifen, gebaut fürs Offroad-Fahren. Die Sümpfe und Pisten im Hinterland von Leonida geben ihm einen echten Nutzen statt eines dekorativen.","search":"canis kamacho jeep crew chief 715 concept","src":"Offizielle Screenshots","medias":["one-eyed-willie-s-mod-shop-01","ultimate-edition-one-eyed-willie-03"],"imageAlts":{"one-eyed-willie-s-mod-shop-01":"Grüner Canis-Pick-up, umgebaut bei One-Eyed Willie in GTA VI.","ultimate-edition-one-eyed-willie-03":"Grüner Canis-Pick-up in der Werkstatt One-Eyed Willie in GTA VI."},"reel":"https://www.google.com/search?tbm=isch&q=Jeep%20Crew%20Chief%20715%20concept","reelNom":"Jeep Crew Chief 715 (Konzeptfahrzeug)","slot":"americain","thumb":"/img/officiel/one-eyed-willie-s-mod-shop-01-480.webp"},{"id":"declasse-rancher","nom":"Rancher","marque":"Declasse","cat":"pickup","st":"vu","insp":"Chevrolet Suburban","src":"Offizielle Screenshots","search":"declasse rancher chevrolet suburban","txt":"Der Rancher ist ein Nutz-Geländewagen alter Schule, näher an Landmaschinen als an einem Freizeitfahrzeug. In der Reihe steht er für ländliche Gegenden – das passt zu den Sümpfen und Farmen im Norden von Leonida. Auf den von Rockstar veröffentlichten Screenshots zu sehen.","medias":["trailer-2-rancher-035"],"imageAlts":{"trailer-2-rancher-035":"Rot-weißer Pick-up mit zwei Mitfahrern auf der Ladefläche, vor Jasons Auto auf der Schnellstraße, zweiter Trailer zu GTA VI bei etwa 00:35."},"reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Suburban","reelNom":"Chevrolet Suburban","slot":"americain","thumb":"/img/officiel/trailer-2-rancher-035-480.webp"},{"id":"declasse-walton-l35-stock","nom":"Walton L35","marque":"Declasse","cat":"pickup","st":"vu","insp":"Chevrolet S-10 1991-1993","src":"Offizielle Screenshots","search":"declasse walton l35 chevrolet s-10 1991-1993","txt":"Kleiner Arbeits-Pick-up alter Schule, Einzelkabine und kurze Ladefläche. Der Chevrolet S-10 aus den frühen 90ern war der günstigste kompakte Pick-up auf dem US-Markt und wurde an Handwerker und Farmen verkauft. Sein Wert steigt, seit diese Klasse aus den Katalogen verschwunden ist.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20S-10","reelNom":"Chevrolet S-10","slot":"americain","thumb":"/img/schemas/declasse-walton-l35-stock.svg"},{"id":"declasse-yosemite","nom":"Yosemite","marque":"Declasse","cat":"pickup","st":"comm","insp":"Chevrolet C10 aus den 60ern","txt":"Klassischer amerikanischer Pick-up mit Einzelkabine, oft zum Sammlerfahrzeug aufbereitet. Die Variante 1500 ist schon in dieser Datenbank.","search":"declasse yosemite chevrolet c10 des annees 60","src":"Zuordnung der Community","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20C10%20des%20ann%C3%A9es%2060","reelNom":"Chevrolet C10 aus den 60ern","slot":"americain","thumb":"/img/schemas/declasse-yosemite.svg"},{"id":"declasse-yosemite-1500","nom":"Yosemite 1500","marque":"Declasse","cat":"pickup","st":"vu","insp":"Chevrolet Silverado der ersten Generation","src":"Offizielle Screenshots","search":"declasse yosemite 1500 chevrolet silverado premiere generation","txt":"Der Yosemite 1500 folgt dem Chevrolet Silverado der ersten Generation, der 1999 als Nachfolger des C/K kam. Das ist der Pick-up, der die Klasse in Richtung Limousinenkomfort gedreht hat: verlängerte Kabine, vier Türen, Chromzierrat. Er ist auf den offiziellen Screenshots zu sehen.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Silverado","reelNom":"Chevrolet Silverado","slot":"americain","thumb":"/img/schemas/declasse-yosemite-1500.svg"},{"id":"dinka-verus","nom":"Verus","marque":"Dinka","cat":"pickup","st":"vu","insp":"Polaris Sportsman MV850","txt":"Gelände-Quad mit Rohrrahmen und breiten Reifen. Das Fahrzeug für sandige Pisten und Orte, an denen kein Auto durchkommt.","search":"dinka verus polaris sportsman mv850","src":"Offizielle Screenshots","reel":"https://www.google.com/search?tbm=isch&q=Polaris%20Sportsman%20MV850","reelNom":"Polaris Sportsman MV850","thumb":"/img/schemas/dinka-verus.svg"},{"id":"bravado-rebel","nom":"Rebel","marque":"Karin","cat":"pickup","st":"vu","insp":"Toyota Hilux","src":"Offizielle Screenshots","search":"karin rebel toyota hilux","txt":"Der Rebel orientiert sich am Toyota Hilux, einem Pick-up, der so berühmt für seine Unzerstörbarkeit ist, dass er zum Standardfahrzeug in Konfliktgebieten und auf Expeditionen wurde. Gerade seine einfache Mechanik macht seinen Wert aus. Er ist auf den offiziellen Screenshots zu finden.","reel":"https://www.google.com/search?tbm=isch&q=Toyota%20Hilux","reelNom":"Toyota Hilux","slot":"japonais","thumb":"/img/schemas/bravado-rebel.svg"},{"id":"dodge-dakota-convertible","nom":"Dakota Cabrio","marque":"Unbekannte Marke","cat":"pickup","st":"vu","insp":"Dodge Dakota Convertible","src":"Erster Trailer","txt":"Ein automobiles Kuriosum: ein Cabrio-Pick-up, den Dodge Ende der 80er in nur wenigen Tausend Exemplaren gebaut hat. Die Idee hat sich nie durchgesetzt – deshalb ist er heute ein kurioses Sammlerstück. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue dakota decapotable dodge dakota convertible","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Dakota%20Convertible","reelNom":"Dodge Dakota Convertible","slot":"americain","thumb":"/img/schemas/dodge-dakota-convertible.svg"},{"id":"ford-explorer-sport-trac","nom":"Explorer Sport Trac","marque":"Unbekannte Marke","cat":"pickup","st":"vu","src":"Extended Look","insp":"Ford Explorer Sport Trac","txt":"Der Ford Explorer Sport Trac, dieser SUV mit kurzer Ladefläche zwischen Kombi und Pick-up, in seiner zivilen Version. Es ist dasselbe Fahrgestell wie beim Exemplar in Rettungsschwimmer-Lackierung, mit Serienkarosserie. Im Extended Look steht er auf einem Parkplatz direkt am Strand.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Explorer%20Sport%20Trac","reelNom":"Ford Explorer Sport Trac","search":"marque inconnue explorer sport trac ford explorer sport trac","slot":"americain","thumb":"/img/schemas/ford-explorer-sport-trac.svg"},{"id":"ford-f-series-3","nom":"F-Series ’50","marque":"Unbekannte Marke","cat":"pickup","st":"vu","insp":"Ford F-Series der dritten Generation","src":"Offizielle Screenshots","txt":"Ford-Pick-up aus den 50ern, dritte Generation – die mit den breiten Kühlergrills und runden Kotflügeln. Das ist die Silhouette, die man mit Farmen und Tankstellen dieser Zeit verbindet, und eine bei Tunern sehr gefragte Basis. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue f-series ’50 ford f-series troisieme generation","reel":"https://www.google.com/search?tbm=isch&q=Ford%20F-Series","reelNom":"Ford F-Series","slot":"americain","thumb":"/img/schemas/ford-f-series-3.svg"},{"id":"ram-3500","nom":"RAM 3500","marque":"Unbekannte Marke","cat":"pickup","st":"vu","insp":"RAM 3500","src":"Erster Trailer","txt":"Schwerer Pick-up mit Zwillingsrädern hinten, gebaut, um Lasten zu ziehen, die sonst nichts zieht. Das Fahrzeug für alle, die Pferde, Boote und Wohnwagen transportieren. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue ram 3500 ram 3500","reel":"https://www.google.com/search?tbm=isch&q=RAM%203500","reelNom":"RAM 3500","thumb":"/img/schemas/ram-3500.svg"},{"id":"jeep-scrambler-cj8","nom":"Scrambler CJ-8","marque":"Unbekannte Marke","cat":"pickup","st":"vu","insp":"Jeep Scrambler CJ-8","src":"Offizielle Screenshots","txt":"Jeep CJ mit verlängertem Radstand und kleiner Ladefläche hinten, gebaut von 1981 bis 1986. Damals wenig verkauft, ist er heute Kult unter Geländewagen-Fans. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue scrambler cj-8 jeep scrambler cj-8","reel":"https://www.google.com/search?tbm=isch&q=Jeep%20Scrambler%20CJ-8","reelNom":"Jeep Scrambler CJ-8","slot":"americain","thumb":"/img/schemas/jeep-scrambler-cj8.svg"},{"id":"swamp-buggy","nom":"Swamp Buggy","marque":"Unbekannte Marke","cat":"pickup","st":"vu","insp":"Swamp Buggy aus Palm Beach","src":"Erster Trailer","txt":"Sumpffahrzeug auf riesigen Rädern, eine Spezialität Südfloridas. Dort werden seit den 40ern Swamp-Buggy-Rennen gefahren, in schlammigen Becken statt auf einer Strecke. Im ersten Trailer gesichtet. Sein Name im Spiel wurde nicht bekannt gegeben.","reel":"https://www.google.com/search?tbm=isch&q=Swamp%20buggy%20de%20Palm%20Beach","reelNom":"Swamp Buggy aus Palm Beach","search":"marque inconnue swamp buggy swamp buggy de palm beach","thumb":"/img/schemas/swamp-buggy.svg"},{"id":"nagasaki-blazer","nom":"Blazer","marque":"Nagasaki","cat":"pickup","st":"vu","insp":"Yamaha YFZ450","src":"Erster Trailer","search":"nagasaki blazer yamaha yfz450","txt":"Der Blazer ist ein Freizeit-Quad, ein vierrädriges Fahrzeug mit Lenker, gebaut für Sand und Wege. Florida mit seinen Stränden und Waldpisten ist einer der aktivsten Märkte für diese Art Fahrzeug. Das Quad fährt durch mehrere Einstellungen des ersten Trailers.","reel":"https://www.google.com/search?tbm=isch&q=Yamaha%20YFZ450","reelNom":"Yamaha YFZ450","slot":"japonais","thumb":"/img/schemas/nagasaki-blazer.svg"},{"id":"nagasaki-outlaw","nom":"Outlaw","marque":"Nagasaki","cat":"pickup","st":"vu","insp":"Can-Am Maverick X3 Turbo","src":"Erster Trailer","search":"nagasaki outlaw can-am maverick x3 turbo","txt":"Der Outlaw ist ein Offroad-Buggy mit Rohrrahmen, irgendwo zwischen Quad und Auto: kompletter Überrollkäfig, zwei Sitze nebeneinander, Federung mit langem Federweg. Der Buggy ist im ersten Trailer zu sehen.","reel":"https://www.google.com/search?tbm=isch&q=Can-Am%20Maverick%20X3%20Turbo","reelNom":"Can-Am Maverick X3 Turbo","thumb":"/img/schemas/nagasaki-outlaw.svg"},{"id":"vapid-caracara","nom":"Caracara","marque":"Vapid","cat":"pickup","st":"vu","insp":"Ford F-150, Hennessey VelociRaptor 6X6","txt":"Die Basisversion des Caracara, vor der verstärkten 4x4-Variante. Kompakter Pick-up mit kurzer Kabine, eher für Pisten gedacht als für die Autobahn.","search":"vapid caracara ford f-150, hennessey velociraptor 6x6","src":"Erster Trailer","reel":"https://www.google.com/search?tbm=isch&q=Ford%20F-150","reelNom":"Ford F-150","slot":"americain","thumb":"/img/schemas/vapid-caracara.svg"},{"id":"vapid-caracara-4x4","nom":"Caracara 4x4","marque":"Vapid","cat":"pickup","st":"vu","insp":"Ford F-150 Raptor der zweiten Generation","src":"Zweiter Trailer","search":"vapid caracara 4x4 ford f-150 raptor deuxieme generation","txt":"Der Caracara 4x4 überträgt den Ford F-150 Raptor ins Spiel, einen Pick-up, der schnell über Pisten fahren soll, statt langsam Hindernisse zu überwinden. Seine Federung mit langem Federweg stammt direkt aus den Wüstenrennen der Baja. Er taucht im zweiten Trailer auf.","medias":["trailer-2-caracara-016","brian-heder-01"],"imageAlts":{"trailer-2-caracara-016":"Brian Heder vor seinem Vapid-Pick-up im offiziellen Trailer 2 von GTA VI.","brian-heder-01":"Brian Heder am Steuer seines Pick-ups auf einem offiziellen GTA-VI-Screenshot."},"reel":"https://www.google.com/search?tbm=isch&q=Ford%20F-150%20Raptor","reelNom":"Ford F-150 Raptor","slot":"americain","thumb":"/img/officiel/trailer-2-caracara-016-480.webp"},{"id":"vapid-ganado","nom":"Ganado ’70","marque":"Vapid","cat":"pickup","st":"vu","insp":"Ford Ranchero 1970, Mercury Cougar 1969-1970","src":"Offizielle Screenshots","note":"Der Name Ganado und der Schriftzug 434ci sind auf dem Coupé-Pick-up zu lesen, der vor Jasons Unterschlupf parkt.","vues":[],"credit":"Offizieller Screenshot von Rockstar Games","search":"vapid ganado ’70 creado ford ranchero 1970, mercury cougar 1969-1970","txt":"Unsere offiziellen Screenshots zeigen diesen gelben Coupé-Pick-up mit roten Streifen vor Jasons Unterschlupf in den Keys. Der Name Ganado ist auf dem Kotflügel und am Armaturenbrett zu lesen, dazu der Schriftzug 434ci, der den Hubraum in Kubikzoll angibt. Es ist ein Coupé Utility in der Tradition des Ford Ranchero, und seine Platzierung im Material von Rockstar lässt vermuten, dass er der Figur gehört. Rockstar hat das Modell inzwischen Vapid zugeordnet, nachdem es zuerst unter dem Namen Creado vorgestellt worden war.","fam":"Amerikanisches Coupé Utility aus den 70ern","alias":"Creado","medias":["ganado-retro-build","jason-s-safehouse-vehicles"],"perso":"jason","vuesDeclarees":["profil","detail"],"reel":"https://www.google.com/search?tbm=isch&q=Ford%20Ranchero%201970","reelNom":"Ford Ranchero 1970","slot":"americain","thumb":"/img/officiel/ganado-retro-build-480.webp"},{"id":"vapid-liberator","nom":"Liberator","marque":"Vapid","cat":"pickup","st":"vu","insp":"Ford Expedition der zweiten Generation als Monster Truck","src":"Erster Trailer","txt":"Monster Truck mit patriotischer Lackierung, schon im ersten Trailer zu erkennen. Seine Basis ist ein großer Ford-SUV auf Lkw-Achsen. So ein Gefährt fährt fast nie auf der Straße: Es lebt zwischen zwei Shows auf dem Anhänger – genau die Art Detail, die Rockstar gern auf die Schippe nimmt.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Expedition%20en%20monster%20truck","reelNom":"Ford Expedition als Monster Truck","search":"vapid liberator ford expedition deuxieme generation en monster truck","slot":"americain","thumb":"/img/schemas/vapid-liberator.svg"},{"id":"vapid-reclaimer","nom":"Reclaimer","marque":"Vapid","cat":"pickup","st":"vu","insp":"Ford Ranger T6 2019-2023","src":"Erster Trailer","txt":"Mittelgroßer Pick-up – das Format, das in den USA Marktanteile von den riesig gewordenen Full-Size-Trucks zurückgewonnen hat. Der Ranger dieser Generation wurde als vernünftiger Kompromiss verkauft: genug Ladefläche zum Arbeiten, kompakt genug zum Parken in der Stadt.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Ranger%20T6","reelNom":"Ford Ranger T6","search":"vapid reclaimer ford ranger t6 2019-2023","slot":"americain","thumb":"/img/schemas/vapid-reclaimer.svg"},{"id":"vapid-sandking-xl","nom":"Sandking XL","marque":"Vapid","cat":"pickup","st":"vu","insp":"Ford Super Duty","src":"Erster Trailer","search":"vapid sandking xl ford super duty","txt":"Der Sandking XL ist ein höhergelegter Pick-up auf übergroßen Reifen, im Geist umgebauter Ford F-350. Höhergelegte Trucks sind besonders im Süden der USA verbreitet, wo sie ebenso Nutzen wie Statement sind. Der Pick-up taucht schon im ersten Trailer auf.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Super%20Duty","reelNom":"Ford Super Duty","slot":"americain","thumb":"/img/schemas/vapid-sandking-xl.svg"},{"id":"bravado-bison","nom":"Bison","marque":"Bravado","cat":"van","st":"vu","insp":"Dodge Ram Quad Cab der vierten Generation","src":"Zweiter Trailer","search":"bravado bison dodge ram quad cab quatrieme generation","txt":"Der Bison ist der amerikanische Arbeits-Pick-up in seiner gängigsten Form: Doppelkabine, kurze Ladefläche, V8-Motor. Diese Fahrzeugart ist seit mehr als vierzig Jahren die meistverkaufte in den USA, über alle Klassen hinweg. Er ist im zweiten Trailer zu sehen.","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Ram%20Quad%20Cab","reelNom":"Dodge Ram Quad Cab","slot":"americain","thumb":"/img/schemas/bravado-bison.svg"},{"id":"bravado-bison-1800","nom":"Bison 1800","marque":"Bravado","cat":"van","st":"vu","insp":"Ram 1500 DT","src":"Zweiter Trailer","txt":"Moderne Version des Bison, auf Basis des Ram 1500 der DT-Generation. Riesiger Kühlergrill, Doppelkabine, optionale Luftfederung: Der moderne amerikanische Pick-up ist kein Werkzeug mehr, sondern eine höhergelegte Familienlimousine – und die Verkaufszahlen geben ihm recht.","search":"bravado bison 1800 ram 1500 dt","medias":["grassrivers-04"],"imageAlts":{"grassrivers-04":"Pick-up im Vordergrund bei einer Verfolgungsjagd durch die Sümpfe von Grassrivers, GTA VI."},"reel":"https://www.google.com/search?tbm=isch&q=Ram%201500%20DT","reelNom":"Ram 1500 DT","thumb":"/img/officiel/grassrivers-04-480.webp"},{"id":"bravado-bison-900-95","nom":"Bison 900 ’95","marque":"Bravado","cat":"van","st":"vu","insp":"Dodge Ram der zweiten Generation","src":"Erster Trailer","txt":"Der Bison in seiner Version aus den 90ern, angelehnt an den Dodge Ram der zweiten Generation. Mit diesem Modell begann der Trend zur hohen Motorhaube und zum Kühlergrill im Lkw-Stil – ein Design, das das ganze Segment umgekrempelt hat. Zwanzig Jahre später sieht man ihn im Süden noch überall.","search":"bravado bison 900 ’95 dodge ram deuxieme generation","medias":["trailer-1-vehicles-053"],"imageAlts":{"trailer-1-vehicles-053":"Grüner Pick-up und sein Insasse, erster offizieller Trailer zu GTA VI bei 00:53"},"reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Ram","reelNom":"Dodge Ram","slot":"americain","thumb":"/img/officiel/trailer-1-vehicles-053-480.webp"},{"id":"bravado-rumpo","nom":"Rumpo","marque":"Bravado","cat":"van","st":"vu","insp":"Ford E-Series","txt":"Kastenwagen mit geschlossenen Seitenwänden, ohne Seitenfenster hinten. Der Rumpo ist seit GTA III in der Reihe und übernimmt die Rolle des austauschbaren Arbeits-Vans.","search":"bravado rumpo ford e-series","src":"Erster Trailer","medias":["trailer-1-vehicles-064"],"imageAlts":{"trailer-1-vehicles-064":"Weißer Transporter links in der von Weazel News gefilmten Szene, erster Trailer zu GTA VI bei etwa 01:04"},"reel":"https://www.google.com/search?tbm=isch&q=Ford%20E-Series","reelNom":"Ford E-Series","slot":"americain","thumb":"/img/officiel/trailer-1-vehicles-064-480.webp"},{"id":"bravado-youga-classic","nom":"Youga Classic","marque":"Bravado","cat":"van","st":"vu","insp":"Ford Econoline der zweiten Generation","src":"Erster Trailer","search":"bravado youga classic ford econoline deuxieme generation","txt":"Der Youga Classic ist der amerikanische Van der 70er, der Van der Surfer und der Rockbands auf Tour. Diese Klasse hat eine eigene Ästhetik entwickelt, mit Airbrush-Wandbildern, Bullaugenfenstern und Teppich im Innenraum. Der Van ist im ersten Trailer zu entdecken.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Econoline","reelNom":"Ford Econoline","slot":"americain","thumb":"/img/schemas/bravado-youga-classic.svg"},{"id":"brute-boxville","nom":"Boxville","marque":"Brute","cat":"van","st":"vu","insp":"GMC Step Van","src":"Offizielle Screenshots","search":"brute boxville gmc step van","txt":"Der Boxville ist der kastenförmige Lieferwagen, der auf amerikanischen Straßen allgegenwärtig ist. Seine Form folgt keinem ästhetischen Anspruch: maximales Volumen auf einem Fahrgestell, mit einer Schiebetür an der Seite. Er ist auf den von Rockstar veröffentlichten Screenshots zu sehen.","reel":"https://www.google.com/search?tbm=isch&q=GMC%20Step%20Van","reelNom":"GMC Step Van","slot":"americain","thumb":"/img/schemas/brute-boxville.svg"},{"id":"vapid-bobcat-xl","nom":"Bobcat XL","marque":"Declasse","cat":"van","st":"vu","insp":"Chevrolet C/K der vierten Generation","src":"Erster Trailer","search":"declasse bobcat xl chevrolet c/k quatrieme generation","txt":"Als kompakter Pick-up mit kurzer Ladefläche besetzt der Bobcat XL die Nische des kleinen Allzweck-Trucks, den Handwerker und städtische Dienste fahren. Weniger wuchtig als ein F-150, bleibt er stadttauglich. Der Pick-up taucht im ersten Trailer auf.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20C%2FK","reelNom":"Chevrolet C/K","slot":"americain","thumb":"/img/schemas/vapid-bobcat-xl.svg"},{"id":"declasse-burrito","nom":"Burrito","marque":"Declasse","cat":"van","st":"vu","insp":"Chevrolet Express 1996-2002","src":"Erster Trailer","search":"declasse burrito chevrolet express 1996-2002","txt":"Der Burrito ist der Baustellen-Transporter schlechthin: Kastenaufbau, keine Fenster hinten, vorne eine Sitzbank für drei. In der Reihe ist er untrennbar mit Raubüberfällen verbunden – das sagt viel darüber, wie unauffällig er ist. Der Van ist tatsächlich im ersten Trailer zu sehen.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Express","reelNom":"Chevrolet Express","slot":"americain","thumb":"/img/schemas/declasse-burrito.svg"},{"id":"coach","nom":"Coach","marque":"Unbekannte Marke","cat":"van","st":"comm","insp":null,"src":"Zuordnung der Community","search":"marque inconnue coach autocar longue distance americain","txt":"Der Fernreisebus gehört zum amerikanischen Straßenbild, mit seinen seitlichen Gepäckfächern und dem Band aus getönten Scheiben. Er verbindet die Städte, die Fluggesellschaften links liegen lassen. Modell von Rockstar für GTA VI nicht bestätigt.","fam":"Amerikanischer Fernreisebus","reel":"https://www.google.com/search?tbm=isch&q=Autocar%20longue%20distance%20am%C3%A9ricain","reelNom":"Amerikanischer Fernreisebus","thumb":"/img/schemas/coach.svg"},{"id":"ford-econoline-4","nom":"Econoline","marque":"Unbekannte Marke","cat":"van","st":"vu","insp":"Ford Econoline der vierten Generation","src":"Zweiter Trailer","txt":"Amerikanischer Transporter mit kurzer Schnauze, vierte Generation. Der Econoline war jahrzehntelang der Standard-Transporter in den USA: Klempner, Floristen, Bands auf Tour. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue econoline ford econoline quatrieme generation","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Econoline","reelNom":"Ford Econoline","slot":"americain","thumb":"/img/schemas/ford-econoline-4.svg"},{"id":"moocher","nom":"Moocher","marque":"Unbekannte Marke","cat":"van","st":"vu","insp":"Fleetwood Southwind 1985","src":"Offizielle Screenshots","txt":"Wohnmobil aus den 80ern, kastenförmige Karosserie und Zierstreifen im Stil der Zeit. Der Name, der ungefähr Schmarotzer bedeutet, sagt viel über die Figur, die sich Rockstar am Steuer vorstellt. Diese alternden Gefährte dienen in Florida oft als dauerhafte Unterkunft.","search":"marque inconnue moocher fleetwood southwind 1985","reel":"https://www.google.com/search?tbm=isch&q=Fleetwood%20Southwind%201985","reelNom":"Fleetwood Southwind 1985","thumb":"/img/schemas/moocher.svg"},{"id":"rexhall-rose-air","nom":"Rose Air","marque":"Unbekannte Marke","cat":"van","st":"vu","insp":"Rexhall Rose Air","src":"Extended Look","txt":"Vollintegriertes Wohnmobil, im Extended Look entdeckt. Rexhall war ein kalifornischer Hersteller von Wohnmobilen der Mittelklasse, den es inzwischen nicht mehr gibt. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue rose air rexhall rose air","reel":"https://www.google.com/search?tbm=isch&q=Rexhall%20Rose%20Air","reelNom":"Rexhall Rose Air","thumb":"/img/schemas/rexhall-rose-air.svg"},{"id":"mercedes-sprinter-2","nom":"Sprinter","marque":"Unbekannte Marke","cat":"van","st":"vu","insp":"Mercedes-Benz Sprinter","src":"Offizielle Screenshots","txt":"Edel-Transporter mit Hochdach, zweite Generation. Der Sprinter hat ganz allein eine Klasse geschaffen: zuverlässig genug für Firmenflotten, geräumig genug für den Ausbau zum Camper. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue sprinter mercedes-benz sprinter","reel":"https://www.google.com/search?tbm=isch&q=Mercedes-Benz%20Sprinter","reelNom":"Mercedes-Benz Sprinter","slot":"europeen","thumb":"/img/schemas/mercedes-sprinter-2.svg"},{"id":"chrysler-town-country","nom":"Town & Country","marque":"Unbekannte Marke","cat":"van","st":"vu","insp":"Chrysler Town & Country","src":"Erster Trailer","txt":"Familienvan mit Schiebetüren, fünfte Generation. Chrysler erfand dieses Format 1983 und dominierte es dreißig Jahre lang, bis der SUV es verdrängte. Das ist das Fahrzeug der Vorstadtfamilien, allgegenwärtig und völlig unsichtbar. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue town & country chrysler town & country","reel":"https://www.google.com/search?tbm=isch&q=Chrysler%20Town%20%26%20Country","reelNom":"Chrysler Town & Country","slot":"americain","thumb":"/img/schemas/chrysler-town-country.svg"},{"id":"ford-transit-4","nom":"Transit","marque":"Unbekannte Marke","cat":"van","st":"vu","insp":"Ford Transit der vierten Generation","src":"Zweiter Trailer","txt":"Europäischer Transporter, in den 2010er-Jahren in die USA geholt, um den Econoline zu ersetzen. Höher, schmaler, sparsamer: das europäische Konzept des Transporters, das sich am Ende auch jenseits des Atlantiks durchgesetzt hat. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue transit ford transit quatrieme generation","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Transit","reelNom":"Ford Transit","slot":"americain","thumb":"/img/schemas/ford-transit-4.svg"},{"id":"ford-transit-cargo-4","nom":"Transit Cargo","marque":"Unbekannte Marke","cat":"van","st":"vu","insp":"Ford Transit Cargo","src":"Erster Trailer","txt":"Kastenversion des Transit, ohne Seitenfenster hinten. Das ist die Ausführung für Kuriere und Handwerker: maximaler Laderaum und minimaler Einblick in das, was man transportiert. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue transit cargo ford transit cargo","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Transit%20Cargo","reelNom":"Ford Transit Cargo","slot":"americain","thumb":"/img/schemas/ford-transit-cargo-4.svg"},{"id":"vapid-speedo","nom":"Speedo","marque":"Vapid","cat":"van","st":"vu","insp":"Chevrolet Express, seit 2003","src":"Erster Trailer","search":"vapid speedo chevrolet express, depuis 2003","txt":"Der Speedo ist ein kompakter Transporter mit Frontlenker-Kabine, im Geist der Stadtlieferwagen. Durch seine geringe Größe ist er das Fahrzeug für Lieferungen in der Innenstadt, wo ein Boxville nicht durchkommt. Man sieht ihn im ersten Trailer vorbeifahren.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Express","reelNom":"Chevrolet Express","slot":"americain","thumb":"/img/schemas/vapid-speedo.svg"},{"id":"zirconium-journey","nom":"Journey","marque":"Zirconium","cat":"van","st":"vu","insp":"1979-1981 Fleetwood Pace Arrow","txt":"Vollintegriertes Wohnmobil, das Fahrzeug für den Ruhestand in Florida und für Roadtrips an der Ostküste. Die neuere Variante Journey II ist schon in dieser Datenbank.","search":"zirconium journey 1979-1981 fleetwood pace arrow","src":"Offizielle Screenshots","reel":"https://www.google.com/search?tbm=isch&q=Fleetwood%20Pace%20Arrow","reelNom":"Fleetwood Pace Arrow","thumb":"/img/schemas/zirconium-journey.svg"},{"id":"zirconium-journey-ii","nom":"Journey II","marque":"Zirconium","cat":"van","st":"comm","insp":"Winnebago Chieftain","src":"Zuordnung der Community","search":"zirconium journey ii winnebago chieftain","txt":"Der Journey II ist ein vollintegriertes Wohnmobil nach dem Vorbild des Winnebago Chieftain. Der Markenname Zirconium spielt mit der Imitation: Zirkon ist der Stein, der wie ein Diamant aussieht, ohne einer zu sein. Für ein Urlaubsfahrzeug mit kleinem Budget sitzt der Witz. Diese Gefährte gehören zum Bild der Straßen Floridas, vor allem im Winter.","reel":"https://www.google.com/search?tbm=isch&q=Winnebago%20Chieftain","reelNom":"Winnebago Chieftain","slot":"americain","thumb":"/img/schemas/zirconium-journey-ii.svg"},{"id":"dinka-double-t","nom":"Double T","marque":"Dinka","cat":"moto","st":"vu","insp":"Honda CBR","src":"Erster Trailer","search":"dinka double t honda cbr","txt":"Die Double T ist eine vollverkleidete Sporttourer-Maschine in der Tradition der Honda CBR. Diese Motorradklasse sucht eine seltene Balance: schnell genug für den Spaß, bequem genug für lange Strecken. Als Quelle für das Auftauchen der Double T gilt der erste Trailer, ihr Name wurde nicht bekannt gegeben.","reel":"https://www.google.com/search?tbm=isch&q=Honda%20CBR","reelNom":"Honda CBR","slot":"japonais","thumb":"/img/schemas/dinka-double-t.svg"},{"id":"dinka-enduro","nom":"Enduro","marque":"Dinka","cat":"moto","st":"officiel","insp":"Honda XL 350 und XR 500","src":"Ultimate Edition","vues":[],"credit":"Offizieller Screenshot von Rockstar Games","search":"dinka enduro honda xl 350 et xr 500","txt":"Die Enduro verdankt ihren Namen der Vorstellung der Ultimate Edition durch Rockstar, und unser offizieller Screenshot zeigt sie klar im Profil: olivgrüner Tank mit Dinka-Logo, abgewetzte schwarze Sitzbank, hoher Kotflügel, Stollenreifen, hochgezogener Auspuff. Sie ist eine japanische Enduro der 80er, von der Sorte, die genauso auf der Straße wie auf Pisten unterwegs war. Ein weiterer Screenshot zeigt sie vor Jasons Unterschlupf geparkt – sie gehört also wohl ihm.","edition":"Ultimate Edition","medias":["dinka-enduro-motorcycle","jason-s-safehouse-vehicles"],"perso":"jason","vuesDeclarees":["profil"],"reel":"https://www.google.com/search?tbm=isch&q=Honda%20XL%20350","reelNom":"Honda XL 350","slot":"japonais","thumb":"/img/officiel/dinka-enduro-motorcycle-480.webp"},{"id":"lcc-avarus","nom":"Avarus","marque":"LCC","cat":"moto","st":"vu","insp":"Chopper ohne Verkleidung (kein bestimmtes Modell)","txt":"Chopper mit stark geneigter Gabel, hohem Lenker und schmalem Vorderrad. Ein Stil, der direkt aus den amerikanischen Motorradclubs kommt und auf den langen, geraden Küstenstraßen bestens hinpasst.","search":"lcc avarus generica mostly-naked chopper","src":"Zweiter Trailer","medias":["trailer-2-motorcycle-143"],"imageAlts":{"trailer-2-motorcycle-143":"Jason fährt ein rotes Motorrad vor einem Wasserflugzeug im offiziellen Trailer 2 von GTA VI."},"reel":"https://www.google.com/search?tbm=isch&q=Generica%20mostly-naked%20chopper","reelNom":"Chopper ohne Verkleidung (kein bestimmtes Modell)","thumb":"/img/officiel/trailer-2-motorcycle-143-480.webp"},{"id":"maibatsu-manchez","nom":"Manchez","marque":"Maibatsu","cat":"moto","st":"vu","insp":"500cc KTM","txt":"Leichte Enduro mit großem Vorderrad, auf Asphalt genauso zu Hause wie auf Feldwegen. Praktisch in den Sümpfen und im Hinterland, wo die Straßen oft einfach enden.","search":"maibatsu manchez 500cc ktm","src":"Offizielle Screenshots","medias":["mount-kalaga-national-park-01","ptt-youngin-illegal-goods-store"],"imageAlts":{"mount-kalaga-national-park-01":"Zwei Geländemotorräder im Mount Kalaga National Park in GTA VI.","ptt-youngin-illegal-goods-store":"Verziertes Geländemotorrad im Laden PTT YOUNGIN$ in GTA VI."},"reel":"https://www.google.com/search?tbm=isch&q=500cc%20KTM","reelNom":"500cc KTM","thumb":"/img/officiel/mount-kalaga-national-park-01-480.webp"},{"id":"maibatsu-sanchez","nom":"Sanchez","marque":"Maibatsu","cat":"moto","st":"vu","insp":"Yamaha YZ450F 2006-2009","src":"Erster Trailer","search":"maibatsu sanchez yamaha yz450f 2006-2009","txt":"Die Sanchez ist in offiziellem Material zu sehen, ohne dass Rockstar ihren Namen nennt. Als Referenz für dieses Motorrad gilt die Yamaha YZ450F der Baujahre 2006 bis 2009. Identifizierung und Zuordnung stammen aus der Community; die erfasste Quelle ist der erste Trailer.","medias":["jason-and-lucia-09"],"imageAlts":{"jason-and-lucia-09":"Jason und Lucia auf einem gelben Motorrad, identifiziert als Maibatsu Sanchez, verfolgt von der Polizei."},"reel":"https://www.google.com/search?tbm=isch&q=Yamaha%20YZ450F","reelNom":"Yamaha YZ450F","slot":"japonais","thumb":"/img/officiel/jason-and-lucia-09-480.webp"},{"id":"yamaha-bws-125","nom":"BWs 125","marque":"Unbekannte Marke","cat":"moto","st":"vu","insp":"Yamaha BWs 125","src":"Extended Look","txt":"Der Stadtroller mit dicken Reifen, abgeleitet vom Yamaha BWs 125 – den man überall abstellt und der Bordsteine ungerührt wegsteckt. Der Name im Spiel wurde nicht bekannt gegeben. Im Extended Look fährt er im Verkehr eines Wohnviertels mit.","reel":"https://www.google.com/search?tbm=isch&q=Yamaha%20BWs%20125","reelNom":"Yamaha BWs 125","search":"marque inconnue bws 125 yamaha bws 125","slot":"japonais","thumb":"/img/schemas/yamaha-bws-125.svg"},{"id":"suzuki-gsx-r1000","nom":"GSX-R1000","marque":"Unbekannte Marke","cat":"moto","st":"vu","insp":"Suzuki GSX-R1000","src":"Offizielle Screenshots","txt":"Ein japanisches Sportmotorrad, Linie für Linie von der Suzuki GSX-R1000 übernommen, bisher ohne Namen im Spiel und ohne fiktiven Hersteller. Das ist die Art Motorrad, die man im Pulk auf den Boulevards sieht, im roten Drehzahlbereich zwischen zwei Fahrspuren. Die offiziellen Screenshots zeigen sie neben Lucia.","medias":["lucia-caminos-03"],"imageAlts":{"lucia-caminos-03":"Lucia sitzt auf einem gelben Motorrad, einer Suzuki GSX-R1000 zugeordnet"},"reel":"https://www.google.com/search?tbm=isch&q=Suzuki%20GSX-R1000","reelNom":"Suzuki GSX-R1000","search":"marque inconnue gsx-r1000 suzuki gsx-r1000","slot":"japonais","thumb":"/img/officiel/lucia-caminos-03-480.webp"},{"id":"pomazoom-mobility-scooter","nom":"Pomazoom","marque":"Unbekannte Marke","cat":"moto","st":"vu","insp":"Pride Maxima 3","src":"Offizielle Screenshots","txt":"Das dreirädrige Elektromobil von Gehwegen und Supermarktparkplätzen, einem Pride Maxima 3 nachgebildet. Rockstar hat daraus ein steuerbares Fahrzeug namens Pomazoom gemacht, samt Korb vorne. Die offiziellen Screenshots erwischen es mitten auf der Fahrt über einen Parkplatz.","medias":["leonida-keys-02"],"imageAlts":{"leonida-keys-02":"Fahrer eines blauen Elektromobils in den Leonida Keys, neben einem Alligator"},"reel":"https://www.google.com/search?tbm=isch&q=Pride%20Maxima%203","reelNom":"Pride Maxima 3","search":"marque inconnue pomazoom pride maxima 3","thumb":"/img/officiel/leonida-keys-02-480.webp"},{"id":"nagasaki-blazer-lifeguard","nom":"Blazer Lifeguard","marque":"Nagasaki","cat":"moto","st":"comm","insp":null,"src":"Zuordnung der Community","search":"nagasaki blazer lifeguard quad de plage en configuration de sauvetage","txt":"Rettungsversion des Blazer, in den Farben der Rettungsschwimmer. Solche Quads werden an den Stränden von Miami Beach tatsächlich eingesetzt, um zu patrouillieren und schnell im Sand einzugreifen. Die Zuordnung zu Leonida stammt von Spielern, da bisher kein offizielles Material dazu bekannt ist.","fam":"Strandquad in Rettungsausführung","reel":"https://www.google.com/search?tbm=isch&q=Quad%20de%20plage%20en%20configuration%20de%20sauvetage","reelNom":"Strandquad in Rettungsausführung","thumb":"/img/schemas/nagasaki-blazer-lifeguard.svg"},{"id":"nagasaki-carbon-rs","nom":"Carbon RS","marque":"Nagasaki","cat":"moto","st":"vu","insp":"Ducati 1199, EBR 1190RS","txt":"Vollverkleidetes Sportmotorrad mit Auspuff unter dem Sitz. Die Carbon RS ist das schnellste Motorrad der früheren Teile und eines der wenigen, die auf der Geraden enorm effektiv und bei Nässe praktisch unfahrbar sind.","search":"nagasaki carbon rs ducati 1199, ebr 1190rs","src":"Erster Trailer","reel":"https://www.google.com/search?tbm=isch&q=Ducati%201199","reelNom":"Ducati 1199","slot":"europeen","thumb":"/img/schemas/nagasaki-carbon-rs.svg"},{"id":"pegassi-bati-801","nom":"Bati 801","marque":"Pegassi","cat":"moto","st":"vu","insp":"Ducati 848","src":"Offizielle Artworks","txt":"Das Sportmotorrad von Pegassi, nach der Ducati 848 gezeichnet: schlanke Verkleidung, für die Unterarme modellierter Tank, extrem gebückte Sitzhaltung. Sie ist in den von Rockstar veröffentlichten Artworks zu sehen, was sie ins Spiel bringt, noch bevor eine Szene sie in Fahrt zeigt.","reel":"https://www.google.com/search?tbm=isch&q=Ducati%20848","reelNom":"Ducati 848","search":"pegassi bati 801 ducati 848","slot":"europeen","thumb":"/img/schemas/pegassi-bati-801.svg"},{"id":"pegassi-faggio","nom":"Faggio","marque":"Pegassi","cat":"moto","st":"vu","insp":"Piaggio Vespa","src":"Extended Look","search":"pegassi faggio piaggio vespa","txt":"Der Roller ist das genaue Gegenteil des restlichen Pegassi-Katalogs – genau das macht den Witz aus. Die Vespa, deren Silhouette er übernimmt, ist ein Designobjekt für sich, 1946 entworfen, um Italien mit möglichst wenig Stahl wieder auf Räder zu bringen. Im Extended Look schlängelt er sich zwischen zwei stehenden Fahrspuren durch.","reel":"https://www.google.com/search?tbm=isch&q=Piaggio%20Vespa","reelNom":"Piaggio Vespa","slot":"europeen","thumb":"/img/schemas/pegassi-faggio.svg"},{"id":"pegassi-faggio-sport","nom":"Faggio Sport","marque":"Pegassi","cat":"moto","st":"vu","insp":"Piaggio Zip, Peugeot V-Clic und Kymco Agility 50","src":"Extended Look","search":"pegassi faggio sport piaggio zip, peugeot v-clic et kymco agility 50","txt":"Die moderne Version des Pegassi-Rollers, im kantigen Design heutiger kleiner 50-cm³-Roller: Kunststoffverkleidung, Gussräder, Scheinwerfer im Beinschild. Weit weg vom Retro-Charme des klassischen Faggio ist er das Gefährt von Kurieren und Schülern – der, den man im Extended Look überall in den Straßen von Vice City sieht. Das Wort Sport verspricht nichts: Er wird die Autoschlange, an der er sich vorbeischlängelt, nicht abhängen.","reel":"https://www.google.com/search?tbm=isch&q=Piaggio%20Zip","reelNom":"Piaggio Zip","slot":"europeen","thumb":"/img/schemas/pegassi-faggio-sport.svg"},{"id":"principe-alvino-v1","nom":"Alvino V1","marque":"Principe","cat":"moto","st":"vu","insp":"Ducati Panigale V2 Sport Bike","src":"Offizielle Screenshots","search":"principe alvino v1 ducati panigale v2 sport bike","txt":"Principe ist die italienische Motorradmarke dieses Universums, im Stil von Ducati. Die Alvino V1 ist ein Sportmotorrad mit Gitterrohrrahmen – eine Bauweise, die diesen Maschinen ihre optische Handschrift ebenso gibt wie ihre Steifigkeit. Die offiziellen Screenshots zeigen sie auf dem Ständer, mit unversehrter Verkleidung.","medias":["jason-duval-01"],"reel":"https://www.google.com/search?tbm=isch&q=Ducati%20Panigale%20V2%20Sport%20Bike","reelNom":"Ducati Panigale V2 Sport Bike","slot":"europeen","thumb":"/img/officiel/jason-duval-01-480.webp"},{"id":"principe-lectro","nom":"Lectro","marque":"Principe","cat":"moto","st":"vu","insp":"Ducati Streetfighter S, MV Agusta Brutale S","src":"Extended Look","txt":"Ein bissiges Naked Bike von Principe, irgendwo zwischen Ducati Streetfighter S und MV Agusta Brutale S: breiter Lenker, sichtbarer Gitterrohrrahmen, nichts, hinter dem man sich vor dem Wind verstecken kann. Im Extended Look jagt sie eine Küstenstraße entlang, das Vorderrad wird leicht.","reel":"https://www.google.com/search?tbm=isch&q=Ducati%20Streetfighter%20S","reelNom":"Ducati Streetfighter S","search":"principe lectro ducati streetfighter s, mv agusta brutale s","slot":"europeen","thumb":"/img/schemas/principe-lectro.svg"},{"id":"shitzu-pcj-600","nom":"PCJ-600","marque":"Shitzu","cat":"moto","st":"comm","insp":"Yamaha YZF-R6","src":"Zuordnung der Community","search":"shitzu pcj-600 yamaha yzf-r6","txt":"Die PCJ-600 ist das Einsteiger-Sportmotorrad der Reihe, angelehnt an die Yamaha YZF-R6. Die 600er-Klasse war lange der Einstieg ins Sportmotorrad: stark genug, um anspruchsvoll zu sein, leicht genug, um handlich zu bleiben. Keine offizielle Bestätigung.","reel":"https://www.google.com/search?tbm=isch&q=Yamaha%20YZF-R6","reelNom":"Yamaha YZF-R6","slot":"japonais","thumb":"/img/schemas/shitzu-pcj-600.svg"},{"id":"western-nightblade","nom":"Nightblade","marque":"Western","cat":"moto","st":"vu","insp":"Harley-Davidson Night Rod Special","txt":"Cruiser mit großem Hubraum, gewölbtem Tank und niedriger Sitzbank. Western ist die Harley-Marke des GTA-Universums.","search":"western nightblade harley-davidson night rod special","src":"Offizielle Screenshots","medias":["electric-fang-tattoo-01"],"imageAlts":{"electric-fang-tattoo-01":"Zwei Motorräder vor Electric Fang Tattoo in GTA VI; rechts ein Cruiser mit breitem Hinterreifen."},"reel":"https://www.google.com/search?tbm=isch&q=Harley-Davidson%20Night%20Rod%20Special","reelNom":"Harley-Davidson Night Rod Special","slot":"americain","thumb":"/img/officiel/electric-fang-tattoo-01-480.webp"},{"id":"western-sovereign","nom":"Sovereign","marque":"Western","cat":"moto","st":"vu","insp":"Harley Davidson Road King","txt":"Verchromter Cruiser mit tief heruntergezogenen Kotflügeln und abnehmbarer Windschutzscheibe. Das amerikanische Tourenmotorrad in seiner klassischsten Form.","search":"western sovereign harley davidson road king","src":"Offizielle Screenshots","medias":["ambrosia-01"],"imageAlts":{"ambrosia-01":"Motorradgruppe unterwegs in Ambrosia in GTA VI."},"reel":"https://www.google.com/search?tbm=isch&q=Harley%20Davidson%20Road%20King","reelNom":"Harley Davidson Road King","slot":"americain","thumb":"/img/officiel/ambrosia-01-480.webp"},{"id":"western-zombie-chopper","nom":"Zombie Chopper","marque":"Western","cat":"moto","st":"vu","insp":"Harley Davidson Fat Bob Custom, Iron 883","src":"Zweiter Trailer","search":"western zombie chopper harley davidson fat bob custom, iron 883","txt":"Der Zombie Chopper ist ein amerikanisches Custom-Bike mit langer Gabel, in der Tradition der Harley-Davidson Fat Bob Custom und Iron 883. Der Chopper entstand aus der Praxis, von einem Serienmotorrad alles abzuhacken (englisch „to chop“), was nicht unbedingt nötig ist – daher der Name. Der Zombie Chopper ist im zweiten Trailer zu sehen; die Identifizierung stammt von der Community.","medias":["electric-fang-tattoo-01"],"imageAlts":{"electric-fang-tattoo-01":"Zwei Motorräder vor Electric Fang Tattoo in GTA VI; links ein Chopper."},"reel":"https://www.google.com/search?tbm=isch&q=Harley%20Davidson%20Fat%20Bob%20Custom","reelNom":"Harley Davidson Fat Bob Custom","slot":"americain","thumb":"/img/officiel/electric-fang-tattoo-01-480.webp"},{"id":"buckingham-maverick","nom":"Maverick","marque":"Buckingham","cat":"helicoptere","st":"vu","insp":"Bell 206L Longranger","src":"Offizielle Screenshots","search":"buckingham maverick bell 206l longranger","txt":"Der Maverick ist im Bild zu sehen, ohne dass Rockstar seinen Namen veröffentlicht hat. Er übernimmt den Aufbau der Bell 206 LongRanger, einer verlängerten Version eines der meistgebauten zivilen Hubschrauber der Welt: sieben Plätze, ein einziges Turbinentriebwerk und eine Zuverlässigkeit, die ihn zum Standardgerät von Nachrichtensendern und Polizeibehörden gemacht hat.","medias":["mount-kalaga-national-park-02"],"imageAlts":{"mount-kalaga-national-park-02":"Rot-weißer Maverick-Hubschrauber im Flug vor den Hügeln, mit einem Passagier an der offenen Tür."},"reel":"https://www.google.com/search?tbm=isch&q=Bell%20206L%20Longranger","reelNom":"Bell 206L Longranger","slot":"americain","thumb":"/img/officiel/mount-kalaga-national-park-02-480.webp"},{"id":"buckingham-police-maverick","nom":"Police Maverick","marque":"Buckingham","cat":"helicoptere","st":"vu","insp":"Eurocopter AS350B","txt":"Der Polizeihubschrauber, mit Suchscheinwerfer und Kamera. Er kommt bei hohen Fahndungsstufen und erzeugt Druck von oben, dem man am Boden nichts entgegensetzen kann.","search":"buckingham police maverick eurocopter as350b","src":"Erster Trailer","reel":"https://www.google.com/search?tbm=isch&q=Eurocopter%20AS350B","reelNom":"Eurocopter AS350B","thumb":"/img/schemas/buckingham-police-maverick.svg"},{"id":"buckingham-supervolito","nom":"SuperVolito","marque":"Buckingham","cat":"helicoptere","st":"vu","insp":"Eurocopter EC145","src":"Erster Trailer","search":"buckingham supervolito eurocopter ec145","txt":"Der SuperVolito ist ein zweimotoriger Geschäftsreise-Hubschrauber, angelehnt an den Eurocopter EC145. Diese Art Maschine dient ebenso dem Transport von Führungskräften wie der Versorgung von Ölplattformen auf See – im Golf von Mexiko ein alltäglicher Einsatz. Im ersten Trailer überfliegt er im Anflug die Bucht.","reel":"https://www.google.com/search?tbm=isch&q=Eurocopter%20EC145","reelNom":"Eurocopter EC145","thumb":"/img/schemas/buckingham-supervolito.svg"},{"id":"buckingham-swift","nom":"Swift","marque":"Buckingham","cat":"helicoptere","st":"vu","insp":"AgustaWestland AW109, Bell 222","src":"Offizielle Screenshots","search":"buckingham swift agustawestland aw109, bell 222","txt":"Der Swift ist ein privater Transporthubschrauber in der Tradition der AgustaWestland AW109: schlanke Silhouette, Einziehfahrwerk, edle Kabine. Das ist die Maschine für alle, die den Staus zwischen Geschäftsviertel und Marina ausweichen wollen. Die offiziellen Screenshots zeigen ihn auf einem Hubschrauberlandeplatz auf einem Dach.","reel":"https://www.google.com/search?tbm=isch&q=AgustaWestland%20AW109","reelNom":"AgustaWestland AW109","slot":"europeen","thumb":"/img/schemas/buckingham-swift.svg"},{"id":"buckingham-valkyrie","nom":"Valkyrie","marque":"Buckingham","cat":"helicoptere","st":"vu","insp":"Bell UH-1Y Venom, Bell 412","src":"Extended Look","txt":"Der Transporthubschrauber von Buckingham, direkter Nachfahre der Bell UH-1 und ihrer Weiterentwicklungen Venom und 412, mit ummanteltem Heckrotor im Fenestron-Stil. Seitliche Schiebetüren und eine zu den Seiten offene Kabine. Der Extended Look begleitet ihn im Tiefflug.","reel":"https://www.google.com/search?tbm=isch&q=Bell%20UH-1Y%20Venom","reelNom":"Bell UH-1Y Venom","search":"buckingham valkyrie bell uh-1y venom, bell 412","slot":"americain","thumb":"/img/schemas/buckingham-valkyrie.svg"},{"id":"buckingham-buzzard","nom":"Buzzard","marque":"Nagasaki","cat":"helicoptere","st":"vu","insp":"AH-6 Little Bird","src":"Zweiter Trailer","search":"nagasaki buzzard ah-6 little bird","txt":"Der Buzzard taucht wieder in Rockstars offiziellem Material auf. Er ist ein leichter zweisitziger Hubschrauber, angelehnt an den AH-6 Little Bird, eine kompakte Maschine, die US-Spezialkräfte gerade deshalb nutzen, weil sie auf engstem Raum landen kann, auch auf Hausdächern.","reel":"https://www.google.com/search?tbm=isch&q=AH-6%20Little%20Bird","reelNom":"AH-6 Little Bird","thumb":"/img/schemas/buckingham-buzzard.svg"},{"id":"nagasaki-police-buzzard","nom":"Police Buzzard","marque":"Nagasaki","cat":"helicoptere","st":"vu","insp":"MH-6 Little Bird","src":"Offizielle Screenshots","txt":"Polizeiversion des Buzzard, mit einer Lackierung, die an die Maschinen des Miami Police Department erinnert. Der MH-6 Little Bird, der ihm als Vorbild dient, ist ein leichter Hubschrauber militärischer Herkunft, den städtische Polizeien wegen seiner geringen Größe und überschaubaren Betriebskosten gewählt haben.","reel":"https://www.google.com/search?tbm=isch&q=MH-6%20Little%20Bird","reelNom":"MH-6 Little Bird","search":"nagasaki police buzzard mh-6 little bird","thumb":"/img/schemas/nagasaki-police-buzzard.svg"},{"id":"western-sea-sparrow","nom":"Sea Sparrow","marque":"Western","cat":"helicoptere","st":"vu","insp":"Sikorsky S-300, früher Hughes 300","src":"Erster Trailer","search":"western sea sparrow sikorsky s-300, anciennement hughes 300","txt":"Der Sea Sparrow ist ein leichter Hubschrauber auf Schwimmern. Als Inspiration gilt der Sikorsky S-300, früher Hughes 300. Die Datenbank ordnet ihn dem ersten Trailer zu, ohne genannten Namen; an den Schwimmern unterscheidet man ihn von der Landversion.","medias":["cover-art-sea-sparrow"],"imageAlts":{"cover-art-sea-sparrow":"Blauer Hubschrauber mit Schwimmern auf einer Illustration des offiziellen Covers von GTA VI"},"reel":"https://www.google.com/search?tbm=isch&q=Sikorsky%20S-300","reelNom":"Sikorsky S-300","thumb":"/img/officiel/cover-art-sea-sparrow-480.webp"},{"id":"buckingham-luxor","nom":"Luxor","marque":"Buckingham","cat":"avion","st":"vu","insp":"Learjet 45","src":"Extended Look","txt":"Der Edel-Businessjet von Buckingham, wie der Shamal auf Basis eines Learjet 45 gebaut, aber mit einer deutlich edleren Innenausstattung. Das ist das Flugzeug für diskrete Ankünfte auf einer privaten Piste. Im Extended Look steht er am Boden, mit ausgeklappter Treppe.","reel":"https://www.google.com/search?tbm=isch&q=Learjet%2045","reelNom":"Learjet 45","search":"buckingham luxor learjet 45","slot":"americain","thumb":"/img/schemas/buckingham-luxor.svg"},{"id":"buckingham-nimbus","nom":"Nimbus","marque":"Buckingham","cat":"avion","st":"vu","insp":"Cessna Citation X","src":"Erster Trailer","txt":"Ein zweistrahliger Businessjet nach dem Vorbild der Cessna Citation X, lange das schnellste Zivilflugzeug auf dem Markt. Schlanker Rumpf, stark gepfeilte Flügel, Triebwerke am Heck. Im ersten Trailer zieht er in großer Höhe über den Himmel von Leonida.","reel":"https://www.google.com/search?tbm=isch&q=Cessna%20Citation%20X","reelNom":"Cessna Citation X","search":"buckingham nimbus cessna citation x","slot":"americain","thumb":"/img/schemas/buckingham-nimbus.svg"},{"id":"buckingham-shamal","nom":"Shamal","marque":"Buckingham","cat":"avion","st":"vu","insp":"Learjet 45","src":"Offizielle Screenshots","search":"buckingham shamal learjet 45","txt":"Rockstar zeigt ihn in seinen Bildern, behält seinen Namen aber für sich. Er ist ein Businessjet nach dem Vorbild des Learjet 45: schmaler Rumpf, Triebwerke am Heck, T-Leitwerk. Der Learjet hat die Klasse der Geschäftsluftfahrt in den 60ern begründet – ganz bewusst als ziviler Kampfjet gedacht.","medias":["vice-city-01"],"reel":"https://www.google.com/search?tbm=isch&q=Learjet%2045","reelNom":"Learjet 45","slot":"americain","thumb":"/img/officiel/vice-city-01-480.webp"},{"id":"jobuilt-mammatus","nom":"Mammatus","marque":"JoBuilt","cat":"avion","st":"vu","insp":"Cessna 172 Skyhawk","src":"Offizielle Screenshots","search":"jobuilt mammatus cessna 172 skyhawk","txt":"Die Maschine ist in Rockstars Bildern zu entdecken, deren Bildunterschriften aber nichts dazu sagen. Ein kleiner einmotoriger Hochdecker im Stil von Cessna – genau die Art Flugzeug, die Floridas Flugplätze füllt: Pilotenausbildung, Schnupperflüge, Privatflüge. Unsere Karte verzeichnet mehrere dieser Flugplätze.","reel":"https://www.google.com/search?tbm=isch&q=Cessna%20172%20Skyhawk","reelNom":"Cessna 172 Skyhawk","slot":"americain","thumb":"/img/schemas/jobuilt-mammatus.svg"},{"id":"mammoth-dodo","nom":"Dodo","marque":"Mammoth","cat":"avion","st":"vu","insp":"De Havilland Canada DHC-2 Beaver","src":"Erster Trailer","search":"mammoth dodo de havilland canada dhc-2 beaver","txt":"Rockstar zeigt ihn, ohne ihn je beim Namen zu nennen. Er ist ein Wasserflugzeug mit hoch angesetzten Tragflächen nach dem Vorbild der De Havilland Beaver, eines kanadischen Flugzeugs für kurze Starts und Landungen auf dem Wasser. Zwischen den Keys, den Sümpfen und den unzähligen Gewässern von Leonida liegt der Nutzen auf der Hand.","medias":["leonida-keys-01"],"reel":"https://www.google.com/search?tbm=isch&q=De%20Havilland%20Canada%20DHC-2%20Beaver","reelNom":"De Havilland Canada DHC-2 Beaver","slot":"europeen","thumb":"/img/officiel/leonida-keys-01-480.webp"},{"id":"mammoth-streamer216","nom":"Streamer216","marque":"Mammoth","cat":"avion","st":"vu","insp":"De Havilland Canada DHC-6 Twin Otter","src":"Zweiter Trailer","txt":"Der zweimotorige Hochdecker für Verbindungen zwischen den Inseln, übernommen von der DHC-6 Twin Otter von De Havilland Canada. Er startet auf kurzer Strecke, landet auf einfachen Pisten und nimmt rund fünfzehn Passagiere mit. Der zweite Trailer zeigt ihn im Endanflug.","reel":"https://www.google.com/search?tbm=isch&q=De%20Havilland%20Canada%20DHC-6%20Twin%20Otter","reelNom":"De Havilland Canada DHC-6 Twin Otter","search":"mammoth streamer216 de havilland canada dhc-6 twin otter","slot":"europeen","thumb":"/img/schemas/mammoth-streamer216.svg"},{"id":"jet","nom":"Jet","marque":"Unbekannte Marke","cat":"avion","st":"vu","insp":"Boeing 747-400, 747-8I","txt":"Verkehrsflugzeug. Seine Präsenz am internationalen Flughafen von Vice City ist vor allem Kulisse, aber die Reihe hat solche Flugzeuge am Ende immer fliegbar gemacht.","search":"marque inconnue jet boeing 747-400, 747-8i","src":"Zweiter Trailer","medias":["trailer-2-jet-037"],"imageAlts":{"trailer-2-jet-037":"Vierstrahliges Verkehrsflugzeug über den Schildern Richtung VCI Airport, zweiter Trailer zu GTA VI bei etwa 00:37."},"reel":"https://www.google.com/search?tbm=isch&q=Boeing%20747-400","reelNom":"Boeing 747-400","slot":"americain","thumb":"/img/officiel/trailer-2-jet-037-480.webp"},{"id":"western-company-duster","nom":"Duster","marque":"Western Company","cat":"avion","st":"vu","insp":"Stearman Model 75","src":"Offizielle Screenshots","search":"western company duster stearman model 75","txt":"Der Doppeldecker fliegt namenlos durch die offiziellen Bilder. Er ist ein Agrarflugzeug in Doppeldecker-Bauweise zum Besprühen von Feldern, in der Tradition des Stearman Model 75: Gitterrohrkonstruktion, offenes Cockpit, festes Fahrwerk. Diese Maschinen, oft umgebaute ehemalige Militär-Schulflugzeuge, fliegen noch heute über die Farmen im Süden der USA.","reel":"https://www.google.com/search?tbm=isch&q=Stearman%20Model%2075","reelNom":"Stearman Model 75","slot":"americain","thumb":"/img/schemas/western-company-duster.svg"},{"id":"xero-blimp","nom":"Blimp","marque":"Xero","cat":"avion","st":"vu","insp":"Goodyear Aerospace GZ-20","src":"Erster Trailer","search":"xero blimp goodyear aerospace gz-20","txt":"Das Werbeluftschiff ist in den USA ein vertrauter Anblick, vor allem über Stadien und bei großen Events. Xero ist die Ölmarke dieses Universums, und diese Art Werbepartnerschaft ist ganz realistisch. Das Luftschiff ist in den Bildern klar zu sehen, sein Name nicht.","reel":"https://www.google.com/search?tbm=isch&q=Goodyear%20Aerospace%20GZ-20","reelNom":"Goodyear Aerospace GZ-20","thumb":"/img/schemas/xero-blimp.svg"},{"id":"airboat-09","nom":"Airboat 09","marque":"Airgator","cat":"bateau","st":"vu","insp":"Propellerboot von Diamondback Hunting & Fishing","src":"Offizielle Screenshots","search":"airgator airboat 09 hydroglisseur diamondback hunting & fishing","txt":"Das Propellerboot ist untrennbar mit den Everglades verbunden: flacher Rumpf, Flugzeugmotor am Heck, erhöhte Sitzreihen für Rundfahrten mit Touristen. Es gleitet über wenige Zentimeter Wasser und pflügt durch die Wasserpflanzen. Der Name Airgator macht keinen Hehl aus dem Bezug zu den Alligatoren, die diese Boote den Besuchern zeigen.","medias":["grassrivers-01"],"reel":"https://www.google.com/search?tbm=isch&q=Hydroglisseur%20Diamondback%20Hunting%20%26%20Fishing","reelNom":"Propellerboot von Diamondback Hunting & Fishing","thumb":"/img/officiel/grassrivers-01-480.webp"},{"id":"btn-delmar","nom":"Delmar","marque":"BTN","cat":"bateau","st":"vu","insp":"BTN Delmar","src":"Erster Trailer","search":"btn delmar btn delmar","txt":"Der Delmar ist ein Küstenfischerboot mit Kabine, wie sie für Tagesausfahrten aus den Marinas Floridas auslaufen. Er ist zum Arbeiten gebaut: freies Deck, Rutenhalter, hoher Freibord. Der erste Trailer zeigt ihn an einem Steg festgemacht.","fam":"Küstenfischerboot mit Kabine","reel":"https://www.google.com/search?tbm=isch&q=BTN%20Delmar","reelNom":"BTN Delmar","thumb":"/img/schemas/btn-delmar.svg"},{"id":"crest-kayak","nom":"Kayak","marque":"Crest","cat":"bateau","st":"officiel","insp":"Crescent-Kajak, mehrere Varianten","src":"Ultimate Edition","vues":[],"credit":"Offizieller Screenshot von Rockstar Games","search":"crest kayak kayak crescent, plusieurs variantes","txt":"Das Kajak wird von Rockstar benannt, und unser offizieller Screenshot zeigt es im Einsatz bei Sonnenuntergang, mit gut lesbarer Marke Crest auf dem Rumpf. Es ist ein Sit-on-Top-Seekajak, ein offenes Boot, das sich besonders für die warmen, flachen Gewässer der Keys eignet. Ein weiterer Screenshot zeigt es vor Jasons Unterschlupf.","edition":"Ultimate Edition","medias":["crest-kayak","jason-s-safehouse-vehicles","mount-kalaga-national-park-06"],"perso":"jason","imageAlts":{"mount-kalaga-national-park-06":"Oranges Crest-Kajak auf einem Fluss unter einer Eisenbahnbrücke im Mount Kalaga National Park."},"vuesDeclarees":["profil"],"reel":"https://www.google.com/search?tbm=isch&q=Kayak%20Crescent","reelNom":"Crescent-Kajak","slot":"americain","thumb":"/img/officiel/crest-kayak-480.webp"},{"id":"dinka-jetmax","nom":"Jetmax","marque":"Dinka","cat":"bateau","st":"comm","insp":null,"src":"Zuordnung der Community","search":"dinka jetmax hors-bord de sport a coque en v","txt":"Der Jetmax ist ein Sportboot, gebaut für Tempo auf ruhigem Wasser: stromlinienförmiger Rumpf, niedriger Steuerstand, übergroße Motorisierung. Die geschützten Buchten von Vice City sind das ideale Revier. Modell von Rockstar nicht bestätigt.","fam":"Sportboot mit V-Rumpf","reel":"https://www.google.com/search?tbm=isch&q=Hors-bord%20de%20sport%20%C3%A0%20coque%20en%20V","reelNom":"Sportboot mit V-Rumpf","thumb":"/img/schemas/dinka-jetmax.svg"},{"id":"nagasaki-marquis","nom":"Marquis","marque":"Dinka","cat":"bateau","st":"vu","insp":"Adjutor Yachts","src":"Zweiter Trailer","search":"dinka marquis adjutor yachts","txt":"Der Marquis ist als Fahrtensegler mit Kajüte erfasst, mit Adjutor Yachts als Inspiration. In unserer Datenbank ist als Marke Dinka hinterlegt. Sein Auftauchen wird dem zweiten Trailer zugeordnet, ohne offizielle Bildunterschrift mit seinem Namen.","reel":"https://www.google.com/search?tbm=isch&q=Adjutor%20Yachts","reelNom":"Adjutor Yachts","slot":"europeen","thumb":"/img/schemas/nagasaki-marquis.svg"},{"id":"lure-predator-l35p","nom":"Predator L35P","marque":"Lure","cat":"bateau","st":"vu","insp":"Contender 25T","src":"Offizielle Screenshots","txt":"Fischerboot mit Mittelkonsole, T-Top und Auslegern. Der Schriftzug Lure Predator ist auf den offiziellen Screenshots zu sehen – damit ist es eines der wenigen namentlich bekannten Boote im Spiel. Das Boot gibt es auch in Polizeilackierung.","search":"lure predator l35p contender 25t","medias":["leonida-keys-05"],"imageAlts":{"leonida-keys-05":"Boote versammelt in den Leonida Keys, im Vordergrund ein Motorboot mit dem Schriftzug Lure Predator."},"reel":"https://www.google.com/search?tbm=isch&q=Contender%2025T","reelNom":"Contender 25T","slot":"americain","thumb":"/img/officiel/leonida-keys-05-480.webp"},{"id":"lure-predator-l35p-police","nom":"Predator L35P der Polizei","marque":"Lure","cat":"bateau","st":"vu","insp":"Contender 25T","src":"Offizielle Screenshots","txt":"Version des Predator L35P in Polizeilackierung: Blaulicht, Reflexstreifen, Suchscheinwerfer. Die Wasserschutzpolizei gehört in einem Bundesstaat mit so vielen Kanälen und Küsten zum Alltag, und sie greift bei Verfolgungsjagden auf dem Wasser ein.","search":"lure predator l35p de police contender 25t","medias":["shitzu-squalo-04"],"reel":"https://www.google.com/search?tbm=isch&q=Contender%2025T","reelNom":"Contender 25T","slot":"americain","thumb":"/img/officiel/shitzu-squalo-04-480.webp"},{"id":"lure-predator-s23","nom":"Predator S23","marque":"Lure","cat":"bateau","st":"vu","insp":"Contender 25 Bay","src":"Offizielle Screenshots","txt":"Kleines Fischerboot für flache Gewässer, sieben Meter, mit Rumpf für geringen Tiefgang, gebaut für Buchten und Mangroven. Das unter Floridas Anglern verbreitetste Format, weit entfernt von Hochseebooten.","search":"lure predator s23 contender 25 bay","medias":["leonida-keys-05"],"imageAlts":{"leonida-keys-05":"Boote versammelt in den Leonida Keys, im Vordergrund ein Motorboot mit dem Schriftzug Lure Predator."},"reel":"https://www.google.com/search?tbm=isch&q=Contender%2025%20Bay","reelNom":"Contender 25 Bay","slot":"americain","thumb":"/img/officiel/leonida-keys-05-480.webp"},{"id":"azimut-85","nom":"Azimut 85","marque":"Unbekannte Marke","cat":"bateau","st":"vu","insp":"Azimut 85","src":"Zweiter Trailer","txt":"Sechsundzwanzig Meter lange Motoryacht, in der Klasse der großen Fahrtenyachten. Die Azimut 85 stammt von einer italienischen Werft, deren Modelle die Marinas von Miami Beach füllen. Ihr Name im Spiel wurde von Rockstar nicht bekannt gegeben.","search":"marque inconnue azimut 85 azimut 85","reel":"https://www.google.com/search?tbm=isch&q=Azimut%2085","reelNom":"Azimut 85","slot":"europeen","thumb":"/img/schemas/azimut-85.svg"},{"id":"azimut-atlantis-45","nom":"Azimut Atlantis 45","marque":"Unbekannte Marke","cat":"bateau","st":"vu","insp":"Azimut Atlantis 45","src":"Zweiter Trailer","txt":"Kajütboot, vierzehn Meter, das Zwischenformat zwischen Tages-Motorboot und Yacht zum Wohnen an Bord. Das ist das Boot des wohlhabenden Besitzers, der am Wochenende rausfährt, nicht das eines Reeders. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue azimut atlantis 45 azimut atlantis 45","reel":"https://www.google.com/search?tbm=isch&q=Azimut%20Atlantis%2045","reelNom":"Azimut Atlantis 45","slot":"europeen","thumb":"/img/schemas/azimut-atlantis-45.svg"},{"id":"fishing-boat","nom":"Fischerboot","marque":"Unbekannte Marke","cat":"bateau","st":"vu","insp":"Steiger Craft 31 Miami","src":"Offizielle Screenshots","txt":"Küstenfischerboot mit geschlossener Kabine, neun Meter. Das Steiger Craft, dessen Linien das Boot übernimmt, trägt Miami buchstäblich in seiner Modellbezeichnung. Es ist das Werkzeug des Berufsfischers, nicht das Spielzeug des Freizeitkapitäns.","search":"marque inconnue bateau de peche steiger craft 31 miami","reel":"https://www.google.com/search?tbm=isch&q=Steiger%20Craft%2031%20Miami","reelNom":"Steiger Craft 31 Miami","thumb":"/img/schemas/fishing-boat.svg"},{"id":"water-taxi","nom":"Wassertaxi","marque":"Unbekannte Marke","cat":"bateau","st":"vu","insp":"Wassertaxi von Miami","src":"Extended Look","txt":"Passagier-Wassershuttle, im Extended Look entdeckt. Miami betreibt ein echtes Wassertaxi-Netz zwischen Innenstadt, Strand und Inseln. Seine Präsenz in Leonida deutet auf ein weiteres Fortbewegungsmittel hin, neben Bus und Hochbahn.","search":"marque inconnue bateau-taxi bateau-taxi de miami","reel":"https://www.google.com/search?tbm=isch&q=Bateau-taxi%20de%20Miami","reelNom":"Wassertaxi von Miami","thumb":"/img/schemas/water-taxi.svg"},{"id":"bavaria-sr33","nom":"Bavaria SR33","marque":"Unbekannte Marke","cat":"bateau","st":"vu","insp":"Bavaria SR33","src":"Erster Trailer","txt":"Deutsches Sportboot mit tiefem Rumpf, gebaut für raue See statt für die Lagune. Bavaria ist vor allem für seine Segelboote bekannt, und diese Motorboot-Reihe ist sein Versuch auf dem Sportbootmarkt. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue bavaria sr33 bavaria sr33","reel":"https://www.google.com/search?tbm=isch&q=Bavaria%20SR33","reelNom":"Bavaria SR33","slot":"europeen","thumb":"/img/schemas/bavaria-sr33.svg"},{"id":"clarion","nom":"Clarion","marque":"Unbekannte Marke","cat":"bateau","st":"vu","insp":"Cigarette 38 Top Gun","src":"Erster Trailer","txt":"Rennboot mit sehr schlankem Rumpf, in der Tradition der Cigarette 38 Top Gun. Diese Boote haben in Miami eine schwere Geschichte: Für Offshore-Rennen gebaut, wurden sie in den 80ern massenhaft von Schmugglern genutzt, weil sie den Booten des Zolls davonfuhren. Passender für Vice City geht es kaum.","search":"marque inconnue clarion cigarette 38 top gun","reel":"https://www.google.com/search?tbm=isch&q=Cigarette%2038%20Top%20Gun","reelNom":"Cigarette 38 Top Gun","slot":"americain","thumb":"/img/schemas/clarion.svg"},{"id":"contender-39st","nom":"Contender 39ST","marque":"Unbekannte Marke","cat":"bateau","st":"vu","insp":"Contender 39ST","src":"Offizielle Screenshots","txt":"Boot für Hochseeangeln mit Mittelkonsole, zwölf Meter, vier Außenborder am Heck. Contender ist eine Werft aus Südflorida, deren Boote dafür gebaut sind, weit und schnell rauszufahren. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue contender 39st contender 39st","reel":"https://www.google.com/search?tbm=isch&q=Contender%2039ST","reelNom":"Contender 39ST","slot":"americain","thumb":"/img/schemas/contender-39st.svg"},{"id":"crownline-275-ss","nom":"Crownline 275 SS","marque":"Unbekannte Marke","cat":"bateau","st":"vu","insp":"Crownline 275 SS","src":"Erster Trailer","txt":"Freizeit-Bowrider, acht Meter, offenes Cockpit und Sitzbank im Bug. Das ist das amerikanische Familienboot schlechthin: Wasserski, Baden, Drinks vor Anker. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue crownline 275 ss crownline 275 ss","reel":"https://www.google.com/search?tbm=isch&q=Crownline%20275%20SS","reelNom":"Crownline 275 SS","slot":"americain","thumb":"/img/schemas/crownline-275-ss.svg"},{"id":"crusader-boats-gfy","nom":"Crusader Boats GFY","marque":"Unbekannte Marke","cat":"bateau","st":"vu","insp":"Crusader Boats GFY","src":"Erster Trailer","txt":"Tauchboot mit freiem Deck, zehn Meter, mit Badeplattform und Flaschenhalterungen. Floridas Riffe ernähren eine ganze Wirtschaft rund um Tauchausfahrten, und genau so ein Boot chartert man für einen Tag. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue crusader boats gfy crusader boats gfy","reel":"https://www.google.com/search?tbm=isch&q=Crusader%20Boats%20GFY","reelNom":"Crusader Boats GFY","thumb":"/img/schemas/crusader-boats-gfy.svg"},{"id":"shipyard-de-hoop-brion","nom":"De Hoop Brion","marque":"Unbekannte Marke","cat":"bateau","st":"vu","insp":"Shipyard De Hoop Brion","src":"Offizielle Screenshots","txt":"Niederländisches Arbeitsschiff mit Arbeitsrumpf und Deckskran. Es ist weder ein Freizeitboot noch ein Fischerboot, sondern eines dieser Arbeitsschiffe, die Handelshäfen bevölkern. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue de hoop brion shipyard de hoop brion","reel":"https://www.google.com/search?tbm=isch&q=Shipyard%20De%20Hoop%20Brion","reelNom":"Shipyard De Hoop Brion","thumb":"/img/schemas/shipyard-de-hoop-brion.svg"},{"id":"ferry","nom":"Fähre","marque":"Unbekannte Marke","cat":"bateau","st":"vu","insp":"Fähre von Fisher Island","src":"Extended Look","txt":"Personen- und Autofähre nach dem Vorbild derer, die Fisher Island anfahren, die Privatinsel vor Miami Beach, die nur per Boot erreichbar ist. Ihre Präsenz deutet darauf hin, dass ein Teil der Karte von Leonida nicht über die Straße verbunden ist.","search":"marque inconnue ferry ferry de fisher island","reel":"https://www.google.com/search?tbm=isch&q=Ferry%20de%20Fisher%20Island","reelNom":"Fähre von Fisher Island","thumb":"/img/schemas/ferry.svg"},{"id":"frauscher-1017-gt","nom":"Frauscher 1017 GT","marque":"Unbekannte Marke","cat":"bateau","st":"vu","insp":"Frauscher 1017 GT","src":"Erster Trailer","txt":"Österreichisches Day Boat mit sehr markanter Linienführung, zehn Meter. Frauscher formt seine Rümpfe wie Sportwagenkarosserien, was der Werft einen ganz eigenen Ruf im Bootsbau eingebracht hat. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue frauscher 1017 gt frauscher 1017 gt","reel":"https://www.google.com/search?tbm=isch&q=Frauscher%201017%20GT","reelNom":"Frauscher 1017 GT","slot":"europeen","thumb":"/img/schemas/frauscher-1017-gt.svg"},{"id":"highfield-sport-900","nom":"Highfield Sport 900","marque":"Unbekannte Marke","cat":"bateau","st":"vu","insp":"Highfield Sport 900","src":"Offizielle Screenshots","txt":"RIB-Schlauchboot von neun Metern, Aluminiumrumpf und aufblasbare Schläuche. Diese Boote dienen als Beiboot großer Yachten und als schneller Shuttle zwischen Ankerplatz und Küste. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue highfield sport 900 highfield sport 900","reel":"https://www.google.com/search?tbm=isch&q=Highfield%20Sport%20900","reelNom":"Highfield Sport 900","thumb":"/img/schemas/highfield-sport-900.svg"},{"id":"horizon-power-catamarans-pc60","nom":"Horizon PC60","marque":"Unbekannte Marke","cat":"bateau","st":"vu","insp":"Horizon Power Catamarans PC60","src":"Erster Trailer","txt":"Motor-Katamaran von achtzehn Metern. Die zwei Rümpfe bieten eine Stabilität und einen Wohnraum, die ein gleich langer Einrumpfer nicht erreicht – um den Preis einer Breite, die das Anlegen erschwert. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue horizon pc60 horizon power catamarans pc60","reel":"https://www.google.com/search?tbm=isch&q=Horizon%20Power%20Catamarans%20PC60","reelNom":"Horizon Power Catamarans PC60","thumb":"/img/schemas/horizon-power-catamarans-pc60.svg"},{"id":"lurssen-73m-coral-ocean","nom":"Lürssen 73m","marque":"Unbekannte Marke","cat":"bateau","st":"vu","insp":"Lürssen Coral Ocean","src":"Erster Trailer","txt":"Superyacht von dreiundsiebzig Metern, die Spitze der Boots-Hierarchie im Spiel. Lürssen ist die deutsche Werft, die die größten Privatyachten der Welt baut. Ein solches Schiff vor Anker ist kein Fahrzeug, sondern Kulisse – und ein Statussymbol. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue lurssen 73m lurssen coral ocean","reel":"https://www.google.com/search?tbm=isch&q=L%C3%BCrssen%20Coral%20Ocean","reelNom":"Lürssen Coral Ocean","thumb":"/img/schemas/lurssen-73m-coral-ocean.svg"},{"id":"cruise-ship","nom":"Kreuzfahrtschiff","marque":"Unbekannte Marke","cat":"bateau","st":"vu","insp":"Royal Caribbean Voyager","src":"Offizielle Screenshots","txt":"Kreuzfahrtschiff, eines der größten beweglichen Objekte im Spiel. Der Hafen von Miami ist der größte Kreuzfahrthafen der Welt, und diese Schiffe gehören ebenso zur Silhouette der Stadt wie ihre Hotels. Steuerbar wird es wohl kaum sein, aber seine Präsenz im Hafen prägt die Kulisse.","search":"marque inconnue paquebot de croisiere royal caribbean voyager","reel":"https://www.google.com/search?tbm=isch&q=Royal%20Caribbean%20Voyager","reelNom":"Royal Caribbean Voyager","thumb":"/img/schemas/cruise-ship.svg"},{"id":"rb-s","nom":"RB-S","marque":"Unbekannte Marke","cat":"bateau","st":"vu","insp":"Küstenwachboot RB-S","src":"Offizielle Screenshots","txt":"Einsatzboot der Küstenwache, fester Rumpf mit Schläuchen, Außenbordmotoren. Das Response Boat Small ist das Standard-Patrouillenboot der US Coast Guard. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue rb-s vedette garde-cotes rb-s","reel":"https://www.google.com/search?tbm=isch&q=Vedette%20garde-c%C3%B4tes%20RB-S","reelNom":"Küstenwachboot RB-S","thumb":"/img/schemas/rb-s.svg"},{"id":"rb-s-ii","nom":"RB-S II","marque":"Unbekannte Marke","cat":"bateau","st":"vu","insp":"Küstenwachboot RB-S II","src":"Offizielle Screenshots","txt":"Zweite Generation des Patrouillenboots der Küstenwache, länger und stärker motorisiert. Es patrouilliert an den Küsten und in den Durchfahrten, während sich die Wasserschutzpolizei auf die Binnengewässer beschränkt. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue rb-s ii vedette garde-cotes rb-s ii","reel":"https://www.google.com/search?tbm=isch&q=Vedette%20garde-c%C3%B4tes%20RB-S%20II","reelNom":"Küstenwachboot RB-S II","thumb":"/img/schemas/rb-s-ii.svg"},{"id":"riva-86-domino","nom":"Riva 86 Domino","marque":"Unbekannte Marke","cat":"bateau","st":"vu","insp":"Riva 86 Domino","src":"Erster Trailer","txt":"Italienische Yacht von sechsundzwanzig Metern. Riva ist für Boote, was Ferrari für Autos ist: ein Name, der als Kurzformel für Reichtum und Geschmack dient. Der Domino ist die moderne Variante davon, ganz Glas und straffe Linien. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue riva 86 domino riva 86 domino","reel":"https://www.google.com/search?tbm=isch&q=Riva%2086%20Domino","reelNom":"Riva 86 Domino","slot":"europeen","thumb":"/img/schemas/riva-86-domino.svg"},{"id":"sea-ray-350-sundancer","nom":"Sea Ray 350 Sundancer","marque":"Unbekannte Marke","cat":"bateau","st":"vu","insp":"Sea Ray 350 Sundancer","src":"Erster Trailer","txt":"Kajütboot von elf Metern, mit Koje und Pantry unter Deck. Sea Ray ist der größte amerikanische Hersteller von Freizeitbooten, und der Sundancer seine meistverkaufte Reihe. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue sea ray 350 sundancer sea ray 350 sundancer","reel":"https://www.google.com/search?tbm=isch&q=Sea%20Ray%20350%20Sundancer","reelNom":"Sea Ray 350 Sundancer","slot":"americain","thumb":"/img/schemas/sea-ray-350-sundancer.svg"},{"id":"sea-doo-rxt-x-300","nom":"Sea-Doo RXT-X 300","marque":"Unbekannte Marke","cat":"bateau","st":"vu","insp":"Sea-Doo RXT-X 300","src":"Erster Trailer","txt":"Leistungsstarker Jetski für drei Personen, nicht zu verwechseln mit dem Seashark, der schon in dieser Datenbank ist. Der RXT-X ist die sportliche Version der Reihe, die über hundert Stundenkilometer schafft. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue sea-doo rxt-x 300 sea-doo rxt-x 300","reel":"https://www.google.com/search?tbm=isch&q=Sea-Doo%20RXT-X%20300","reelNom":"Sea-Doo RXT-X 300","slot":"americain","thumb":"/img/schemas/sea-doo-rxt-x-300.svg"},{"id":"skater-388","nom":"Skater 388","marque":"Unbekannte Marke","cat":"bateau","st":"vu","insp":"Skater 388","src":"Erster Trailer","txt":"Offshore-Rennkatamaran, mit einem Tunnel in der Rumpfmitte, der das Boot bei hoher Geschwindigkeit anhebt. Diese Boote schaffen über zweihundert Stundenkilometer und haben außerhalb von Rennen und Angeberei keinen Nutzen. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue skater 388 skater 388","reel":"https://www.google.com/search?tbm=isch&q=Skater%20388","reelNom":"Skater 388","slot":"americain","thumb":"/img/schemas/skater-388.svg"},{"id":"nagasaki-dinghy","nom":"Dinghy","marque":"Nagasaki","cat":"bateau","st":"vu","insp":"Festrumpfschlauchboot","src":"Zweiter Trailer","search":"nagasaki dinghy rigid-hulled inflatable boat","txt":"Das Dinghy ist ein Festrumpfschlauchboot: fester Rumpf mit aufblasbaren Schläuchen darüber. Es ist das Arbeitsboot schlechthin, um ein Boot vor Anker zu erreichen, zum Tauchen oder für schnelle Einsätze. Der zweite Trailer lässt es zwischen zwei Mangrovenufern dahinflitzen.","reel":"https://www.google.com/search?tbm=isch&q=Rigid-hulled%20inflatable%20boat","reelNom":"Festrumpfschlauchboot","thumb":"/img/schemas/nagasaki-dinghy.svg"},{"id":"pegassi-speeder","nom":"Speeder","marque":"Pegassi","cat":"bateau","st":"vu","insp":"Coeur 290 Nighthawk, Cherubini Classic 20","src":"Erster Trailer","search":"pegassi speeder coeur 290 nighthawk, cherubini classic 20","txt":"Der Speeder ist ein Hochleistungs-Rennboot in der Tradition der Cigarette-Racing-Boote. Diese Boote mit tiefem V-Rumpf haben in Miami eine besondere Geschichte: In den 70ern für Offshore-Rennen gebaut, wurden sie entlang der Küsten Floridas schnell auch für andere Tätigkeiten genutzt. Im ersten Trailer rast er mit Vollgas, den Bug aus dem Wasser.","reel":"https://www.google.com/search?tbm=isch&q=Coeur%20290%20Nighthawk","reelNom":"Coeur 290 Nighthawk","thumb":"/img/schemas/pegassi-speeder.svg"},{"id":"shitzu-longfin","nom":"Longfin","marque":"Shitzu","cat":"bateau","st":"comm","insp":"Hochsee-Fischerboot","txt":"Boot für Hochseeangeln mit hoher Kabine, Turm und Auslegern. Die Art Boot, die man an der ganzen Küste Floridas für einen Tag chartert – und die in der Fiktion wie in der Realität auch anderen Geschäften dient.","search":"shitzu longfin vedette de peche hauturiere","src":"Zuordnung der Community","reel":"https://www.google.com/search?tbm=isch&q=Vedette%20de%20p%C3%AAche%20hauturi%C3%A8re","reelNom":"Hochsee-Fischerboot","thumb":"/img/schemas/shitzu-longfin.svg"},{"id":"shitzu-squalo","nom":"Squalo","marque":"Shitzu","cat":"bateau","st":"officiel","insp":"Chris-Craft Stinger 390x","src":"Ultimate Edition","vues":[],"credit":"Offizieller Screenshot von Rockstar Games","search":"shitzu squalo chris-craft stinger 390x","txt":"Der Name des Squalo steht schwarz auf weiß in der Vorstellung der Ultimate Edition, und die offiziellen Screenshots sind eindeutig: Das Shitzu-Logo und der Name Squalo sind auf Rumpf und Windschutzscheibe zu lesen. Man sieht die Lackierung mit Palmblattmuster, das Teakdeck, die Angelruten, eine Tauchflasche und das Kennzeichen VB 0522 05. Der Rumpf stammt vom Chris-Craft Stinger 390x, einem Sportboot der 80er, dessen flache Silhouette und spitze Nase untrennbar zur Bildwelt von Miami gehören.","edition":"Ultimate Edition","medias":["shitzu-squalo-01","shitzu-squalo-02","shitzu-squalo-03","shitzu-squalo-04"],"vuesDeclarees":["face","profil","arriere","detail"],"reel":"https://www.google.com/search?tbm=isch&q=Chris-Craft%20Stinger%20390x","reelNom":"Chris-Craft Stinger 390x","slot":"americain","thumb":"/img/officiel/shitzu-squalo-01-480.webp"},{"id":"shitzu-tropic","nom":"Tropic","marque":"Shitzu","cat":"bateau","st":"vu","insp":"Sea Ray 300 Sundancer","src":"Erster Trailer","search":"shitzu tropic sea ray 300 sundancer","txt":"Der Tropic ist ein Kajütboot für die Freizeit, angelehnt an den Sea Ray 300 Sundancer. Das ist das amerikanische Familienboot schlechthin: geräumig genug, um an Bord zu schlafen, seetüchtig genug, um die Bucht zu verlassen, und tausendfach an der ganzen Küste Floridas verkauft. Die Art Boot, die man hinter den Häusern an den Kanälen festgemacht findet.","medias":["trailer-1-tropic-011"],"imageAlts":{"trailer-1-tropic-011":"Weißes Kajütboot von oben gesehen in der Nähe von Delfinen, erster Trailer zu GTA VI bei etwa 00:11."},"reel":"https://www.google.com/search?tbm=isch&q=Sea%20Ray%20300%20Sundancer","reelNom":"Sea Ray 300 Sundancer","slot":"americain","thumb":"/img/officiel/trailer-1-tropic-011-480.webp"},{"id":"speedophile-seashark","nom":"Seashark","marque":"Speedophile","cat":"bateau","st":"officiel","insp":"Sea-Doo GTX","src":"Zweiter Trailer","search":"speedophile seashark sea-doo gtx","txt":"Sein Name ist im zweiten Trailer seitlich am Rumpf zu lesen, als Jason und Lucia damit mit Vollgas über die Bucht jagen. Er ist ein Jetski für drei Personen, angelehnt an den Sea-Doo GTX: Jetantrieb, Verbundrumpf, keine sichtbare Schraube. Der Markenname ist einer der direktesten Witze im Katalog.","medias":["trailer-2-seashark-141"],"imageAlts":{"trailer-2-seashark-141":"Jason und Lucia auf einem grünen Jetski; der Name Seashark ist auf dem Rumpf zu lesen, zweiter Trailer zu GTA VI bei etwa 02:21."},"reel":"https://www.google.com/search?tbm=isch&q=Sea-Doo%20GTX","reelNom":"Sea-Doo GTX","slot":"americain","thumb":"/img/officiel/trailer-2-seashark-141-480.webp"},{"id":"vortex-airboat","nom":"Airboat","marque":"Vortex","cat":"bateau","st":"vu","insp":"Propellerboot Panther Airboat","src":"Erster Trailer","txt":"Das Propellerboot ist die echte Neuheit auf dem Wasser in GTA VI: noch nie in der Reihe gesehen. Flacher Rumpf, riesiger Luftpropeller im Käfig: Es gleitet über wenige Zentimeter Wasser und kommt dorthin, wo kein anderer Rumpf durchkommt. Diese Art Gefährt verbindet man mit den Sümpfen Floridas. Wie man sich in den Grassrivers fortbewegen kann, muss im Spiel noch geprüft werden.","search":"vortex airboat hydroglisseur panther airboat","medias":["grassrivers-03"],"imageAlts":{"grassrivers-03":"Propellerboot von oben gesehen zwischen Alligatoren und Wasserpflanzen in Grassrivers."},"reel":"https://www.google.com/search?tbm=isch&q=Hydroglisseur%20Panther%20Airboat","reelNom":"Propellerboot Panther Airboat","thumb":"/img/officiel/grassrivers-03-480.webp"},{"id":"bravado-bison-1800-police","nom":"Bison 1800 (Polizei)","marque":"Bravado","cat":"service","st":"vu","insp":"Ram 1500 DT","src":"Offizielle Screenshots","txt":"Patrouillenvariante des Bison 1800. Behörden in Südflorida setzen tatsächlich Pick-ups dieser Größe für Einsätze abseits befestigter Straßen ein, auf Pisten in Feuchtgebieten oder an Strandzufahrten, wo ein normaler Streifenwagen stecken bleibt.","reel":"https://www.google.com/search?tbm=isch&q=Ram%201500%20DT","reelNom":"Ram 1500 DT","search":"bravado bison 1800 (police) ram 1500 dt","thumb":"/img/schemas/bravado-bison-1800-police.svg"},{"id":"bravado-buffalo-stx-pursuit","nom":"Buffalo STX Pursuit","marque":"Bravado","cat":"service","st":"vu","insp":"Dodge Charger Pursuit","src":"Erster Trailer","search":"bravado buffalo stx pursuit dodge charger pursuit","txt":"Streifenversion des Buffalo STX: Lichtbalken, Lackierung der Behörde, verstärkte Federung und Kühlung. In den USA verkaufen die Hersteller tatsächlich zugelassene Polizeivarianten, die sich technisch von den zivilen Modellen unterscheiden. Im ersten Trailer jagt er mit Blaulicht in eine Verfolgungsjagd.","medias":["jason-and-lucia-09","vice-city-06"],"imageAlts":{"jason-and-lucia-09":"Jason und Lucia auf einem gelben Motorrad, identifiziert als Maibatsu Sanchez, verfolgt von der Polizei.","vice-city-06":"Buffalo STX der Vice Beach Police, umringt von Polizisten und Passantinnen vor dem Ocean View Hotel."},"reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Charger%20Pursuit","reelNom":"Dodge Charger Pursuit","slot":"americain","thumb":"/img/officiel/jason-and-lucia-09-480.webp"},{"id":"bravado-gauntlet-interceptor","nom":"Gauntlet Interceptor","marque":"Bravado","cat":"service","st":"vu","insp":"Dodge Challenger in Polizeiausführung","src":"Erster Trailer","search":"bravado gauntlet interceptor dodge challenger en configuration de police","txt":"Abfangvariante des Gauntlet, gebaut für die Verfolgung statt für die Streife. US-Behörden setzen regelmäßig Muscle-Cars in dieser Rolle ein – weniger wegen ihrer tatsächlichen Wirksamkeit als wegen ihrer abschreckenden Wirkung. Im ersten Trailer steht er quer auf der Fahrbahn, Türen offen.","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Challenger%20en%20configuration%20de%20police","reelNom":"Dodge Challenger in Polizeiausführung","slot":"americain","thumb":"/img/schemas/bravado-gauntlet-interceptor.svg"},{"id":"bravado-police-cruiser-buffalo","nom":"Police Cruiser (Buffalo)","marque":"Bravado","cat":"service","st":"vu","insp":"Dodge Charger","txt":"Der Buffalo in der Lackierung der Stadtstreife. Die Polizei von Leonida fährt nicht überall dasselbe Fahrzeug: Stadt, Autobahn und Hinterland haben jeweils ihre eigene Ausführung.","search":"bravado police cruiser (buffalo) dodge charger","src":"Erster Trailer","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Charger","reelNom":"Dodge Charger","slot":"americain","thumb":"/img/schemas/bravado-police-cruiser-buffalo.svg"},{"id":"brute-ambulance","nom":"Ambulance","marque":"Brute","cat":"service","st":"vu","insp":"Chevrolet Express 3500 als Fahrgestell mit Fahrerhaus","src":"Extended Look","txt":"Der Krankenwagen von Leonida folgt dem üblichen amerikanischen Format: ein Chevrolet Express als Fahrgestell mit Fahrerhaus, darauf ein aufgesetzter Patientenraum, breiter als die Kabine. In den USA werden diese Aufbauten von spezialisierten Karosseriebauern montiert – daher der deutliche Bruch in der Linie direkt hinter den Vordertüren.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Express%203500%20ch%C3%A2ssis-cabine","reelNom":"Chevrolet Express 3500 als Fahrgestell mit Fahrerhaus","search":"brute ambulance chevrolet express 3500 chassis-cabine","slot":"americain","thumb":"/img/schemas/brute-ambulance.svg"},{"id":"brute-bus","nom":"Bus","marque":"Brute","cat":"service","st":"vu","insp":"New Flyer Xcelsior","txt":"Niederflur-Stadtbus. Einige Haltestellen sind auf unserer Karte eingetragen. Dieses Fahrzeug ist aus offiziellem Material erfasst; was du als Spieler damit machen kannst, muss im Spiel noch geprüft werden.","search":"brute bus new flyer xcelsior","src":"Erster Trailer","reel":"https://www.google.com/search?tbm=isch&q=New%20Flyer%20Xcelsior","reelNom":"New Flyer Xcelsior","thumb":"/img/schemas/brute-bus.svg"},{"id":"brute-police-riot","nom":"Police Riot","marque":"Brute","cat":"service","st":"vu","insp":"Lenco BEAR","src":"Zweiter Trailer","search":"brute police riot lenco bear","txt":"Der gepanzerte Einsatzwagen der Polizei ist im Bild zu sehen, seine Bezeichnung bleibt unbekannt. Diese Fahrzeuge, oft Militärüberschuss, der an örtliche Polizeien weitergegeben wurde, sind in den USA zum Thema öffentlicher Debatten geworden. Ihre Präsenz in einer Stadt wie Vice City ist alles andere als nebensächlich.","medias":["trailer-2-police-riot-119"],"imageAlts":{"trailer-2-police-riot-119":"Schwarzer gepanzerter Transporter gegenüber Lucia, links neben dem von der Explosion weggeschleuderten Auto, zweiter Trailer zu GTA VI bei etwa 01:59."},"reel":"https://www.google.com/search?tbm=isch&q=Lenco%20BEAR","reelNom":"Lenco BEAR","slot":"americain","thumb":"/img/officiel/trailer-2-police-riot-119-480.webp"},{"id":"brute-rental-shuttle-bus","nom":"Rental Shuttle Bus","marque":"Brute","cat":"service","st":"vu","insp":"1996-2002 Chevrolet Express","txt":"Shuttle-Kleinbus, der Terminals mit Parkplätzen und Hotels verbindet. Ein Fahrzeug, das man nur an Flughäfen bemerkt – und Leonida hat mehrere davon.","search":"brute rental shuttle bus 1996-2002 chevrolet express","src":"Zweiter Trailer","medias":["leonida-keys-02"],"imageAlts":{"leonida-keys-02":"Weißer Kleinbus rechts in der Straßenszene der Leonida Keys in GTA VI."},"reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Express","reelNom":"Chevrolet Express","slot":"americain","thumb":"/img/officiel/leonida-keys-02-480.webp"},{"id":"brute-stockade","nom":"Stockade","marque":"Brute","cat":"service","st":"vu","insp":"International 4700 Series","src":"Extended Look","txt":"Der gepanzerte Geldtransporter, auf demselben Fahrgestell International 4700 gebaut wie der Benson, aber mit verstärktem Aufbau samt Schießscharten. Er ist ebenso Ziel für Raubüberfälle wie Fahrzeug. Im Extended Look steht er vor einer Bankfiliale.","medias":["extended-look-stockade"],"imageAlts":{"extended-look-stockade":"Geldtransporter mitten auf der Straße, Standbild aus An Extended Look"},"reel":"https://www.google.com/search?tbm=isch&q=International%204700%20Series","reelNom":"International 4700 Series","search":"brute stockade international 4700 series","thumb":"/img/officiel/extended-look-stockade-480.webp"},{"id":"brute-tipper-6-wheels","nom":"Tipper (6 Räder)","marque":"Brute","cat":"service","st":"vu","insp":"Chevrolet Kodiak, GMC TopKick","src":"Extended Look","txt":"Der sechsrädrige Kipper von Brute auf Basis von Kodiak und TopKick: zwei Hinterachsen, Kippmulde, Größe zwischen Nutzfahrzeug und Lkw. Im Extended Look fährt er beladen über eine Baustellenpiste.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Kodiak","reelNom":"Chevrolet Kodiak","search":"brute tipper (6 roues) chevrolet kodiak, gmc topkick","slot":"americain","thumb":"/img/schemas/brute-tipper-6-wheels.svg"},{"id":"brute-utility-truck","nom":"Utility Truck","marque":"Brute","cat":"service","st":"vu","insp":"International 4700 Series","src":"Extended Look","txt":"Der Wartungs-Lkw von Brute, mit zusammengeklappter Hubarbeitsbühne auf der Ladefläche und Werkzeugkisten an den Seiten, auf einem Fahrgestell der International 4700 Series. Das ist das Fahrzeug der Trupps, die Stromleitungen reparieren. Im Extended Look steht er geparkt, Stützen ausgefahren.","reel":"https://www.google.com/search?tbm=isch&q=International%204700%20Series","reelNom":"International 4700 Series","search":"brute utility truck international 4700 series","thumb":"/img/schemas/brute-utility-truck.svg"},{"id":"declasse-granger-taxi","nom":"Granger Taxi","marque":"Declasse","cat":"service","st":"vu","insp":"Chevrolet Suburban","src":"Extended Look","txt":"Der Granger als Taxi lackiert, ein großer Suburban mit Leuchtschild auf dem Dach. Das ist das Taxi für Gruppen, das eine ganze Familie samt Gepäck mitnimmt, wenn die Limousine nicht mehr reicht. Im Extended Look wartet er vor dem Eingang eines Hotels.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Suburban","reelNom":"Chevrolet Suburban","search":"declasse granger taxi chevrolet suburban","slot":"americain","thumb":"/img/schemas/declasse-granger-taxi.svg"},{"id":"declasse-sheriff-suv","nom":"Sheriff SUV","marque":"Declasse","cat":"service","st":"comm","insp":"Chevrolet Tahoe des Sheriffs","txt":"Der SUV des Sheriff-Büros, im Einsatz außerhalb der Stadtgrenzen. Die Trennung zwischen Stadtpolizei und County-Sheriff prägt die Karte von Leonida ebenso wie die Geografie.","search":"declasse sheriff suv chevrolet tahoe de sherif","src":"Zuordnung der Community","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Tahoe%20de%20sh%C3%A9rif","reelNom":"Chevrolet Tahoe des Sheriffs","slot":"americain","thumb":"/img/schemas/declasse-sheriff-suv.svg"},{"id":"dundreary-police-landstalker-xl","nom":"Police Landstalker XL","marque":"Dundreary","cat":"service","st":"vu","insp":"Lincoln Navigator der vierten Generation","src":"Extended Look","txt":"Großer SUV in Polizeifarben, abgeleitet vom zivilen Landstalker XL. Ein Fahrzeug dieser Größe dient selten der Verfolgung: US-Behörden setzen es für Vorgesetzte, Teamtransport und sperrige Ausrüstung ein. Im Extended Look entdeckt.","reel":"https://www.google.com/search?tbm=isch&q=Lincoln%20Navigator","reelNom":"Lincoln Navigator","search":"dundreary police landstalker xl lincoln navigator quatrieme generation","slot":"americain","thumb":"/img/schemas/dundreary-police-landstalker-xl.svg"},{"id":"hvy-airtug","nom":"Airtug","marque":"HVY","cat":"service","st":"vu","insp":"Clark CT30","src":"Extended Look","txt":"Der kleine Flughafenschlepper, der die Gepäckwagen zwischen Terminal und Frachtraum zieht. Seine Form stammt vom Clark CT30, einem Flughafenfahrzeug, das niemand bemerkt, das aber überall auf dem Rollfeld unterwegs ist. Der Extended Look erwischt ihn bei der Arbeit am Flughafen von Leonida.","reel":"https://www.google.com/search?tbm=isch&q=Clark%20CT30","reelNom":"Clark CT30","search":"hvy airtug clark ct30","thumb":"/img/schemas/hvy-airtug.svg"},{"id":"hvy-biff","nom":"Biff","marque":"HVY","cat":"service","st":"vu","insp":"Kenworth T800","src":"Extended Look","txt":"Der Kipper von HVY, auf einem Kenworth-T800-Fahrgestell mit kurzer Kabine. Er fährt Kies und Erde von Baustelle zu Baustelle und ist schwer genug, um ohne zu bremsen über eine Kreuzung zu fahren. Im Extended Look steht er auf einer Baustelle.","reel":"https://www.google.com/search?tbm=isch&q=Kenworth%20T800","reelNom":"Kenworth T800","search":"hvy biff kenworth t800","thumb":"/img/schemas/hvy-biff.svg"},{"id":"hvy-forklift","nom":"Forklift","marque":"HVY","cat":"service","st":"vu","insp":"Yale GLP060VX","src":"Offizielle Screenshots","txt":"Der Gabelstapler aus Lagerhallen und von Laderampen, nach dem Vorbild eines Yale GLP060VX. Langsam, tief gebaut, kommt über keinen Bordstein, aber unverzichtbar, sobald eine Palette bewegt werden muss. Die offiziellen Screenshots zeigen ihn in einem Industriegebiet.","reel":"https://www.google.com/search?tbm=isch&q=Yale%20GLP060VX","reelNom":"Yale GLP060VX","search":"hvy forklift yale glp060vx","thumb":"/img/schemas/hvy-forklift.svg"},{"id":"jacksheepe-excavator","nom":"Excavator","marque":"Jacksheepe","cat":"service","st":"vu","insp":"Liebherr R954B HD-S, Samsung SE280LC-2","src":"Extended Look","txt":"Der Kettenbagger von Jacksheepe, eine Mischung aus Liebherr R954B HD-S und Samsung SE280LC-2. Drehbarer Oberwagen, Knickarm und eine Schaufel, breit genug, um mühelos eine Limousine umzudrehen. Im Extended Look ist er bei Erdarbeiten im Einsatz.","reel":"https://www.google.com/search?tbm=isch&q=Liebherr%20R954B%20HD-S","reelNom":"Liebherr R954B HD-S","search":"jacksheepe excavator liebherr r954b hd-s, samsung se280lc-2","thumb":"/img/schemas/jacksheepe-excavator.svg"},{"id":"mtl-flatbed","nom":"Flatbed","marque":"JoBuilt","cat":"service","st":"vu","insp":"2004 Freightliner Century Class 112","src":"Extended Look","search":"jobuilt flatbed 2004 freightliner century class 112","txt":"Der Flatbed ist ein Pritschen-Lkw, mit dem Fahrzeuge oder sperrige Ladungen transportiert werden. Unsere Datenbank ordnet diese Version JoBuilt zu und verknüpft sie mit dem Freightliner Century Class 112 von 2004. Im Extended Look hat er ein Wrack geladen, die Plattform gekippt.","reel":"https://www.google.com/search?tbm=isch&q=2004%20Freightliner%20Century%20Class%20112","reelNom":"2004 Freightliner Century Class 112","slot":"americain","thumb":"/img/schemas/mtl-flatbed.svg"},{"id":"jobuilt-hauler","nom":"Hauler","marque":"JoBuilt","cat":"service","st":"vu","insp":"Sattelzugmaschinen von Freightliner und Kenworth","src":"Offizielle Screenshots","search":"jobuilt hauler tracteurs routiers freightliner et kenworth","txt":"Der Hauler ist eine Sattelzugmaschine, der vordere Teil eines Sattelzugs. JoBuilt ist die Marke für schweres Gerät in diesem Universum. Der Hafen von Vice City und die Fernstraßen in den Norden von Leonida sind das natürliche Revier dieser Fahrzeuge. Die offiziellen Screenshots zeigen ihn angekuppelt und abfahrbereit.","reel":"https://www.google.com/search?tbm=isch&q=Tracteurs%20routiers%20Freightliner","reelNom":"Sattelzugmaschinen von Freightliner","slot":"americain","thumb":"/img/schemas/jobuilt-hauler.svg"},{"id":"jobuilt-phantom","nom":"Phantom","marque":"JoBuilt","cat":"service","st":"vu","insp":"Peterbilt 359 EXHD","src":"Erster Trailer","search":"jobuilt phantom peterbilt 359 exhd","txt":"Der Phantom ist eine Sattelzugmaschine mit Langkabine, von der Sorte, die die USA von Küste zu Küste durchquert, mit einer Schlafkoje hinter den Sitzen. Im ersten Trailer überholt er auf einer Schnellstraße.","medias":["trailer-1-phantom-003"],"imageAlts":{"trailer-1-phantom-003":"Sattelzugmaschine mit Patriot-Auflieger mitten auf der Schnellstraße, erster Trailer zu GTA VI bei etwa 00:03."},"reel":"https://www.google.com/search?tbm=isch&q=Peterbilt%20359%20EXHD","reelNom":"Peterbilt 359 EXHD","thumb":"/img/officiel/trailer-1-phantom-003-480.webp"},{"id":"jobuilt-phantom-custom","nom":"Phantom Custom","marque":"JoBuilt","cat":"service","st":"vu","insp":"GMC General 1984 mit verkleideter Schlafkabine","src":"Offizielle Screenshots","search":"jobuilt phantom custom gmc general 1984 a cabine couchette carenee","txt":"Individualisierte Version des Phantom: Chrom, zusätzliche Scheinwerfer, aufwendige Lackierung. Die Kultur der aufgemotzten Trucks ist in den USA eine lebendige Tradition, denn dort gehört das Fahrzeug oft dem Fahrer selbst. Die offiziellen Screenshots zeigen ihn auf einem Rastplatz.","reel":"https://www.google.com/search?tbm=isch&q=GMC%20General%201984%20%C3%A0%20cabine%20couchette%20car%C3%A9n%C3%A9e","reelNom":"GMC General 1984 mit verkleideter Schlafkabine","slot":"americain","thumb":"/img/schemas/jobuilt-phantom-custom.svg"},{"id":"jobuilt-rubble","nom":"Rubble","marque":"JoBuilt","cat":"service","st":"vu","insp":"Peterbilt 359 EXHD","txt":"Kipper mit vier Achsen. Baustellen gehören zum Stadtbild von Vice City, mit Maschinen, die wirklich herumfahren, statt nur herumzustehen.","search":"jobuilt rubble peterbilt 359 exhd","src":"Erster Trailer","reel":"https://www.google.com/search?tbm=isch&q=Peterbilt%20359%20EXHD","reelNom":"Peterbilt 359 EXHD","thumb":"/img/schemas/jobuilt-rubble.svg"},{"id":"maibatsu-mule","nom":"Mule","marque":"Maibatsu","cat":"service","st":"vu","insp":"Mitsubishi Fuso Canter der siebten Generation","txt":"Lkw mit Kofferaufbau auf Basis einer japanischen Kabine. Der Mule ist der Standard-Liefer- und Umzugs-Lkw der Reihe.","search":"maibatsu mule mitsubishi fuso canter septieme generation","src":"Erster Trailer","reel":"https://www.google.com/search?tbm=isch&q=Mitsubishi%20Fuso%20Canter","reelNom":"Mitsubishi Fuso Canter","slot":"japonais","thumb":"/img/schemas/maibatsu-mule.svg"},{"id":"airport-bus","nom":"Airport Bus","marque":"Unbekannte Marke","cat":"service","st":"vu","src":"Extended Look","txt":"Der Shuttle, der die Terminals abfährt, mit breiten Türen und langem Mittelgang für stehende Fahrgäste, den Koffer zu ihren Füßen. Der Hersteller ist unbekannt, und ein reales Modell wurde bisher nicht identifiziert. Im Extended Look bedient er den Flughafen von Vice City.","fam":"Flughafen-Shuttle","reel":"https://www.google.com/search?tbm=isch&q=Navette%20d%E2%80%99a%C3%A9roport","reelNom":"Flughafen-Shuttle","search":"marque inconnue airport bus navette d’aeroport","thumb":"/img/schemas/airport-bus.svg"},{"id":"amloco-ge-genesis","nom":"Amloco (GE Genesis)","marque":"Unbekannte Marke","cat":"service","st":"vu","insp":"Lokomotive GE Genesis","src":"Offizielle Screenshots","txt":"Amloco, die Eisenbahngesellschaft von Leonida, zieht ihre Personenzüge mit einer Lok nach dem Vorbild der GE Genesis: abgerundete Nase, selbsttragender Aufbau, helle Lackierung. Sie ist die Maschine für den Fernverkehr zwischen Städten, nicht für Güter. Die offiziellen Screenshots zeigen sie am Bahnsteig.","reel":"https://www.google.com/search?tbm=isch&q=Locomotive%20GE%20Genesis","reelNom":"Lokomotive GE Genesis","search":"marque inconnue amloco (ge genesis) locomotive ge genesis","thumb":"/img/schemas/amloco-ge-genesis.svg"},{"id":"dashound","nom":"Dashound","marque":"Unbekannte Marke","cat":"service","st":"vu","insp":"Reisebus MCI Renaissance E, Greyhound-Lackierung","src":"Erster Trailer","search":"marque inconnue dashound autocar mci renaissance e, livree greyhound","txt":"Der Überlandbus Dashound ist eine Konstante der Reihe, die Umsetzung eines sehr realen amerikanischen Unternehmens mit dem Windhund als Wappentier. Dieses Netz bedient Tausende Orte, die Flugzeug und Bahn aufgegeben haben. Im ersten Trailer fährt er auf der Autobahn, die komplette Lackierung ist zu sehen.","reel":"https://www.google.com/search?tbm=isch&q=Autocar%20MCI%20Renaissance%20E","reelNom":"Reisebus MCI Renaissance E","thumb":"/img/schemas/dashound.svg"},{"id":"isuzu-elf-250","nom":"Elf 250","marque":"Unbekannte Marke","cat":"service","st":"vu","insp":"Isuzu Elf 250","src":"Extended Look","txt":"Der kleine Frontlenker-Lkw von Isuzu, allgegenwärtig bei Stadtlieferungen auf der ganzen Welt. Kabine über dem Motor, Kofferaufbau hinten, winziger Wendekreis. Der Name im Spiel wurde noch nicht bekannt gegeben. Er taucht im Extended Look auf.","reel":"https://www.google.com/search?tbm=isch&q=Isuzu%20Elf%20250","reelNom":"Isuzu Elf 250","search":"marque inconnue elf 250 isuzu elf 250","slot":"japonais","thumb":"/img/schemas/isuzu-elf-250.svg"},{"id":"vapid-caracara-lifeguard","nom":"Explorer Sport Trac (Lifeguard)","marque":"Unbekannte Marke","cat":"service","st":"vu","insp":"Ford Explorer Sport Trac","txt":"Pick-up der Strandaufsicht, in Rettungslackierung mit festgezurrter Ausrüstung hinten. Der Sport Trac war ein Explorer, bei dem Ford den Kofferraum durch eine kurze Ladefläche ersetzt hatte, gebaut von 2000 bis 2010. Die Rettungsstationen von Miami Beach hatten sie jahrelang im Einsatz. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue explorer sport trac (lifeguard) ford explorer sport trac","src":"Erster Trailer","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Explorer%20Sport%20Trac","reelNom":"Ford Explorer Sport Trac","slot":"americain","thumb":"/img/schemas/vapid-caracara-lifeguard.svg"},{"id":"ford-f-series-tow-truck","nom":"F-Series Abschleppwagen","marque":"Unbekannte Marke","cat":"service","st":"vu","insp":"Ford F-Series als Abschleppwagen","src":"Extended Look","txt":"Ein Abschleppwagen auf Basis des Ford F-Series, mit sichtbarem Hydraulikarm und Seilwinde hinten. Rockstar hat ihm bisher weder einen Namen im Spiel noch einen fiktiven Hersteller gegeben. Im Extended Look ist er im Einsatz, ein Unfallwagen hängt am Seil.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20F-Series","reelNom":"Ford F-Series","search":"marque inconnue f-series depanneuse ford f-series, configuration depanneuse","slot":"americain","thumb":"/img/schemas/ford-f-series-tow-truck.svg"},{"id":"ford-f-series-flatbed","nom":"F-Series Pritschenwagen","marque":"Unbekannte Marke","cat":"service","st":"vu","insp":"Ford F-Series der sechsten Generation","src":"Erster Trailer","txt":"Ford F-Series der sechsten Generation, zum Pritschenwagen umgebaut: Die originale Ladefläche wurde durch eine nackte Plattform für sperriges Material ersetzt. Ein gängiger Umbau in Landwirtschaft und Bau. Name im Spiel nicht bekannt gegeben.","search":"marque inconnue f-series plateau ford f-series sixieme generation","reel":"https://www.google.com/search?tbm=isch&q=Ford%20F-Series","reelNom":"Ford F-Series","slot":"americain","thumb":"/img/schemas/ford-f-series-flatbed.svg"},{"id":"freight-train","nom":"Freight Train","marque":"Unbekannte Marke","cat":"service","st":"vu","insp":"Electro Motive Division, GE AC4400CW","txt":"Güterzug. Das Schienennetz durchzieht Leonida zwischen Industriegebieten, Häfen und Innenstädten, mit Bahnübergängen, die die Straße wirklich sperren.","search":"marque inconnue freight train electro motive division, ge ac4400cw","src":"Offizielle Screenshots","reel":"https://www.google.com/search?tbm=isch&q=Electro%20Motive%20Division","reelNom":"Electro Motive Division","thumb":"/img/schemas/freight-train.svg"},{"id":"chevrolet-kodiak-gmc-topkick","nom":"Kodiak / Topkick","marque":"Unbekannte Marke","cat":"service","st":"vu","insp":"Chevrolet Kodiak, GMC Topkick","src":"Extended Look","txt":"Der mittelschwere Lkw von General Motors, unter den beiden Namen Chevrolet Kodiak und GMC Topkick verkauft, mit kurzer Motorhaube und Chromgrill. Ihm wurden weder ein Name im Spiel noch ein hauseigener Hersteller zugewiesen. Im Extended Look ist er als Baustellenfahrzeug zu sehen.","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Kodiak","reelNom":"Chevrolet Kodiak","search":"marque inconnue kodiak / topkick chevrolet kodiak, gmc topkick","slot":"americain","thumb":"/img/schemas/chevrolet-kodiak-gmc-topkick.svg"},{"id":"international-s-series-semi-truck","nom":"S-Series","marque":"Unbekannte Marke","cat":"service","st":"vu","insp":"International S-Series, Sattelzugmaschine","src":"Zweiter Trailer","txt":"Eine Sattelzugmaschine International S-Series, erkennbar an ihrem eckigen Kühlergrill und der hohen Kabine über dem Motor. Sie hat weder einen Namen im Spiel noch einen fiktiven Hersteller bekommen. Im zweiten Trailer fährt sie mit angehängtem Auflieger über die Autobahn.","reel":"https://www.google.com/search?tbm=isch&q=International%20S-Series","reelNom":"International S-Series","search":"marque inconnue s-series international s-series, tracteur routier","thumb":"/img/schemas/international-s-series-semi-truck.svg"},{"id":"chevrolet-silverado-6500-hd","nom":"Silverado 6500 HD","marque":"Unbekannte Marke","cat":"service","st":"vu","insp":"Chevrolet Silverado 6500 HD","src":"Extended Look","txt":"Mittelschwerer Lkw, weit jenseits des privaten Pick-ups: ein Fahrgestell mit Fahrerhaus für gewerbliche Aufbauten wie Abschleppwagen, Kipper oder Pritsche. Im Extended Look entdeckt. Sein Name im Spiel wurde nicht bekannt gegeben.","search":"marque inconnue silverado 6500 hd chevrolet silverado 6500 hd","reel":"https://www.google.com/search?tbm=isch&q=Chevrolet%20Silverado%206500%20HD","reelNom":"Chevrolet Silverado 6500 HD","slot":"americain","thumb":"/img/schemas/chevrolet-silverado-6500-hd.svg"},{"id":"dodge-grand-caravan-taxi","nom":"Taxi Grand Caravan","marque":"Unbekannte Marke","cat":"service","st":"vu","insp":"Dodge Grand Caravan 2011-2020, Chrysler Town & Country 2011-2016","src":"Offizielle Screenshots","txt":"Der Van in Taxi-Lackierung, übernommen vom Dodge Grand Caravan und seinem Cousin, dem Chrysler Town & Country. In Miami übernehmen diese gelben Vans die Fahrten zum Flughafen, mit Schiebetüren und einem Kofferraum voller Koffer. Die offiziellen Screenshots erwischen ihn im Verkehr.","reel":"https://www.google.com/search?tbm=isch&q=Dodge%20Grand%20Caravan","reelNom":"Dodge Grand Caravan","search":"marque inconnue taxi grand caravan dodge grand caravan 2011-2020, chrysler town & country 2011-2016","slot":"americain","thumb":"/img/schemas/dodge-grand-caravan-taxi.svg"},{"id":"mtl-packer","nom":"Packer","marque":"MTL","cat":"service","st":"vu","insp":"1994 International 9000/9200","src":"Zweiter Trailer","search":"mtl packer 1994 international 9000/9200","txt":"Der Packer ist ein Autotransporter, mit dem Neuwagen oder beschlagnahmte Fahrzeuge transportiert werden. Sein zweistöckiger Auflieger macht ihn unverwechselbar. Er ist im zweiten Trailer erfasst; die Identifizierung stammt von der Community, einen Namen hat das Studio nicht genannt.","reel":"https://www.google.com/search?tbm=isch&q=1994%20International%209000%2F9200","reelNom":"1994 International 9000/9200","thumb":"/img/schemas/mtl-packer.svg"},{"id":"nagasaki-caddy","nom":"Caddy","marque":"Nagasaki","cat":"service","st":"vu","src":"Extended Look","txt":"Das Golfcart von Nagasaki, langsam und unverwüstlich, kehrt in einer Kulisse zurück, die wie dafür gemacht ist: die gepflegten Golfplätze von Leonida. Ihm ist kein bestimmtes reales Modell zugeordnet – logisch für ein so allgemeines Gefährt. Im Extended Look fährt es zwischen zwei Löchern.","fam":"Golfcart","reel":"https://www.google.com/search?tbm=isch&q=Voiturette%20de%20golf","reelNom":"Golfcart","search":"nagasaki caddy voiturette de golf","thumb":"/img/schemas/nagasaki-caddy.svg"},{"id":"vapid-benson","nom":"Benson","marque":"Vapid","cat":"service","st":"vu","insp":"International 4700 Delivery Truck Chassis","txt":"Mittelgroßer Lkw mit Kofferaufbau, größer als der Mule und wendiger als ein Sattelzug. Traditionell dient er für Raubüberfälle, bei denen viel Laderaum gebraucht wird.","search":"vapid benson international 4700 delivery truck chassis","src":"Extended Look","reel":"https://www.google.com/search?tbm=isch&q=International%204700%20Delivery%20Truck%20Chassis","reelNom":"International 4700 Delivery Truck Chassis","thumb":"/img/schemas/vapid-benson.svg"},{"id":"vapid-police-cruiser-interceptor","nom":"Police Cruiser (Interceptor)","marque":"Vapid","cat":"service","st":"vu","insp":"Ford Taurus","txt":"Streifen-SUV, in den 2010er-Jahren als Ersatz für die Limousine zum Standard der US-Polizei geworden. Größerer Kofferraum, mehr Bodenfreiheit.","search":"vapid police cruiser (interceptor) ford taurus","src":"Erster Trailer","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Taurus","reelNom":"Ford Taurus","slot":"americain","thumb":"/img/schemas/vapid-police-cruiser-interceptor.svg"},{"id":"vapid-police-cruiser-stanier-le","nom":"Police Cruiser (Stanier LE)","marque":"Vapid","cat":"service","st":"vu","insp":"Ford Crown Victoria","src":"Erster Trailer","txt":"Klassischer Streifenwagen auf Basis des Stanier LE. Der Crown Victoria war zwanzig Jahre lang bei fast allen US-Polizeibehörden im Einsatz: Leiterrahmen, Heckantrieb, günstig zu reparieren nach einem Crash. Nicht zu verwechseln mit dem Police Ghost, der dieselbe Basis unter einer unauffälligen Lackierung nutzt.","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Crown%20Victoria","reelNom":"Ford Crown Victoria","search":"vapid police cruiser (stanier le) ford crown victoria","slot":"americain","thumb":"/img/schemas/vapid-police-cruiser-stanier-le.svg"},{"id":"vapid-police-ghost","nom":"Police Ghost (Stanier LE)","marque":"Vapid","cat":"service","st":"vu","insp":"Ford Crown Victoria","src":"Zweiter Trailer","txt":"Der klassische Streifenwagen von Vice City, auf Basis des Stanier. Der Crown Victoria, dessen Züge er übernimmt, war über zwanzig Jahre lang der Standard-Streifenwagen der USA: Heckantrieb, Leiterrahmen, unverwüstlich. Der Name Ghost verweist auf unauffällige Einheiten, deren Beschriftung man erst erkennt, wenn man schon zu nah dran ist.","search":"vapid police ghost (stanier le) ford crown victoria","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Crown%20Victoria","reelNom":"Ford Crown Victoria","slot":"americain","thumb":"/img/schemas/vapid-police-ghost.svg"},{"id":"ford-explorer-police","nom":"Police Montagne","marque":"Vapid","cat":"service","st":"vu","insp":"Ford Explorer der sechsten Generation","src":"Erster Trailer","txt":"Der Streifen-SUV hat seit den 2010er-Jahren in den meisten US-Polizeibehörden die Limousine ersetzt: tieferer Kofferraum, mehr Bodenfreiheit, bessere Sicht auf den Verkehr. Der Polizei-Montagne übernimmt diese Silhouette und taucht schon im ersten Trailer in den Straßen von Vice City auf.","search":"vapid police montagne ford explorer sixieme generation","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Explorer","reelNom":"Ford Explorer","slot":"americain","thumb":"/img/schemas/ford-explorer-police.svg"},{"id":"vapid-taxi","nom":"Stanier Taxi","marque":"Vapid","cat":"service","st":"vu","insp":"Ford Crown Victoria","txt":"Der Crown Victoria in Taxi-Lackierung, mit Schachbrettmuster an den Flanken und Schild auf dem Dach. Das ist die Flottenlimousine schlechthin: riesiger Kofferraum, Leiterrahmen, unverwüstliche Technik, die sich günstig warten lässt. Im ersten Trailer fährt er durch den Verkehr von Vice City.","search":"vapid stanier taxi ford crown victoria","src":"Erster Trailer","reel":"https://www.google.com/search?tbm=isch&q=Ford%20Crown%20Victoria","reelNom":"Ford Crown Victoria","slot":"americain","thumb":"/img/schemas/vapid-taxi.svg"},{"id":"vapid-tow-truck","nom":"Tow Truck","marque":"Vapid","cat":"service","st":"vu","insp":"International Harvester S-Series aus den 80ern","src":"Erster Trailer","search":"vapid tow truck international harvester serie s des annees 80","txt":"Der Abschleppwagen mit Plattform oder Kran gehört zum amerikanischen Stadtbild, zwischen Pannenhilfe und dem Abschleppen falsch geparkter Fahrzeuge. Als Quelle für diesen Tow Truck gilt der erste Trailer, in dem das Fahrzeug nicht benannt wird.","reel":"https://www.google.com/search?tbm=isch&q=International%20Harvester%20s%C3%A9rie%20S%20des%20ann%C3%A9es%2080","reelNom":"International Harvester S-Series aus den 80ern","thumb":"/img/schemas/vapid-tow-truck.svg"},{"id":"endurex-race-bike","nom":"Race Bike","marque":"Endurex","cat":"divers","st":"vu","insp":"Pinarello Dogma","src":"Extended Look","txt":"Das Wettkampf-Rennrad von Endurex, nach einem Pinarello Dogma gezeichnet: Carbonrahmen mit asymmetrischen Kettenstreben, Rennlenker, Hochprofilfelgen. Es ist das schnellste Zweirad ohne Motor im Spiel. Der Extended Look erwischt es mitten im Sprint.","reel":"https://www.google.com/search?tbm=isch&q=Pinarello%20Dogma","reelNom":"Pinarello Dogma","search":"endurex race bike pinarello dogma","thumb":"/img/schemas/endurex-race-bike.svg"},{"id":"bmx","nom":"BMX","marque":"Unbekannte Marke","cat":"divers","st":"vu","insp":"BMX-Rad","src":"Offizielle Screenshots","search":"marque inconnue bmx bmx bike","txt":"Das Fahrrad ist im Bild – sein Name nirgends. Dieses Rad mit kleinen Laufrädern, in den 70ern entstanden, als kalifornische Kinder Motocross nachahmten, ist heute olympische Sportart. Die Skateparks von Miami machen es zu einem glaubwürdigen Stadtgefährt und zugleich zu einem Spielzeug.","reel":"https://www.google.com/search?tbm=isch&q=BMX%20bike","reelNom":"BMX-Rad","thumb":"/img/schemas/bmx.svg"},{"id":"cruiser","nom":"Cruiser","marque":"Unbekannte Marke","cat":"divers","st":"vu","insp":"Beach-Cruiser, Strandfahrrad aus den 30ern","src":"Offizielle Screenshots","search":"marque inconnue cruiser beach cruiser, velo de plage des annees 30","txt":"Das Strandfahrrad mit hohem Lenker und breitem Sattel ist in den Bildern zu entdecken, ohne zugehörige Bildunterschrift. Es ist das Sinnbild des Küsten-Floridas: keine Gänge, aufrechte Sitzhaltung, breite Reifen für den festgefahrenen Sand der Promenaden.","reel":"https://www.google.com/search?tbm=isch&q=Beach%20cruiser","reelNom":"Beach-Cruiser","thumb":"/img/schemas/cruiser.svg"},{"id":"lombike","nom":"LomBike","marque":"Unbekannte Marke","cat":"divers","st":"vu","insp":"CitiBike Miami E-Bikes","src":"Offizielle Screenshots","search":"marque inconnue lombike citibike miami e-bikes","txt":"Praktisches Stadtrad ohne sportliche Ambitionen. Diese Art Fahrrad dient vor allem für kurze Wege und Lieferungen in der Nachbarschaft. Dass es im Spiel ist, ist bisher nur eine Vermutung.","reel":"https://www.google.com/search?tbm=isch&q=CitiBike%20Miami%20E-Bikes","reelNom":"CitiBike Miami E-Bikes","thumb":"/img/schemas/lombike.svg"},{"id":"monorail-de-vice-city","nom":"Vice-City-Monorail","marque":"Unbekannte Marke","cat":"divers","st":"vu","insp":"Innovia APM 100, Metromover von Miami","src":"Zweiter Trailer","search":"marque inconnue monorail de vice city innovia apm 100, metromover de miami","txt":"Die städtische Einschienenbahn ist eine Besonderheit Miamis: Seit den 80ern betreibt die Stadt ein automatisches Hochbahnnetz, das die Innenstadt bedient. Dieses in den USA seltene Verkehrsmittel gehört zum Erscheinungsbild der Stadt. Unsere Datenbank ordnet diese Einschienenbahn dem zweiten Trailer zu und nennt den Innovia APM 100 des Metromover als Inspiration.","reel":"https://www.google.com/search?tbm=isch&q=Innovia%20APM%20100","reelNom":"Innovia APM 100","thumb":"/img/schemas/monorail-de-vice-city.svg"},{"id":"scorcher","nom":"Scorcher","marque":"Unbekannte Marke","cat":"divers","st":"vu","insp":"Saracen Zen, Rockshox Domain 180mm","src":"Offizielle Screenshots","search":"marque inconnue scorcher saracen zen, rockshox domain 180mm","txt":"Das Scorcher ist ein gefedertes Mountainbike, gedacht für Wege und Parks statt für die Straße. Der Mount Kalaga National Park, auf unserer Karte verzeichnet, ist genau die Art Ort, an der so ein Rad richtig Sinn ergibt. Die offiziellen Screenshots zeigen es an eine niedrige Mauer gelehnt.","reel":"https://www.google.com/search?tbm=isch&q=Saracen%20Zen","reelNom":"Saracen Zen","thumb":"/img/schemas/scorcher.svg"},{"id":"electric-scooter","nom":"E-Scooter","marque":"Unbekannte Marke","cat":"divers","st":"vu","insp":"BIRD One","src":"Extended Look","txt":"Der E-Scooter zum Ausleihen, kopiert vom BIRD One, den man in Miami auf jedem Gehweg abgestellt findet. Niedriges Trittbrett, gerader Lenker, geringe Reichweite und gedrosseltes Tempo. Im Extended Look stehen mehrere davon an einer Verleihstation.","reel":"https://www.google.com/search?tbm=isch&q=BIRD%20One","reelNom":"BIRD One","search":"marque inconnue trottinette electrique bird one","thumb":"/img/schemas/electric-scooter.svg"},{"id":"vcia-train","nom":"VCIA Train","marque":"Unbekannte Marke","cat":"divers","st":"comm","insp":null,"src":"Zuordnung der Community","search":"marque inconnue vcia train navette automatique d’aeroport","txt":"Der Shuttle, der die Terminals verbindet, bleibt eine Vermutung der Community, ohne bekannten Namen. Diese fahrerlosen Züge gehören zur Standardausstattung großer US-Flughäfen, und der internationale Flughafen von Vice City ist auf unserer Karte.","fam":"Automatischer Flughafen-Shuttle","reel":"https://www.google.com/search?tbm=isch&q=Navette%20automatique%20d%E2%80%99a%C3%A9roport","reelNom":"Automatischer Flughafen-Shuttle","thumb":"/img/schemas/vcia-train.svg"},{"id":"vcmm-train","nom":"VCMM Train","marque":"Unbekannte Marke","cat":"divers","st":"vu","insp":"Metrorail von Miami","src":"Zweiter Trailer","search":"marque inconnue vcmm train metrorail de miami","txt":"Der Stadtzug von Vice City fällt im Bild auf, sein Name wurde aber nicht veröffentlicht. Unsere Karte verzeichnet mehrere Stationen, darunter die am Flughafen und die am Vice City Arts Center – ein Hinweis auf ein Netz, das die Stadt wirklich bedient und nicht nur Kulisse ist.","reel":"https://www.google.com/search?tbm=isch&q=Metrorail%20de%20Miami","reelNom":"Metrorail von Miami","thumb":"/img/schemas/vcmm-train.svg"}];
